{
  "name": "Nostalgic Dots & Boxes",
  "description": "A classic 2-player strategy game with a nostalgic graph paper aesthetic. Players take turns connecting dots to close squares and claim territory."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export const GRID_SIZE_DOTS = 8; // Reduced to 8x8 for better playability on screens, though prompt said 16. 
// Note: Prompt asked for 16x16. I will implement 16x16 but visually it might be dense. 
// Let's stick to the prompt's 16x16 requirement strictly.
export const GRID_ROWS = 16;
export const GRID_COLS = 16;

export const PLAYER_X = 'X';
export const PLAYER_O = 'O';

export type Player = typeof PLAYER_X | typeof PLAYER_O;
export type SquareOwner = Player | null;

// Visual styling constants
export const DOT_SIZE = 6; // px
export const LINE_THICKNESS = 4; // px
export const HIT_AREA = 20; // px, for easier clicking
export const CELL_SIZE = 36; // px, size of the square

import { Player, SquareOwner } from './constants';

export interface GameState {
  hLines: boolean[][]; // [row][col] - horizontal lines
  vLines: boolean[][]; // [row][col] - vertical lines
  squares: SquareOwner[][]; // [row][col] - ownership of squares
  currentPlayer: Player;
  scores: Record<Player, number>;
  winner: Player | 'Draw' | null;
  moveHistory: string[]; // For potential undo or debug
}

export type LineType = 'horizontal' | 'vertical';

import React from 'react';
import { Player, PLAYER_X, PLAYER_O } from '../constants';

interface ScoreBoardProps {
  scores: Record<Player, number>;
  currentPlayer: Player;
  winner: Player | 'Draw' | null;
  onReset: () => void;
}

const ScoreBoard: React.FC<ScoreBoardProps> = ({ scores, currentPlayer, winner, onReset }) => {
  return (
    <div className="w-full max-w-2xl mx-auto mb-4 px-4">
      <div className="bg-white/80 backdrop-blur-sm border-2 border-slate-300 rounded-lg shadow-sm p-4 flex flex-col sm:flex-row items-center justify-between gap-4">

        {/* Player X Score */}
        <div className={`flex items-center gap-3 px-4 py-2 rounded-lg transition-colors duration-300 ${currentPlayer === PLAYER_X && !winner ? 'bg-blue-100 border-blue-200 border' : ''}`}>
          <div className="w-8 h-8 flex items-center justify-center text-2xl font-bold text-blue-600">
            X
          </div>
          <div className="flex flex-col">
            <span className="text-xs uppercase tracking-wider text-slate-500 font-semibold">Player X</span>
            <span className="text-2xl font-bold leading-none">{scores[PLAYER_X]}</span>
          </div>
        </div>

        {/* Game Status */}
        <div className="flex flex-col items-center">
          {winner ? (
            <div className="text-xl font-bold text-green-600 animate-bounce">
              {winner === 'Draw' ? 'It\'s a Draw!' : `Player ${winner} Wins!`}
            </div>
          ) : (
            <div className="text-lg text-slate-600">
              <span className="font-bold text-slate-800">Player {currentPlayer}'s</span> Turn
            </div>
          )}
          <button 
            onClick={onReset}
            className="mt-2 px-4 py-1 text-sm bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-full border border-slate-300 transition-colors"
          >
            Reset Game
          </button>
        </div>

        {/* Player O Score */}
        <div className={`flex items-center gap-3 px-4 py-2 rounded-lg transition-colors duration-300 ${currentPlayer === PLAYER_O && !winner ? 'bg-red-100 border-red-200 border' : ''}`}>
          <div className="flex flex-col items-end">
            <span className="text-xs uppercase tracking-wider text-slate-500 font-semibold">Player O</span>
            <span className="text-2xl font-bold leading-none">{scores[PLAYER_O]}</span>
          </div>
          <div className="w-8 h-8 flex items-center justify-center text-2xl font-bold text-red-500">
            O
          </div>
        </div>

      </div>
    </div>
  );
};

export default ScoreBoard;

import React, { memo } from 'react';
import { GRID_ROWS, GRID_COLS, PLAYER_X, PLAYER_O, CELL_SIZE, LINE_THICKNESS } from '../constants';
import { GameState, LineType } from '../types';

interface GridProps {
  gameState: GameState;
  onLineClick: (type: LineType, row: number, col: number) => void;
}

// Helper to check if a line is filled
const isHLineFilled = (gameState: GameState, r: number, c: number) => gameState.hLines[r]?.[c];
const isVLineFilled = (gameState: GameState, r: number, c: number) => gameState.vLines[r]?.[c];

const Grid: React.FC<GridProps> = ({ gameState, onLineClick }) => {
  // We construct the grid using a flex column layout of rows.
  // Each "Visual Row" consists of dots and Horizontal Lines.
  // Between Visual Rows, we have Vertical Lines and Squares.

  const renderHorizontalRow = (rowIndex: number) => {
    const items = [];
    for (let col = 0; col < GRID_COLS; col++) {
      // The Dot
      items.push(
        <div key={`dot-${rowIndex}-${col}`} className="relative z-20 flex-shrink-0">
          <div className="w-2 h-2 sm:w-3 sm:h-3 rounded-full bg-slate-800 shadow-sm transition-transform hover:scale-150" />
        </div>
      );

      // The Horizontal Line (if not last column)
      if (col < GRID_COLS - 1) {
        const isFilled = isHLineFilled(gameState, rowIndex, col);
        const lastMove = false; // Could track last move for animation highlighting

        items.push(
          <div 
            key={`h-${rowIndex}-${col}`}
            className="relative flex items-center justify-center"
            style={{ width: CELL_SIZE, height: '12px' }} // Height is hit area
            onClick={() => !isFilled && !gameState.winner && onLineClick('horizontal', rowIndex, col)}
          >
            {/* Hit area helper */}
            <div className={`absolute w-full h-full cursor-pointer z-10 hover:bg-blue-200/30 rounded transition-colors ${!isFilled && !gameState.winner ? 'hover:opacity-100' : 'hover:opacity-0'} opacity-0`} />

            {/* The visible line */}
            <div 
              className={`h-1 rounded-full transition-all duration-300 ease-out ${
                isFilled 
                  ? 'bg-slate-800 w-full opacity-100' 
                  : 'bg-slate-300 w-full opacity-0'
              }`}
            />
          </div>
        );
      }
    }
    return (
      <div key={`row-h-${rowIndex}`} className="flex items-center">
        {items}
      </div>
    );
  };

  const renderVerticalRow = (rowIndex: number) => {
    // This row contains Vertical Lines and Squares
    // rowIndex here corresponds to the square row index (0 to GRID_ROWS - 2)
    const items = [];

    for (let col = 0; col < GRID_COLS; col++) {
      // Vertical Line
      const isFilled = isVLineFilled(gameState, rowIndex, col);

      items.push(
        <div 
          key={`v-${rowIndex}-${col}`}
          className="relative flex flex-col items-center justify-start flex-shrink-0"
          style={{ height: CELL_SIZE, width: '12px' }} // Width is hit area
          onClick={() => !isFilled && !gameState.winner && onLineClick('vertical', rowIndex, col)}
        >
          {/* Hit area helper */}
          <div className={`absolute w-full h-full cursor-pointer z-10 hover:bg-blue-200/30 rounded transition-colors ${!isFilled && !gameState.winner ? 'hover:opacity-100' : 'hover:opacity-0'} opacity-0`} />

          {/* The visible line */}
          <div 
            className={`w-1 rounded-full transition-all duration-300 ease-out ${
              isFilled 
                ? 'bg-slate-800 h-full opacity-100' 
                : 'bg-slate-300 h-full opacity-0'
            }`}
          />
        </div>
      );

      // The Square (if not last column)
      if (col < GRID_COLS - 1) {
        const owner = gameState.squares[rowIndex]?.[col];
        items.push(
          <div 
            key={`sq-${rowIndex}-${col}`}
            className="flex items-center justify-center relative"
            style={{ width: CELL_SIZE, height: CELL_SIZE }}
          >
            {owner && (
              <span className={`text-2xl sm:text-3xl font-bold select-none animate-bounce-in ${
                owner === PLAYER_X ? 'text-blue-600' : 'text-red-500'
              }`}>
                {owner}
              </span>
            )}
          </div>
        );
      }
    }

    return (
      <div key={`row-v-${rowIndex}`} className="flex items-start">
        {items}
      </div>
    );
  };

  return (
    <div className="inline-block p-4 sm:p-8 bg-white border border-slate-200 shadow-xl rounded-sm select-none">
      {Array.from({ length: GRID_ROWS }).map((_, r) => (
        <React.Fragment key={r}>
          {renderHorizontalRow(r)}
          {r < GRID_ROWS - 1 && renderVerticalRow(r)}
        </React.Fragment>
      ))}
    </div>
  );
};

export default memo(Grid);

import React, { useState, useCallback, useEffect } from 'react';
import { 
  GRID_ROWS, 
  GRID_COLS, 
  PLAYER_X, 
  PLAYER_O, 
  Player, 
  SquareOwner 
} from './constants';
import { GameState, LineType } from './types';
import Grid from './components/Grid';
import ScoreBoard from './components/ScoreBoard';

// Initial state creation
const createInitialState = (): GameState => {
  // H lines: GRID_ROWS x (GRID_COLS - 1)
  const hLines = Array(GRID_ROWS).fill(null).map(() => Array(GRID_COLS - 1).fill(false));

  // V lines: (GRID_ROWS - 1) x GRID_COLS
  const vLines = Array(GRID_ROWS - 1).fill(null).map(() => Array(GRID_COLS).fill(false));

  // Squares: (GRID_ROWS - 1) x (GRID_COLS - 1)
  const squares = Array(GRID_ROWS - 1).fill(null).map(() => Array(GRID_COLS - 1).fill(null));

  return {
    hLines,
    vLines,
    squares,
    currentPlayer: PLAYER_X,
    scores: { [PLAYER_X]: 0, [PLAYER_O]: 0 },
    winner: null,
    moveHistory: []
  };
};

function App() {
  const [gameState, setGameState] = useState<GameState>(createInitialState);
  const [isGameEnded, setIsGameEnded] = useState(false);

  const resetGame = () => {
    setGameState(createInitialState());
    setIsGameEnded(false);
  };

  const checkGameEnd = useCallback((squares: SquareOwner[][], scores: Record<Player, number>) => {
    const totalSquares = (GRID_ROWS - 1) * (GRID_COLS - 1);
    const filledSquares = scores[PLAYER_X] + scores[PLAYER_O];

    if (filledSquares === totalSquares) {
      setIsGameEnded(true);
      if (scores[PLAYER_X] > scores[PLAYER_O]) return PLAYER_X;
      if (scores[PLAYER_O] > scores[PLAYER_X]) return PLAYER_O;
      return 'Draw';
    }
    return null;
  }, []);

  const handleLineClick = useCallback((type: LineType, r: number, c: number) => {
    setGameState(prev => {
      // 1. Validate move
      if (type === 'horizontal') {
        if (prev.hLines[r][c]) return prev; // Already taken
      } else {
        if (prev.vLines[r][c]) return prev; // Already taken
      }

      // 2. Clone state deeper for mutation
      const newHLines = prev.hLines.map(row => [...row]);
      const newVLines = prev.vLines.map(row => [...row]);
      const newSquares = prev.squares.map(row => [...row]);
      let newScores = { ...prev.scores };
      let squareCompleted = false;

      // 3. Mark the line
      if (type === 'horizontal') {
        newHLines[r][c] = true;
      } else {
        newVLines[r][c] = true;
      }

      // 4. Check for completed squares
      // If Horizontal line at r, c:
      // Potential squares are [r-1][c] (above) and [r][c] (below)
      if (type === 'horizontal') {
        // Check Square Above
        if (r > 0) {
          // Square at r-1, c
          // Needs: hLines[r-1][c], hLines[r][c], vLines[r-1][c], vLines[r-1][c+1]
          if (
            newHLines[r-1][c] && 
            newHLines[r][c] && 
            newVLines[r-1][c] && 
            newVLines[r-1][c+1]
          ) {
            newSquares[r-1][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
          }
        }
        // Check Square Below
        if (r < GRID_ROWS - 1) {
          // Square at r, c
          if (
            newHLines[r][c] && 
            newHLines[r+1][c] && 
            newVLines[r][c] && 
            newVLines[r][c+1]
          ) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
          }
        }
      } 
      // If Vertical line at r, c:
      // Potential squares are [r][c-1] (left) and [r][c] (right)
      else {
        // Check Square Left
        if (c > 0) {
          // Square at r, c-1
          if (
            newHLines[r][c-1] && 
            newHLines[r+1][c-1] && 
            newVLines[r][c-1] && 
            newVLines[r][c]
          ) {
            newSquares[r][c-1] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
          }
        }
        // Check Square Right
        if (c < GRID_COLS - 1) {
          // Square at r, c
          if (
            newHLines[r][c] && 
            newHLines[r+1][c] && 
            newVLines[r][c] && 
            newVLines[r][c+1]
          ) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
          }
        }
      }

      // 5. Determine next player and winner
      const winner = checkGameEnd(newSquares, newScores);
      const nextPlayer = squareCompleted ? prev.currentPlayer : (prev.currentPlayer === PLAYER_X ? PLAYER_O : PLAYER_X);

      return {
        ...prev,
        hLines: newHLines,
        vLines: newVLines,
        squares: newSquares,
        scores: newScores,
        currentPlayer: nextPlayer,
        winner: winner
      };
    });
  }, [checkGameEnd]);

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <header className="pt-6 pb-2 px-4 text-center z-10">
        <h1 className="text-4xl sm:text-5xl font-bold text-slate-800 tracking-tight" style={{ textShadow: '2px 2px 0px rgba(0,0,0,0.1)' }}>
          Dots & Boxes
        </h1>
        <p className="text-slate-500 mt-2 text-lg">Connect dots to claim squares!</p>
      </header>

      {/* Scoreboard */}
      <ScoreBoard 
        scores={gameState.scores} 
        currentPlayer={gameState.currentPlayer} 
        winner={gameState.winner}
        onReset={resetGame}
      />

      {/* Game Grid Container - Scrollable */}
      <main className="flex-1 game-scroll overflow-auto flex items-start justify-center p-4 sm:p-8">
         <Grid gameState={gameState} onLineClick={handleLineClick} />
      </main>

      {/* Footer Instructions (Optional) */}
      <footer className="p-4 text-center text-slate-400 text-sm">
        {isGameEnded ? "Game Over! Press Reset to play again." : `Current Turn: Player ${gameState.currentPlayer}`}
      </footer>
    </div>
  );
}

export default App;

export const GRID_SIZE_DOTS = 8; // Reduced to 8x8 for better playability on screens, though prompt said 16. 
// Note: Prompt asked for 16x16. I will implement 16x16 but visually it might be dense. 
// Let's stick to the prompt's 16x16 requirement strictly.
export const GRID_ROWS = 16;
export const GRID_COLS = 16;

export const PLAYER_X = 'X';
export const PLAYER_O = 'O';

export type Player = typeof PLAYER_X | typeof PLAYER_O;
export type SquareOwner = Player | null;

// Visual styling constants
export const DOT_SIZE = 6; // px
export const LINE_THICKNESS = 4; // px
export const HIT_AREA = 20; // px, for easier clicking
export const CELL_SIZE = 36; // px, size of the square
export const CORNER_SIZE = 16; // px, width/height of the corners (dots/intersections)

import React, { memo } from 'react';
import { GRID_ROWS, GRID_COLS, PLAYER_X, PLAYER_O, CELL_SIZE, CORNER_SIZE } from '../constants';
import { GameState, LineType } from '../types';

interface GridProps {
  gameState: GameState;
  onLineClick: (type: LineType, row: number, col: number) => void;
}

// Helper to check if a line is filled
const isHLineFilled = (gameState: GameState, r: number, c: number) => gameState.hLines[r]?.[c];
const isVLineFilled = (gameState: GameState, r: number, c: number) => gameState.vLines[r]?.[c];

const Grid: React.FC<GridProps> = ({ gameState, onLineClick }) => {
  // We construct the grid using a flex column layout of rows.
  // Each "Visual Row" consists of dots and Horizontal Lines.
  // Between Visual Rows, we have Vertical Lines and Squares.

  const renderHorizontalRow = (rowIndex: number) => {
    const items = [];
    for (let col = 0; col < GRID_COLS; col++) {
      // The Dot
      items.push(
        <div 
          key={`dot-${rowIndex}-${col}`} 
          className="relative z-20 flex-shrink-0 flex items-center justify-center"
          style={{ width: CORNER_SIZE, height: CORNER_SIZE }}
        >
          <div className="w-2 h-2 sm:w-3 sm:h-3 rounded-full bg-slate-800 shadow-sm transition-transform hover:scale-150" />
        </div>
      );

      // The Horizontal Line (if not last column)
      if (col < GRID_COLS - 1) {
        const isFilled = isHLineFilled(gameState, rowIndex, col);

        items.push(
          <div 
            key={`h-${rowIndex}-${col}`}
            className="relative flex items-center justify-center flex-shrink-0"
            style={{ width: CELL_SIZE, height: CORNER_SIZE }} // Height matches corner size for alignment
            onClick={() => !isFilled && !gameState.winner && onLineClick('horizontal', rowIndex, col)}
          >
            {/* Hit area helper */}
            <div 
              className={`absolute left-0 right-0 h-4 cursor-pointer z-10 hover:bg-blue-200/30 rounded transition-colors ${!isFilled && !gameState.winner ? 'hover:opacity-100' : 'hover:opacity-0'} opacity-0`} 
              style={{ top: '50%', transform: 'translateY(-50%)' }}
            />

            {/* The visible line */}
            <div 
              className={`h-1 rounded-full transition-all duration-300 ease-out ${
                isFilled 
                  ? 'bg-slate-800 w-full opacity-100' 
                  : 'bg-slate-300 w-full opacity-0'
              }`}
            />
          </div>
        );
      }
    }
    return (
      <div key={`row-h-${rowIndex}`} className="flex items-center">
        {items}
      </div>
    );
  };

  const renderVerticalRow = (rowIndex: number) => {
    // This row contains Vertical Lines and Squares
    // rowIndex here corresponds to the square row index (0 to GRID_ROWS - 2)
    const items = [];

    for (let col = 0; col < GRID_COLS; col++) {
      // Vertical Line
      const isFilled = isVLineFilled(gameState, rowIndex, col);

      items.push(
        <div 
          key={`v-${rowIndex}-${col}`}
          className="relative flex flex-col items-center justify-start flex-shrink-0"
          style={{ height: CELL_SIZE, width: CORNER_SIZE }} // Width matches CORNER_SIZE
          onClick={() => !isFilled && !gameState.winner && onLineClick('vertical', rowIndex, col)}
        >
          {/* Hit area helper */}
          <div 
            className={`absolute top-0 bottom-0 w-4 cursor-pointer z-10 hover:bg-blue-200/30 rounded transition-colors ${!isFilled && !gameState.winner ? 'hover:opacity-100' : 'hover:opacity-0'} opacity-0`}
            style={{ left: '50%', transform: 'translateX(-50%)' }}
          />

          {/* The visible line */}
          <div 
            className={`w-1 rounded-full transition-all duration-300 ease-out ${
              isFilled 
                ? 'bg-slate-800 h-full opacity-100' 
                : 'bg-slate-300 h-full opacity-0'
            }`}
          />
        </div>
      );

      // The Square (if not last column)
      if (col < GRID_COLS - 1) {
        const owner = gameState.squares[rowIndex]?.[col];
        items.push(
          <div 
            key={`sq-${rowIndex}-${col}`}
            className="flex items-center justify-center relative flex-shrink-0"
            style={{ width: CELL_SIZE, height: CELL_SIZE }}
          >
            {owner && (
              <span className={`text-2xl sm:text-3xl font-bold select-none animate-bounce-in ${
                owner === PLAYER_X ? 'text-blue-600' : 'text-red-500'
              }`}>
                {owner}
              </span>
            )}
          </div>
        );
      }
    }

    return (
      <div key={`row-v-${rowIndex}`} className="flex items-start">
        {items}
      </div>
    );
  };

  return (
    <div className="inline-block p-4 sm:p-8 bg-white border border-slate-200 shadow-xl rounded-sm select-none">
      {Array.from({ length: GRID_ROWS }).map((_, r) => (
        <React.Fragment key={r}>
          {renderHorizontalRow(r)}
          {r < GRID_ROWS - 1 && renderVerticalRow(r)}
        </React.Fragment>
      ))}
    </div>
  );
};

export default memo(Grid);

import React from 'react';
import { Player, PLAYER_X, PLAYER_O } from '../constants';

interface ScoreBoardProps {
  scores: Record<Player, number>;
  currentPlayer: Player;
  winner: Player | 'Draw' | null;
  onReset: () => void;
}

const ScoreBoard: React.FC<ScoreBoardProps> = ({ scores, currentPlayer, winner, onReset }) => {
  return (
    <div className="w-full max-w-2xl mx-auto mb-2 sm:mb-4 px-2 sm:px-4">
      <div className="bg-white/90 backdrop-blur-sm border-2 border-slate-300 rounded-lg shadow-sm p-2 sm:p-4 flex flex-row items-center justify-between gap-2 sm:gap-4">

        {/* Player X Score */}
        <div className={`flex items-center gap-1 sm:gap-3 px-2 sm:px-4 py-1 sm:py-2 rounded-lg transition-colors duration-300 ${currentPlayer === PLAYER_X && !winner ? 'bg-blue-100 border-blue-200 border' : 'border border-transparent'}`}>
          <div className="w-6 h-6 sm:w-8 sm:h-8 flex items-center justify-center text-lg sm:text-2xl font-bold text-blue-600">
            X
          </div>
          <div className="flex flex-col items-start">
            <span className="text-[10px] sm:text-xs uppercase tracking-wider text-slate-500 font-semibold hidden xs:block">Player X</span>
            <span className="text-xl sm:text-2xl font-bold leading-none">{scores[PLAYER_X]}</span>
          </div>
        </div>

        {/* Game Status */}
        <div className="flex flex-col items-center flex-1 min-w-0">
          {winner ? (
            <div className="text-sm sm:text-xl font-bold text-green-600 animate-bounce whitespace-nowrap">
              {winner === 'Draw' ? 'Draw!' : `${winner} Wins!`}
            </div>
          ) : (
            <div className="text-sm sm:text-lg text-slate-600 whitespace-nowrap">
              <span className="font-bold text-slate-800">{currentPlayer}'s</span> <span className="hidden sm:inline">Turn</span>
            </div>
          )}
          <button 
            onClick={onReset}
            className="mt-1 px-3 py-1 text-xs sm:text-sm bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-full border border-slate-300 transition-colors whitespace-nowrap"
          >
            Reset
          </button>
        </div>

        {/* Player O Score */}
        <div className={`flex items-center gap-1 sm:gap-3 px-2 sm:px-4 py-1 sm:py-2 rounded-lg transition-colors duration-300 ${currentPlayer === PLAYER_O && !winner ? 'bg-red-100 border-red-200 border' : 'border border-transparent'}`}>
          <div className="flex flex-col items-end">
            <span className="text-[10px] sm:text-xs uppercase tracking-wider text-slate-500 font-semibold hidden xs:block">Player O</span>
            <span className="text-xl sm:text-2xl font-bold leading-none">{scores[PLAYER_O]}</span>
          </div>
          <div className="w-6 h-6 sm:w-8 sm:h-8 flex items-center justify-center text-lg sm:text-2xl font-bold text-red-500">
            O
          </div>
        </div>

