                placeholder="Name"
              />
            </div>
            <div>
              <label className="block text-slate-500 text-sm font-bold mb-2 uppercase tracking-wide">Player 2 (O)</label>
              <input 
                type="text" 
                value={p2Name}
                onChange={(e) => setP2Name(e.target.value)}
