import React, { useState, useEffect, useRef } from 'react';
import { Peer, DataConnection } from 'peerjs';
import { GameConfig } from '../types';
import { PLAYER_X, PLAYER_O } from '../constants';

interface OnlineSetupProps {
  onStartGame: (config: GameConfig, conn: DataConnection, peer: Peer) => void;
  onBack: () => void;
}

const OnlineSetup: React.FC<OnlineSetupProps> = ({ onStartGame, onBack }) => {
  const [activeTab, setActiveTab] = useState<'HOST' | 'JOIN'>('HOST');
  const [name, setName] = useState('');
  const [gridSize, setGridSize] = useState(6);
  const [roomId, setRoomId] = useState(''); // User input for joining
  const [generatedId, setGeneratedId] = useState(''); // Host ID
  const [status, setStatus] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  const peerRef = useRef<Peer | null>(null);
  const connRef = useRef<DataConnection | null>(null);
  const isGameStartingRef = useRef(false);

  // Cleanup peer on unmount ONLY if game is not starting
  useEffect(() => {
    return () => {
      // If the game is starting, we hand off the peer to App.tsx, so don't destroy it here.
      if (peerRef.current && !isGameStartingRef.current) {
        peerRef.current.destroy();
      }
    };
  }, []);

  const generateShortId = () => {
    // Generate a 4-digit numeric ID
    return Math.floor(1000 + Math.random() * 9000).toString();
  };

  const createRoom = () => {
    if (!name.trim()) {
      setStatus('Please enter your name');
      return;
    }

    setIsLoading(true);
    setStatus('Initializing room...');

    const shortId = generateShortId();
    const fullPeerId = `db-game-${shortId}`;

    // Create Peer
    const peer = new Peer(fullPeerId);
    peerRef.current = peer;

    peer.on('open', (id) => {
      setGeneratedId(shortId);
      setIsLoading(false);
      setStatus('Waiting for opponent to join...');
    });

    peer.on('error', (err) => {
      console.error(err);
      setStatus('Error creating room. Please try again.');
      setIsLoading(false);
    });

    peer.on('connection', (conn) => {
      // Host receives connection
      connRef.current = conn;

      conn.on('open', () => {
        // Wait for 'JOIN' message from guest
        conn.on('data', (data: any) => {
          if (data && data.type === 'JOIN') {
            // Start Game!
            const config: GameConfig = {
              p1Name: name, // Host is always P1 (X)
              p2Name: data.name || 'Opponent',
              gridSize,
              mode: 'ONLINE',
              roomId: shortId,
              myPlayer: PLAYER_X
            };

            // Send start config to guest
            conn.send({ type: 'START', config });

            // Mark as starting so cleanup doesn't kill the peer
            isGameStartingRef.current = true;

            // Start local
            onStartGame(config, conn, peer);
          }
        });
      });
    });
  };

  const joinRoom = () => {
    if (!name.trim()) {
      setStatus('Please enter your name');
      return;
    }
    if (!roomId.trim()) {
      setStatus('Please enter a Room ID');
      return;
    }

    setIsLoading(true);
    setStatus('Connecting to room...');

    const peer = new Peer(); // Auto-gen ID for guest
    peerRef.current = peer;

    peer.on('open', () => {
      const targetPeerId = `db-game-${roomId}`; // Numeric ID is used here
      const conn = peer.connect(targetPeerId);
      connRef.current = conn;

      conn.on('open', () => {
        setStatus('Connected! Joining game...');
        // Send my name
        conn.send({ type: 'JOIN', name });
      });

      conn.on('data', (data: any) => {
        if (data && data.type === 'START') {
          // Received start config from Host
          // I am Player 2 (O)
          const config: GameConfig = {
             ...data.config,
             myPlayer: PLAYER_O
          };

          // Mark as starting so cleanup doesn't kill the peer
          isGameStartingRef.current = true;

          onStartGame(config, conn, peer);
        }
      });

      conn.on('close', () => {
        if (!isGameStartingRef.current) {
            setStatus('Connection closed by host.');
            setIsLoading(false);
        }
      });

      // Handle connection errors (e.g., ID not found)
      peer.on('error', (err) => {
         console.error(err);
         setStatus('Could not connect. Check Room ID.');
         setIsLoading(false);
      });
    });

    peer.on('error', (err) => {
      console.error(err);
      setStatus('Connection error. Please try again.');
      setIsLoading(false);
    });
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(generatedId);
    setStatus('Room ID copied!');
    setTimeout(() => setStatus('Waiting for opponent to join...'), 2000);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
      <div className="bg-white/95 backdrop-blur-md border-2 border-slate-300 rounded-xl shadow-xl p-6 sm:p-8 w-full relative">
        <button onClick={onBack} className="absolute left-4 top-4 text-slate-400 hover:text-slate-600 font-bold">← Back</button>

        <h2 className="text-3xl font-bold text-slate-800 text-center mb-6 mt-2">Online Lobby</h2>

        {/* Tabs */}
        <div className="flex bg-slate-100 p-1 rounded-lg mb-6">
          <button 
            onClick={() => { setActiveTab('HOST'); setStatus(''); }}
            className={`flex-1 py-2 rounded-md font-bold text-sm transition-all ${activeTab === 'HOST' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            Create Room
          </button>
          <button 
             onClick={() => { setActiveTab('JOIN'); setStatus(''); }}
             className={`flex-1 py-2 rounded-md font-bold text-sm transition-all ${activeTab === 'JOIN' ? 'bg-white text-green-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            Join Room
          </button>
        </div>

        {/* Common Name Input */}
        <div className="mb-4">
          <label className="block text-slate-500 text-xs font-bold mb-1 uppercase">Your Name</label>
          <input 
            type="text" 
            value={name}
            onChange={(e) => setName(e.target.value)}
            maxLength={12}
            className="w-full px-4 py-3 border-2 border-slate-200 rounded-lg focus:outline-none focus:border-slate-400 font-bold text-slate-800 bg-slate-50"
            placeholder="Enter name"
            disabled={isLoading || !!generatedId}
          />
        </div>

        {activeTab === 'HOST' && (
          <div className="animate-in">
             {!generatedId ? (
               <>
                <div className="mb-6">
                  <label className="block text-slate-500 text-xs font-bold mb-3 uppercase text-center">Grid Size</label>
                  <div className="flex justify-between gap-2">
                    {[6, 8, 10].map((size) => (
                      <button
                        key={size}
                        onClick={() => setGridSize(size)}
                        className={`flex-1 py-2 rounded-lg border-2 font-bold transition-all ${
                          gridSize === size 
                            ? 'bg-slate-800 text-white border-slate-800' 
                            : 'bg-white text-slate-500 border-slate-200'
                        }`}
                        disabled={isLoading}
                      >
                        {size}x{size}
                      </button>
                    ))}
                  </div>
                </div>
                <button 
                  onClick={createRoom}
                  disabled={isLoading}
                  className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-3 rounded-xl shadow-md transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isLoading ? 'Creating...' : 'Create Room'}
                </button>
               </>
             ) : (
               <div className="flex flex-col items-center bg-blue-50 border-2 border-blue-100 rounded-xl p-6 mb-4">
                 <span className="text-slate-500 text-xs font-bold uppercase mb-2">Room Code</span>
                 <div className="text-5xl font-mono font-bold text-blue-600 tracking-wider mb-2 select-all" onClick={copyToClipboard}>
                   {generatedId}
                 </div>
                 <p className="text-xs text-blue-400 mb-4">Share this code with your friend</p>
                 <div className="flex items-center gap-2 text-slate-500 text-sm">
                   <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                   Waiting for player...
                 </div>
               </div>
             )}
          </div>
        )}

        {activeTab === 'JOIN' && (
          <div className="animate-in">
             <div className="mb-6">
                <label className="block text-slate-500 text-xs font-bold mb-1 uppercase">Room Code</label>
                <input 
                  type="number"
                  pattern="[0-9]*" 
                  value={roomId}
                  onChange={(e) => setRoomId(e.target.value.slice(0, 4))}
                  className="w-full px-4 py-3 border-2 border-slate-200 rounded-lg focus:outline-none focus:border-green-400 font-bold text-slate-800 bg-slate-50 font-mono tracking-widest text-center text-xl uppercase placeholder:normal-case placeholder:tracking-normal placeholder:text-slate-300"
                  placeholder="e.g. 1234"
                  disabled={isLoading}
                />
              </div>
              <button 
                onClick={joinRoom}
                disabled={isLoading}
                className="w-full bg-green-500 hover:bg-green-600 text-white font-bold py-3 rounded-xl shadow-md transition-all disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isLoading ? 'Connecting...' : 'Join Game'}
              </button>
          </div>
        )}

        {status && (
          <div className="mt-4 text-center text-sm font-bold text-slate-500 bg-slate-100 py-2 rounded-lg animate-in">
            {status}
          </div>
        )}
      </div>
    </div>
  );
};

export default OnlineSetup;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { DataConnection, Peer } from 'peerjs';
import { 
  PLAYER_X, 
  PLAYER_O, 
  Player, 
  SquareOwner 
} from './constants';
import { GameState, LineType, GameConfig, NetworkMessage } from './types';
import Grid from './components/Grid';
import ScoreBoard from './components/ScoreBoard';
import SetupScreen from './components/SetupScreen';
import MenuScreen from './components/MenuScreen';
import OnlineSetup from './components/OnlineSetup';

type ViewState = 'MENU' | 'SETUP_OFFLINE' | 'SETUP_ONLINE' | 'GAME';

// Initial state creation
const createInitialState = (rows: number, cols: number): GameState => {
  const hLines = Array(rows).fill(null).map(() => Array(cols - 1).fill(false));
  const vLines = Array(rows - 1).fill(null).map(() => Array(cols).fill(false));
  const squares = Array(rows - 1).fill(null).map(() => Array(cols - 1).fill(null));

  return {
    hLines,
    vLines,
    squares,
    currentPlayer: PLAYER_X,
    scores: { [PLAYER_X]: 0, [PLAYER_O]: 0 },
    winner: null,
    moveHistory: []
  };
};

function App() {
  const [view, setView] = useState<ViewState>('MENU');
  const [gameConfig, setGameConfig] = useState<GameConfig | null>(null);
  const [gameState, setGameState] = useState<GameState | null>(null);

  // PeerJS Connection References
  const connectionRef = useRef<DataConnection | null>(null);
  const peerRef = useRef<Peer | null>(null);

  // Helper to process a move on the state
  const processMove = (prev: GameState, type: LineType, r: number, c: number, rows: number, cols: number): GameState => {
      // 1. Validate move (basic check, caller should also check)
      if (type === 'horizontal') {
        if (prev.hLines[r][c]) return prev; 
      } else {
        if (prev.vLines[r][c]) return prev;
      }

      // 2. Clone state
      const newHLines = prev.hLines.map(row => [...row]);
      const newVLines = prev.vLines.map(row => [...row]);
      const newSquares = prev.squares.map(row => [...row]);
      let newScores = { ...prev.scores };
      let squareCompleted = false;

      // 3. Mark the line
      if (type === 'horizontal') newHLines[r][c] = true;
      else newVLines[r][c] = true;

      // 4. Check for completed squares
      const ROWS = rows;
      const COLS = cols;

      if (type === 'horizontal') {
        // Above
        if (r > 0 && newHLines[r-1][c] && newHLines[r][c] && newVLines[r-1][c] && newVLines[r-1][c+1]) {
            newSquares[r-1][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
        // Below
        if (r < ROWS - 1 && newHLines[r][c] && newHLines[r+1][c] && newVLines[r][c] && newVLines[r][c+1]) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
      } else {
        // Left
        if (c > 0 && newHLines[r][c-1] && newHLines[r+1][c-1] && newVLines[r][c-1] && newVLines[r][c]) {
            newSquares[r][c-1] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
        // Right
        if (c < COLS - 1 && newHLines[r][c] && newHLines[r+1][c] && newVLines[r][c] && newVLines[r][c+1]) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
      }

      // 5. Determine winner
      const totalSquares = (ROWS - 1) * (COLS - 1);
      const filledSquares = newScores[PLAYER_X] + newScores[PLAYER_O];
      let winner = null;
      if (filledSquares === totalSquares) {
        if (newScores[PLAYER_X] > newScores[PLAYER_O]) winner = PLAYER_X;
        else if (newScores[PLAYER_O] > newScores[PLAYER_X]) winner = PLAYER_O;
        else winner = 'Draw';
      }

      const nextPlayer = squareCompleted ? prev.currentPlayer : (prev.currentPlayer === PLAYER_X ? PLAYER_O : PLAYER_X);

      return {
        ...prev,
        hLines: newHLines,
        vLines: newVLines,
        squares: newSquares,
        scores: newScores,
        currentPlayer: nextPlayer,
        winner: winner as any
      };
  };

  const handleStartOffline = (config: { p1Name: string; p2Name: string; gridSize: number }) => {
    const fullConfig: GameConfig = { ...config, mode: 'OFFLINE' };
    setGameConfig(fullConfig);
    setGameState(createInitialState(config.gridSize, config.gridSize));
    setView('GAME');
  };

  const handleStartOnline = (config: GameConfig, conn: DataConnection, peer: Peer) => {
    connectionRef.current = conn;
    peerRef.current = peer;
    setGameConfig(config);
    setGameState(createInitialState(config.gridSize, config.gridSize));
    setView('GAME');

    // Setup listener for incoming moves
    conn.on('data', (data: any) => {
      const msg = data as NetworkMessage;
      if (msg.type === 'MOVE') {
        setGameState(prev => {
          if (!prev) return null;
          return processMove(prev, msg.lineType, msg.r, msg.c, config.gridSize, config.gridSize);
        });
      } else if (msg.type === 'RESTART') {
        setGameState(createInitialState(config.gridSize, config.gridSize));
      } else if (msg.type === 'QUIT') {
        alert('Opponent has left the game.');
        quitGame();
      }
    });

    conn.on('close', () => {
      alert('Connection lost.');
      quitGame();
    });
  };

  const quitGame = () => {
    // If online, close connection and destroy peer
    if (connectionRef.current) {
      // Try send quit message
      try { connectionRef.current.send({ type: 'QUIT' }); } catch(e) {}
      connectionRef.current.close();
      connectionRef.current = null;
    }

    if (peerRef.current) {
      peerRef.current.destroy();
      peerRef.current = null;
    }

    setGameConfig(null);
    setGameState(null);
    setView('MENU');
  };

  const resetGame = () => {
    if (!gameConfig) return;

    if (gameConfig.mode === 'ONLINE') {
        if (window.confirm("Do you want to leave the game?")) {
            quitGame();
        }
       return;
    }

    // Offline Reset
    setGameState(createInitialState(gameConfig.gridSize, gameConfig.gridSize));
  };

  const handleLineClick = useCallback((type: LineType, r: number, c: number) => {
    if (!gameConfig || !gameState) return;

    // Online check: Is it my turn?
    if (gameConfig.mode === 'ONLINE' && gameConfig.myPlayer !== gameState.currentPlayer) {
      return; // Not your turn
    }

    setGameState(prev => {
      if (!prev) return null;
      const newState = processMove(prev, type, r, c, gameConfig.gridSize, gameConfig.gridSize);

      // If state changed and Online, send move
      if (gameConfig.mode === 'ONLINE' && connectionRef.current) {
         // Only send if move was valid (state changed, essentially check if lines differ)
         if (newState !== prev) {
             const msg: NetworkMessage = { type: 'MOVE', lineType: type, r, c };
             connectionRef.current.send(msg);
         }
      }

      return newState;
    });
  }, [gameConfig, gameState]);


  // RENDER LOGIC

  if (view === 'MENU') {
    return <MenuScreen onSelectMode={(mode) => setView(mode === 'ONLINE' ? 'SETUP_ONLINE' : 'SETUP_OFFLINE')} />;
  }

  if (view === 'SETUP_OFFLINE') {
    return <SetupScreen onStart={handleStartOffline} onBack={() => setView('MENU')} />;
  }

  if (view === 'SETUP_ONLINE') {
    return <OnlineSetup onStartGame={handleStartOnline} onBack={() => setView('MENU')} />;
  }

  // GAME VIEW
  if (!gameConfig || !gameState) return null;

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <header className="pt-4 sm:pt-6 pb-2 px-4 text-center z-10 relative">
        <button 
          onClick={quitGame}
          className="absolute left-4 top-4 sm:top-6 text-slate-400 hover:text-slate-600 font-bold text-sm sm:text-base"
        >
          ← Quit
        </button>

        <h1 className="text-4xl sm:text-5xl font-bold text-slate-800 tracking-tight" style={{ textShadow: '2px 2px 0px rgba(0,0,0,0.1)' }}>
          Dots & Boxes
        </h1>
        {gameConfig.mode === 'ONLINE' && (
             <div className="text-xs text-blue-500 font-mono mt-1">
                 Room: {gameConfig.roomId}
             </div>
        )}
      </header>

      {/* Scoreboard */}
      <ScoreBoard 
        scores={gameState.scores} 
        currentPlayer={gameState.currentPlayer} 
        winner={gameState.winner}
        onReset={resetGame}
        p1Name={gameConfig.p1Name}
        p2Name={gameConfig.p2Name}
        myPlayer={gameConfig.myPlayer}
      />

      {/* Game Grid */}
      <main className="flex-1 game-scroll overflow-auto flex items-start justify-center p-4 sm:p-8">
         <Grid 
           gameState={gameState} 
           onLineClick={handleLineClick} 
           rows={gameConfig.gridSize} 
           cols={gameConfig.gridSize} 
           disabled={gameConfig.mode === 'ONLINE' && gameState.currentPlayer !== gameConfig.myPlayer}
          />
      </main>

      {/* Footer */}
      <footer className="p-4 text-center text-slate-400 text-sm">
        {gameState.winner
          ? "Game Over!" 
          : gameConfig.mode === 'ONLINE' 
             ? (gameState.currentPlayer === gameConfig.myPlayer ? "It's your turn!" : `Waiting for ${gameState.currentPlayer === PLAYER_X ? gameConfig.p1Name : gameConfig.p2Name}...`)
             : `Current Turn: ${gameState.currentPlayer === PLAYER_X ? gameConfig.p1Name : gameConfig.p2Name}`
        }
      </footer>
    </div>
  );
}

export default App;

