import React, { useState, useEffect } from 'react';

interface SetupScreenProps {
  onStart: (config: { p1Name: string; p2Name: string; gridSize: number }) => void;
  onBack: () => void;
}

const SetupScreen: React.FC<SetupScreenProps> = ({ onStart, onBack }) => {
  const [p1Name, setP1Name] = useState('Player 1');
  const [p2Name, setP2Name] = useState('Player 2');
  const [gridSize, setGridSize] = useState(6);
  const [installPrompt, setInstallPrompt] = useState<any>(null);
  const [isStandalone, setIsStandalone] = useState(false);

  useEffect(() => {
    // Check if running in standalone mode (PWA)
    const checkStandalone = () => {
      const isStandaloneMode = window.matchMedia('(display-mode: standalone)').matches || 
                              (window.navigator as any).standalone === true;
      setIsStandalone(isStandaloneMode);
    };

    checkStandalone();
    window.addEventListener('resize', checkStandalone);

    // Check if the event was already captured globally in index.html
    if ((window as any).deferredPrompt) {
      setInstallPrompt((window as any).deferredPrompt);
    }

    const handler = (e: Event) => {
      // Prevent the mini-infobar from appearing on mobile
      e.preventDefault();
      // Stash the event so it can be triggered later.
      setInstallPrompt(e);
      // Update global for consistency
      (window as any).deferredPrompt = e;
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => {
      window.removeEventListener('beforeinstallprompt', handler);
      window.removeEventListener('resize', checkStandalone);
    }
  }, []);

  const handleInstallClick = () => {
    if (installPrompt) {
      // Trigger the native install prompt
      installPrompt.prompt();
      installPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          setInstallPrompt(null);
          (window as any).deferredPrompt = null;
        }
      });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onStart({ p1Name, p2Name, gridSize });
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
      <div className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-2 border-slate-300 dark:border-slate-700 rounded-xl shadow-xl p-6 sm:p-8 w-full relative transition-colors duration-300">
        <button onClick={onBack} className="absolute left-4 top-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 font-bold transition-colors">← Back</button>

        <h1 className="text-4xl sm:text-5xl font-bold text-slate-800 dark:text-slate-100 text-center mb-8 mt-4 tracking-tight transition-colors" style={{ textShadow: '2px 2px 0px rgba(0,0,0,0.05)' }}>
          Dots & Boxes
        </h1>

        <form onSubmit={handleSubmit} className="flex flex-col gap-6">
          {/* Player Names */}
          <div className="flex flex-col gap-4">
            <div>
              <label className="block text-slate-500 dark:text-slate-400 text-sm font-bold mb-2 uppercase tracking-wide">Player 1 (X)</label>
              <input 
                type="text" 
                value={p1Name}
                onChange={(e) => setP1Name(e.target.value)}
                maxLength={12}
                className="w-full px-4 py-3 border-2 border-blue-200 dark:border-blue-900/50 rounded-lg focus:outline-none focus:border-blue-400 dark:focus:border-blue-500 font-bold text-slate-800 dark:text-blue-100 bg-blue-50 dark:bg-slate-900 focus:bg-white dark:focus:bg-slate-800 transition-colors placeholder-slate-400"
                placeholder="Name"
              />
            </div>
            <div>
              <label className="block text-slate-500 dark:text-slate-400 text-sm font-bold mb-2 uppercase tracking-wide">Player 2 (O)</label>
              <input 
                type="text" 
                value={p2Name}
                onChange={(e) => setP2Name(e.target.value)}
                maxLength={12}
                className="w-full px-4 py-3 border-2 border-red-200 dark:border-red-900/50 rounded-lg focus:outline-none focus:border-red-400 dark:focus:border-red-500 font-bold text-slate-800 dark:text-red-100 bg-red-50 dark:bg-slate-900 focus:bg-white dark:focus:bg-slate-800 transition-colors placeholder-slate-400"
                placeholder="Name"
              />
            </div>
          </div>

          {/* Grid Size Selection */}
          <div>
            <label className="block text-slate-500 dark:text-slate-400 text-sm font-bold mb-3 uppercase tracking-wide text-center">Select Grid Size</label>
            <div className="flex justify-between gap-3">
              {[6, 8, 10].map((size) => (
                <button
                  key={size}
                  type="button"
                  onClick={() => setGridSize(size)}
                  className={`flex-1 py-3 rounded-lg border-2 font-bold transition-all transform active:scale-95 ${
                    gridSize === size 
                      ? 'bg-slate-800 dark:bg-slate-200 text-white dark:text-slate-900 border-slate-800 dark:border-slate-200 shadow-md scale-105' 
                      : 'bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-700 hover:border-slate-400 dark:hover:border-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                  }`}
                >
                  {size}x{size}
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col gap-3 mt-4">
            {/* Start Button */}
            <button 
              type="submit"
              className="w-full bg-green-500 hover:bg-green-600 text-white font-bold py-4 rounded-xl shadow-lg border-b-4 border-green-700 active:border-b-0 active:translate-y-1 transition-all text-xl uppercase tracking-wide"
            >
              Start Game
            </button>

            {/* Install Button */}
            {!isStandalone && installPrompt && (
              <div className="flex flex-col gap-2 animate-in">
                <button
                  type="button"
                  onClick={handleInstallClick}
                  className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg border-b-4 border-blue-700 active:border-b-0 active:translate-y-1 transition-all text-base flex items-center justify-center gap-2 uppercase tracking-wide"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                  </svg>
                  INSTALL APP
                </button>
              </div>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

