import React, { useState, useCallback, useRef, useEffect } from 'react';
import { DataConnection, Peer } from 'peerjs';
import { 
  PLAYER_X, 
  PLAYER_O, 
  Player, 
  SquareOwner 
} from '../constants';
import { GameState, LineType, GameConfig, NetworkMessage } from '../types';
import Grid from './Grid';
import ScoreBoard from './ScoreBoard';
import SetupScreen from './SetupScreen';
import MenuScreen from './MenuScreen';
import OnlineSetup from './OnlineSetup';

type ViewState = 'MENU' | 'SETUP_OFFLINE' | 'SETUP_ONLINE' | 'GAME';

// Initial state creation
const createInitialState = (rows: number, cols: number): GameState => {
  const hLines = Array(rows).fill(null).map(() => Array(cols - 1).fill(false));
  const vLines = Array(rows - 1).fill(null).map(() => Array(cols).fill(false));
  const squares = Array(rows - 1).fill(null).map(() => Array(cols - 1).fill(null));

  return {
    hLines,
    vLines,
    squares,
    currentPlayer: PLAYER_X,
    scores: { [PLAYER_X]: 0, [PLAYER_O]: 0 },
    winner: null,
    moveHistory: []
  };
};

interface DotsGameProps {
  onBackToLauncher: () => void;
  theme: 'light' | 'dark';
  onToggleTheme: () => void;
}

const DotsGame: React.FC<DotsGameProps> = ({ onBackToLauncher, theme, onToggleTheme }) => {
  const [view, setView] = useState<ViewState>('MENU');
  const [gameConfig, setGameConfig] = useState<GameConfig | null>(null);
  const [gameState, setGameState] = useState<GameState | null>(null);

  // PeerJS Connection References
  const connectionRef = useRef<DataConnection | null>(null);
  const peerRef = useRef<Peer | null>(null);

  // Helper to process a move on the state
  const processMove = (prev: GameState, type: LineType, r: number, c: number, rows: number, cols: number): GameState => {
      // 1. Validate move (basic check, caller should also check)
      if (type === 'horizontal') {
        if (prev.hLines[r][c]) return prev; 
      } else {
        if (prev.vLines[r][c]) return prev;
      }

      // 2. Clone state
      const newHLines = prev.hLines.map(row => [...row]);
      const newVLines = prev.vLines.map(row => [...row]);
      const newSquares = prev.squares.map(row => [...row]);
      let newScores = { ...prev.scores };
      let squareCompleted = false;

      // 3. Mark the line
      if (type === 'horizontal') newHLines[r][c] = true;
      else newVLines[r][c] = true;

      // 4. Check for completed squares
      const ROWS = rows;
      const COLS = cols;

      if (type === 'horizontal') {
        // Above
        if (r > 0 && newHLines[r-1][c] && newHLines[r][c] && newVLines[r-1][c] && newVLines[r-1][c+1]) {
            newSquares[r-1][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
        // Below
        if (r < ROWS - 1 && newHLines[r][c] && newHLines[r+1][c] && newVLines[r][c] && newVLines[r][c+1]) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
      } else {
        // Left
        if (c > 0 && newHLines[r][c-1] && newHLines[r+1][c-1] && newVLines[r][c-1] && newVLines[r][c]) {
            newSquares[r][c-1] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
        // Right
        if (c < COLS - 1 && newHLines[r][c] && newHLines[r+1][c] && newVLines[r][c] && newVLines[r][c+1]) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
      }

      // 5. Determine winner
      const totalSquares = (ROWS - 1) * (COLS - 1);
      const filledSquares = newScores[PLAYER_X] + newScores[PLAYER_O];
      let winner = null;
      if (filledSquares === totalSquares) {
        if (newScores[PLAYER_X] > newScores[PLAYER_O]) winner = PLAYER_X;
        else if (newScores[PLAYER_O] > newScores[PLAYER_X]) winner = PLAYER_O;
        else winner = 'Draw';
      }

      const nextPlayer = squareCompleted ? prev.currentPlayer : (prev.currentPlayer === PLAYER_X ? PLAYER_O : PLAYER_X);

      return {
        ...prev,
        hLines: newHLines,
        vLines: newVLines,
        squares: newSquares,
        scores: newScores,
        currentPlayer: nextPlayer,
        winner: winner as any
      };
  };

  const handleStartOffline = (config: { p1Name: string; p2Name: string; gridSize: number }) => {
    const fullConfig: GameConfig = { ...config, mode: 'OFFLINE' };
    setGameConfig(fullConfig);
    setGameState(createInitialState(config.gridSize, config.gridSize));
    setView('GAME');
  };

  const handleStartOnline = (config: GameConfig, conn: DataConnection, peer: Peer) => {
    connectionRef.current = conn;
    peerRef.current = peer;
    setGameConfig(config);
    setGameState(createInitialState(config.gridSize, config.gridSize));
    setView('GAME');

    // Setup listener for incoming moves
    conn.on('data', (data: any) => {
      const msg = data as NetworkMessage;
      if (msg.type === 'MOVE') {
        setGameState(prev => {
          if (!prev) return null;
          return processMove(prev, msg.lineType, msg.r, msg.c, config.gridSize, config.gridSize);
        });
      } else if (msg.type === 'RESTART') {
        setGameState(createInitialState(config.gridSize, config.gridSize));
      } else if (msg.type === 'QUIT') {
        alert('Opponent has left the game.');
        quitGame();
      }
    });

    conn.on('close', () => {
      alert('Connection lost.');
      quitGame();
    });
  };

  const quitGame = () => {
    // If online, close connection and destroy peer
    if (connectionRef.current) {
      // Try send quit message
      try { connectionRef.current.send({ type: 'QUIT' }); } catch(e) {}
      connectionRef.current.close();
      connectionRef.current = null;
    }

    if (peerRef.current) {
      peerRef.current.destroy();
      peerRef.current = null;
    }

    setGameConfig(null);
    setGameState(null);
    setView('MENU');
  };

  const resetGame = () => {
    if (!gameConfig) return;

    if (gameConfig.mode === 'ONLINE') {
        if (window.confirm("Do you want to leave the game?")) {
            quitGame();
        }
       return;
    }

    // Offline Reset
    setGameState(createInitialState(gameConfig.gridSize, gameConfig.gridSize));
  };

  const handleLineClick = useCallback((type: LineType, r: number, c: number) => {
    if (!gameConfig || !gameState) return;

    // Online check: Is it my turn?
    if (gameConfig.mode === 'ONLINE' && gameConfig.myPlayer !== gameState.currentPlayer) {
      return; // Not your turn
    }

    setGameState(prev => {
      if (!prev) return null;
      const newState = processMove(prev, type, r, c, gameConfig.gridSize, gameConfig.gridSize);

      // If state changed and Online, send move
      if (gameConfig.mode === 'ONLINE' && connectionRef.current) {
         // Only send if move was valid (state changed, essentially check if lines differ)
         if (newState !== prev) {
             const msg: NetworkMessage = { type: 'MOVE', lineType: type, r, c };
             connectionRef.current.send(msg);
         }
      }

      return newState;
    });
  }, [gameConfig, gameState]);


  // RENDER LOGIC

  if (view === 'MENU') {
    return (
      <>
        <div className="absolute top-4 left-4 z-50">
           <button onClick={onBackToLauncher} className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-700 dark:hover:text-slate-200">← Back</button>
        </div>
        <MenuScreen onSelectMode={(mode) => setView(mode === 'ONLINE' ? 'SETUP_ONLINE' : 'SETUP_OFFLINE')} theme={theme} onToggleTheme={onToggleTheme} />
      </>
    );
  }

  if (view === 'SETUP_OFFLINE') {
    return <SetupScreen onStart={handleStartOffline} onBack={() => setView('MENU')} />;
  }

  if (view === 'SETUP_ONLINE') {
    return <OnlineSetup onStartGame={handleStartOnline} onBack={() => setView('MENU')} />;
  }

  // GAME VIEW
  if (!gameConfig || !gameState) return null;

  return (
    <div className="flex flex-col h-full dark:text-slate-200 w-full">
      {/* Header */}
      <header className="pt-4 sm:pt-6 pb-2 px-4 text-center z-10 relative">
        <button 
          onClick={quitGame}
          className="absolute left-4 top-4 sm:top-6 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 font-bold text-sm sm:text-base transition-colors"
        >
          ← Quit
        </button>

        <h1 className="text-4xl sm:text-5xl font-bold text-slate-800 dark:text-slate-100 tracking-tight transition-colors" style={{ textShadow: theme === 'dark' ? '2px 2px 0px rgba(0,0,0,0.5)' : '2px 2px 0px rgba(0,0,0,0.1)' }}>
          Dots & Boxes
        </h1>
        {gameConfig.mode === 'ONLINE' && (
             <div className="text-xs text-blue-500 dark:text-blue-400 font-mono mt-1">
                 Room: {gameConfig.roomId}
             </div>
        )}
      </header>

      {/* Scoreboard */}
      <ScoreBoard 
        scores={gameState.scores} 
        currentPlayer={gameState.currentPlayer} 
        winner={gameState.winner}
        onReset={resetGame}
        p1Name={gameConfig.p1Name}
        p2Name={gameConfig.p2Name}
        myPlayer={gameConfig.myPlayer}
      />

      {/* Game Grid */}
      <main className="flex-1 game-scroll overflow-auto flex items-start justify-center p-4 sm:p-8">
         <Grid 
           gameState={gameState} 
           onLineClick={handleLineClick} 
           rows={gameConfig.gridSize} 
           cols={gameConfig.gridSize} 
           disabled={gameConfig.mode === 'ONLINE' && gameState.currentPlayer !== gameConfig.myPlayer}
          />
      </main>

      {/* Footer */}
      <footer className="p-4 text-center text-slate-400 dark:text-slate-500 text-sm">
        {gameState.winner
          ? "Game Over!" 
          : gameConfig.mode === 'ONLINE' 
             ? (gameState.currentPlayer === gameConfig.myPlayer ? "It's your turn!" : `Waiting for ${gameState.currentPlayer === PLAYER_X ? gameConfig.p1Name : gameConfig.p2Name}...`)
             : `Current Turn: ${gameState.currentPlayer === PLAYER_X ? gameConfig.p1Name : gameConfig.p2Name}`
        }
      </footer>
    </div>
  );
}

export default DotsGame;

import React, { useState, useEffect, useCallback, useRef } from 'react';

interface ZipGameProps {
  onBackToLauncher: () => void;
  theme: 'light' | 'dark';
}

type Level = 'EASY' | 'MEDIUM' | 'HARD';
type Point = { r: number; c: number };

const ZipGame: React.FC<ZipGameProps> = ({ onBackToLauncher, theme }) => {
  const [view, setView] = useState<'MENU' | 'GAME'>('MENU');
  const [level, setLevel] = useState<Level>('EASY');
  const [gridSize, setGridSize] = useState(4);
  const [path, setPath] = useState<Point[]>([]);
  const [isDrawing, setIsDrawing] = useState(false);
  const [win, setWin] = useState(false);

  // Configuration based on level
  const getGridSize = (lvl: Level) => {
    switch(lvl) {
      case 'EASY': return 4;
      case 'MEDIUM': return 5;
      case 'HARD': return 6;
      default: return 4;
    }
  };

  const startGame = (lvl: Level) => {
    const size = getGridSize(lvl);
    setGridSize(size);
    setLevel(lvl);
    resetGame(size);
    setView('GAME');
  };

  const resetGame = (size: number = gridSize) => {
    // Start at a random position or fixed? Let's fix top-left for simplicity/consistency or random.
    // Random start makes it more replayable.
    const startR = Math.floor(Math.random() * size);
    const startC = Math.floor(Math.random() * size);
    setPath([{ r: startR, c: startC }]);
    setWin(false);
    setIsDrawing(false);
  };

  // Check if a point is in the path
  const getPathIndex = (r: number, c: number) => {
    return path.findIndex(p => p.r === r && p.c === c);
  };

  const handlePointerDown = (r: number, c: number) => {
    if (win) return;
    const index = getPathIndex(r, c);
    // User can only start drawing from the HEAD of the path
    if (index === path.length - 1) {
        setIsDrawing(true);
    }
  };

  const handlePointerEnter = (r: number, c: number) => {
    if (!isDrawing || win) return;

    const lastPoint = path[path.length - 1];
    const index = getPathIndex(r, c);

    // Logic:
    // 1. If we move to the 2nd to last point, we undo (backtrack)
    if (path.length > 1 && index === path.length - 2) {
      setPath(prev => prev.slice(0, -1));
      return;
    }

    // 2. If we move to an unvisited cell
    if (index === -1) {
      // Check adjacency
      const isAdjacent = Math.abs(lastPoint.r - r) + Math.abs(lastPoint.c - c) === 1;

      if (isAdjacent) {
        const newPath = [...path, { r, c }];
        setPath(newPath);

        // Check Win Condition
        if (newPath.length === gridSize * gridSize) {
          setWin(true);
          setIsDrawing(false);
        }
      }
    }
  };

  const handlePointerUp = () => {
    setIsDrawing(false);
  };

  // Handle global pointer up in case drag ends outside grid
  useEffect(() => {
    window.addEventListener('pointerup', handlePointerUp);
    return () => window.removeEventListener('pointerup', handlePointerUp);
  }, []);

  // Generate color for index
  const getCellColor = (index: number, total: number) => {
    if (index === -1) return undefined;
    // Rainbow gradient from Red to Purple
    // Easy: 0 to 100% of hue spectrum
    const hue = (index / (total - 1)) * 300; // 0 to 300 (skip pink/red wrap)
    return `hsl(${hue}, 85%, 60%)`;
  };

  // --- RENDERING ---

  if (view === 'MENU') {
    return (
      <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
         <div className="absolute top-4 left-4 z-50">
           <button onClick={onBackToLauncher} className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-700 dark:hover:text-slate-200">← Back</button>
        </div>

        <div className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-2 border-slate-300 dark:border-slate-700 rounded-xl shadow-xl p-8 w-full text-center relative transition-colors duration-300">
           <h1 className="text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-purple-600 mb-2 tracking-tight" style={{ filter: theme === 'dark' ? 'brightness(1.2)' : 'none' }}>
            Zip
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mb-8 font-medium">Connect the path to fill the grid!</p>

          <div className="flex flex-col gap-3">
             <button onClick={() => startGame('EASY')} className="w-full bg-green-500 hover:bg-green-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-green-700 active:border-b-0 active:translate-y-1 transition-all">
                Easy (4x4)
             </button>
             <button onClick={() => startGame('MEDIUM')} className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-blue-700 active:border-b-0 active:translate-y-1 transition-all">
                Medium (5x5)
             </button>
             <button onClick={() => startGame('HARD')} className="w-full bg-purple-500 hover:bg-purple-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-purple-700 active:border-b-0 active:translate-y-1 transition-all">
                Hard (6x6)
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full dark:text-slate-200">
      {/* Header */}
      <header className="pt-6 pb-2 px-4 text-center relative">
        <button 
          onClick={() => setView('MENU')}
          className="absolute left-4 top-6 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 font-bold transition-colors"
        >
          ← Menu
        </button>
        <h1 className="text-4xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">
          Zip <span className="text-sm font-normal text-slate-400 block sm:inline opacity-70"> - {level} Level</span>
        </h1>
      </header>

      {/* Game Area */}
      <main className="flex-1 flex flex-col items-center justify-center p-4">

        {/* Progress */}
        <div className="mb-6 font-mono text-xl font-bold text-slate-600 dark:text-slate-400">
           {path.length} / {gridSize * gridSize}
        </div>

        {/* The Grid */}
        <div 
          className="relative bg-white dark:bg-slate-800 p-2 rounded-xl shadow-2xl border-2 border-slate-200 dark:border-slate-700 touch-none select-none"
          style={{
             display: 'grid',
             gridTemplateColumns: `repeat(${gridSize}, 1fr)`,
             gap: '6px',
          }}
        >
           {Array.from({ length: gridSize * gridSize }).map((_, i) => {
             const r = Math.floor(i / gridSize);
             const c = i % gridSize;
             const pathIndex = getPathIndex(r, c);
             const isFilled = pathIndex !== -1;
             const isHead = pathIndex === path.length - 1;

             return (
               <div
                 key={`${r}-${c}`}
                 onPointerDown={(e) => {
                     e.preventDefault(); // Prevent scroll
                     handlePointerDown(r, c);
                 }}
                 onPointerEnter={(e) => {
                     handlePointerEnter(r, c);
                 }}
                 className={`
                    w-12 h-12 sm:w-16 sm:h-16 rounded-lg flex items-center justify-center text-xl sm:text-2xl font-bold transition-all duration-200
                    ${isFilled ? 'scale-100' : 'scale-95 bg-slate-100 dark:bg-slate-900'}
                    ${isHead ? 'ring-4 ring-white/50 z-10 scale-110 shadow-lg' : ''}
                 `}
                 style={{
                    backgroundColor: isFilled ? getCellColor(pathIndex, gridSize * gridSize) : undefined,
                    color: isFilled ? 'white' : 'transparent',
                    boxShadow: isFilled ? 'inset 0 -4px 0 rgba(0,0,0,0.1)' : 'none'
                 }}
               >
                 {isFilled ? pathIndex + 1 : ''}
               </div>
             );
           })}
        </div>

        {win && (
           <div className="mt-8 animate-bounce-in flex flex-col items-center">
              <div className="text-3xl font-bold text-green-500 mb-2">Level Complete!</div>
              <button 
                onClick={() => resetGame()}
                className="px-8 py-3 bg-slate-800 dark:bg-slate-200 text-white dark:text-slate-900 font-bold rounded-full shadow-lg hover:scale-105 transition-transform"
              >
                Play Again
              </button>
           </div>
        )}

        {!win && (
             <button 
                onClick={() => resetGame()}
                className="mt-8 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 font-bold text-sm"
              >
                Reset Board
              </button>
        )}

      </main>
    </div>
