import React, { useState, useEffect, useRef } from 'react';

interface ZipGameProps {
  onBackToLauncher: () => void;
  theme: 'light' | 'dark';
}

type Level = 'EASY' | 'MEDIUM' | 'HARD';
type Point = { r: number; c: number };

// Helper to generate a key for the map
const posKey = (r: number, c: number) => `${r},${c}`;

const ZipGame: React.FC<ZipGameProps> = ({ onBackToLauncher, theme }) => {
  const [view, setView] = useState<'MENU' | 'GAME'>('MENU');
  const [level, setLevel] = useState<Level>('EASY');
  const [gridSize, setGridSize] = useState(4);

  // Game State
  const [fixedCells, setFixedCells] = useState<Map<string, number>>(new Map());
  const [path, setPath] = useState<Point[]>([]); // User's current path. Index i is number i+1.
  const [isDrawing, setIsDrawing] = useState(false);
  const [win, setWin] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  // Configuration based on level
  const getGridSize = (lvl: Level) => {
    switch(lvl) {
      case 'EASY': return 4;
      case 'MEDIUM': return 5;
      case 'HARD': return 6;
      default: return 4;
    }
  };

  const startGame = async (lvl: Level) => {
    const size = getGridSize(lvl);
    setGridSize(size);
    setLevel(lvl);
    setIsGenerating(true);
    setView('GAME');

    // Allow UI to update before heavy generation
    setTimeout(() => {
        generatePuzzle(size);
        setIsGenerating(false);
    }, 100);
  };

  const generatePuzzle = (size: number) => {
    // 1. Generate a random Hamiltonian Path (Backtracking DFS)
    const totalCells = size * size;
    const solutionPath: Point[] = [];
    const visited = new Set<string>();

    const startR = Math.floor(Math.random() * size);
    const startC = Math.floor(Math.random() * size);

    const isValid = (r: number, c: number) => r >= 0 && r < size && c >= 0 && c < size;

    const findPath = (curr: Point): boolean => {
       solutionPath.push(curr);
       visited.add(posKey(curr.r, curr.c));

       if (solutionPath.length === totalCells) return true;

       // Get neighbors
       const neighbors = [
         { r: curr.r - 1, c: curr.c },
         { r: curr.r + 1, c: curr.c },
         { r: curr.r, c: curr.c - 1 },
         { r: curr.r, c: curr.c + 1 },
       ].filter(n => isValid(n.r, n.c) && !visited.has(posKey(n.r, n.c)));

       // Randomize neighbors for variety
       for (let i = neighbors.length - 1; i > 0; i--) {
           const j = Math.floor(Math.random() * (i + 1));
           [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
       }

       for (const n of neighbors) {
           if (findPath(n)) return true;
       }

       // Backtrack
       visited.delete(posKey(curr.r, curr.c));
       solutionPath.pop();
       return false;
    };

    // Retry a few times if path finding fails (unlikely on small open grids but possible)
    let attempts = 0;
    while(attempts < 50) {
        // Reset
        solutionPath.length = 0;
        visited.clear();

        // Random start for this attempt
        const r = Math.floor(Math.random() * size);
        const c = Math.floor(Math.random() * size);

        if (findPath({r, c})) break;
        attempts++;
    }

    if (solutionPath.length !== totalCells) {
        console.error("Failed to generate path");
        // Fallback: Just clear everything to avoid crash
        setFixedCells(new Map());
        setPath([]);
        return;
    }

    // 2. Determine Fixed Cells (Hints)
    const fixed = new Map<string, number>();

    // Always reveal Start (1) and End (Total)
    fixed.set(posKey(solutionPath[0].r, solutionPath[0].c), 1);
    fixed.set(posKey(solutionPath[totalCells-1].r, solutionPath[totalCells-1].c), totalCells);

    // Reveal ~30-40% of intermediate numbers
    const numHints = Math.floor(totalCells * 0.35); 
    for(let i = 0; i < numHints; i++) {
        const idx = Math.floor(Math.random() * (totalCells - 2)) + 1; // 1 to total-2
        const p = solutionPath[idx];
        fixed.set(posKey(p.r, p.c), idx + 1);
    }

    setFixedCells(fixed);

    // 3. Initialize User Path with just the Start
    setPath([solutionPath[0]]);
    setWin(false);
  };

  const resetCurrentLevel = () => {
    // Keep fixed cells, reset user path to just the number 1
    const startEntry = Array.from(fixedCells.entries()).find(([_, val]) => val === 1);
    if (startEntry) {
        const [key] = startEntry;
        const [r, c] = key.split(',').map(Number);
        setPath([{ r, c }]);
        setWin(false);
    }
  };

  // Check if a point is in the current user path
  const getPathIndex = (r: number, c: number) => {
    return path.findIndex(p => p.r === r && p.c === c);
  };

  const handlePointerDown = (r: number, c: number) => {
    if (win) return;
    const index = getPathIndex(r, c);
    // User can only start dragging from the END of their current path
    if (index === path.length - 1) {
        setIsDrawing(true);
    }
  };

  const handlePointerEnter = (r: number, c: number) => {
    if (!isDrawing || win) return;

    const lastPoint = path[path.length - 1];
    const index = getPathIndex(r, c);

    // 1. Backtracking: If we move to the 2nd to last point, we undo
    if (path.length > 1 && index === path.length - 2) {
      // Don't allow removing if it's a fixed number that ISN'T the start? 
      // Actually, standard logic is you can undo anything you drew. 
      // But you can't undo the '1'.
      const currentVal = path.length;
      if (currentVal > 1) { // Can't remove the '1'
         setPath(prev => prev.slice(0, -1));
      }
      return;
    }

    // 2. Moving forward
    if (index === -1) {
      // Check adjacency
      const isAdjacent = Math.abs(lastPoint.r - r) + Math.abs(lastPoint.c - c) === 1;

      if (isAdjacent) {
        const nextVal = path.length + 1;
        const key = posKey(r, c);

        // CHECK: Is this cell a fixed number?
        if (fixedCells.has(key)) {
            const requiredVal = fixedCells.get(key);
            if (requiredVal !== nextVal) {
                return; // Invalid move: Wrong number order
            }
        }

        // Valid move
        const newPath = [...path, { r, c }];
        setPath(newPath);

        // Check Win
        if (newPath.length === gridSize * gridSize) {
          setWin(true);
          setIsDrawing(false);
        }
      }
    }
  };

  const handlePointerUp = () => {
    setIsDrawing(false);
  };

  useEffect(() => {
    window.addEventListener('pointerup', handlePointerUp);
    return () => window.removeEventListener('pointerup', handlePointerUp);
  }, []);

  // Visuals
  const getCellColor = (val: number, isFixed: boolean) => {
    // Rainbow gradient
    const total = gridSize * gridSize;
    const hue = ((val - 1) / (total - 1)) * 280; // 0 to 280 (Red to Purple)

    if (isFixed) return undefined; // Fixed cells handled via class/style logic
    return `hsl(${hue}, 85%, 60%)`;
  };

  // --- RENDERING ---

  if (view === 'MENU') {
    return (
      <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
         <div className="absolute top-4 left-4 z-50">
           <button onClick={onBackToLauncher} className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-700 dark:hover:text-slate-200">← Back</button>
        </div>

        <div className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-2 border-slate-300 dark:border-slate-700 rounded-xl shadow-xl p-8 w-full text-center relative transition-colors duration-300">
           <h1 className="text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-purple-600 mb-2 tracking-tight" style={{ filter: theme === 'dark' ? 'brightness(1.2)' : 'none' }}>
            Zip
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mb-8 font-medium">Connect the numbers in order to fill the grid!</p>

          <div className="flex flex-col gap-3">
             <button onClick={() => startGame('EASY')} className="w-full bg-green-500 hover:bg-green-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-green-700 active:border-b-0 active:translate-y-1 transition-all">
                Easy (4x4)
             </button>
             <button onClick={() => startGame('MEDIUM')} className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-blue-700 active:border-b-0 active:translate-y-1 transition-all">
                Medium (5x5)
             </button>
             <button onClick={() => startGame('HARD')} className="w-full bg-purple-500 hover:bg-purple-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-purple-700 active:border-b-0 active:translate-y-1 transition-all">
                Hard (6x6)
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full dark:text-slate-200">
      {/* Header */}
      <header className="pt-6 pb-2 px-4 text-center relative">
        <button 
          onClick={() => setView('MENU')}
          className="absolute left-4 top-6 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 font-bold transition-colors"
        >
          ← Menu
        </button>
        <h1 className="text-4xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">
          Zip <span className="text-sm font-normal text-slate-400 block sm:inline opacity-70"> - {level}</span>
        </h1>
      </header>

      {/* Game Area */}
      <main className="flex-1 flex flex-col items-center justify-center p-4">

        {/* Progress or Loading */}
        {isGenerating ? (
            <div className="animate-pulse text-xl font-bold text-slate-500">Generating Puzzle...</div>
        ) : (
            <>
                <div className="mb-6 font-mono text-xl font-bold text-slate-600 dark:text-slate-400">
                   {path.length} / {gridSize * gridSize}
                </div>

                {/* The Grid */}
                <div 
                  className="relative bg-white dark:bg-slate-800 p-2 rounded-xl shadow-2xl border-2 border-slate-200 dark:border-slate-700 touch-none select-none"
                  style={{
                     display: 'grid',
                     gridTemplateColumns: `repeat(${gridSize}, 1fr)`,
                     gap: '6px',
                  }}
                >
                   {Array.from({ length: gridSize * gridSize }).map((_, i) => {
                     const r = Math.floor(i / gridSize);
                     const c = i % gridSize;
                     const key = posKey(r, c);

                     // Is it in user path?
                     const pathIndex = getPathIndex(r, c);
                     const isVisited = pathIndex !== -1;
                     const visitNum = pathIndex + 1;

                     // Is it fixed?
                     const fixedNum = fixedCells.get(key);
                     const isFixed = fixedNum !== undefined;

                     // Is it the current head of the path?
                     const isHead = isVisited && visitNum === path.length;

                     // Determine display number
                     const displayNum = isVisited ? visitNum : (isFixed ? fixedNum : '');

                     return (
                       <div
                         key={key}
                         onPointerDown={(e) => {
                             e.preventDefault(); // Prevent scroll
                             handlePointerDown(r, c);
                         }}
                         onPointerEnter={(e) => {
                             handlePointerEnter(r, c);
                         }}
                         className={`
                            w-12 h-12 sm:w-16 sm:h-16 rounded-lg flex items-center justify-center text-xl sm:text-2xl font-bold transition-all duration-200
                            ${isVisited ? 'scale-100 text-white' : 'scale-95 bg-slate-100 dark:bg-slate-900'}
                            ${isFixed && !isVisited ? 'text-slate-400 dark:text-slate-500 border-2 border-slate-300 dark:border-slate-600' : ''}
                            ${isFixed && isVisited ? 'ring-2 ring-white/50' : ''}
                            ${isHead ? 'z-10 scale-110 shadow-lg ring-4 ring-white/50' : ''}
                         `}
                         style={{
                            backgroundColor: isVisited ? getCellColor(visitNum, false) : undefined,
                            boxShadow: isVisited ? 'inset 0 -4px 0 rgba(0,0,0,0.1)' : 'none'
                         }}
                       >
                         {displayNum}
                       </div>
                     );
                   })}
                </div>

                {win && (
                   <div className="mt-8 animate-bounce-in flex flex-col items-center gap-4">
                      <div className="text-3xl font-bold text-green-500 mb-2">Level Complete!</div>
                      <div className="flex gap-4">
                          <button 
                            onClick={() => generatePuzzle(gridSize)}
                            className="px-6 py-3 bg-slate-800 dark:bg-slate-200 text-white dark:text-slate-900 font-bold rounded-full shadow-lg hover:scale-105 transition-transform"
                          >
                            New Puzzle
                          </button>
                      </div>
                   </div>
                )}

                {!win && (
                     <div className="flex gap-4 mt-8">
                         <button 
                            onClick={resetCurrentLevel}
                            className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 font-bold text-sm"
                          >
                            Restart
                          </button>
                          <span className="text-slate-300">|</span>
                          <button 
                            onClick={() => generatePuzzle(gridSize)}
                            className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 font-bold text-sm"
                          >
                            New Puzzle
                          </button>
                     </div>
                )}
            </>
        )}
      </main>
    </div>
  );
};

