  // Check if a point is in the current user path
  const getPathIndex = (r: number, c: number) => {
    return path.findIndex(p => p.r === r && p.c === c);
  };

  const handlePointerDown = (r: number, c: number) => {
    if (win) return;
    const index = getPathIndex(r, c);
    // User can only start dragging from the END of their current path
    if (index === path.length - 1) {
        setIsDrawing(true);
    }
  };

  const handlePointerEnter = (r: number, c: number) => {
    if (!isDrawing || win) return;

    const lastPoint = path[path.length - 1];
    const index = getPathIndex(r, c);

    // 1. Backtracking: If we move to the 2nd to last point, we undo
    if (path.length > 1 && index === path.length - 2) {
      // Don't allow removing if it's a fixed number that ISN'T the start? 
      // Actually, standard logic is you can undo anything you drew. 
      // But you can't undo the '1'.
      const currentVal = path.length;
      if (currentVal > 1) { // Can't remove the '1'
         setPath(prev => prev.slice(0, -1));
      }
      return;
    }

    // 2. Moving forward
    if (index === -1) {
      // Check adjacency
      const isAdjacent = Math.abs(lastPoint.r - r) + Math.abs(lastPoint.c - c) === 1;

      if (isAdjacent) {
        const nextVal = path.length + 1;
        const key = posKey(r, c);

        // CHECK: Is this cell a fixed number?
        if (fixedCells.has(key)) {
            const requiredVal = fixedCells.get(key);
            if (requiredVal !== nextVal) {
                return; // Invalid move: Wrong number order
            }
        }

        // Valid move
        const newPath = [...path, { r, c }];
        setPath(newPath);

        // Check Win
        if (newPath.length === gridSize * gridSize) {
          setWin(true);
          setIsDrawing(false);
        }
      }
    }
  };

  const handlePointerUp = () => {
    setIsDrawing(false);
  };

  useEffect(() => {
    window.addEventListener('pointerup', handlePointerUp);
    return () => window.removeEventListener('pointerup', handlePointerUp);
  }, []);

  // Visuals
  const getCellColor = (val: number, isFixed: boolean) => {
    // Rainbow gradient
    const total = gridSize * gridSize;
    const hue = ((val - 1) / (total - 1)) * 280; // 0 to 280 (Red to Purple)

    if (isFixed) return undefined; // Fixed cells handled via class/style logic
    return `hsl(${hue}, 85%, 60%)`;
  };

  // --- RENDERING ---

  if (view === 'MENU') {
    return (
      <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
         <div className="absolute top-4 left-4 z-50">
           <button onClick={onBackToLauncher} className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-700 dark:hover:text-slate-200">← Back</button>
        </div>

        <div className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-2 border-slate-300 dark:border-slate-700 rounded-xl shadow-xl p-8 w-full text-center relative transition-colors duration-300">
           <h1 className="text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-purple-600 mb-2 tracking-tight" style={{ filter: theme === 'dark' ? 'brightness(1.2)' : 'none' }}>
            Zip
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mb-8 font-medium">Connect the numbers in order to fill the grid!</p>

          <div className="flex flex-col gap-3">
             <button onClick={() => startGame('EASY')} className="w-full bg-green-500 hover:bg-green-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-green-700 active:border-b-0 active:translate-y-1 transition-all">
                Easy (4x4)
             </button>
             <button onClick={() => startGame('MEDIUM')} className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-blue-700 active:border-b-0 active:translate-y-1 transition-all">
                Medium (5x5)
             </button>
             <button onClick={() => startGame('HARD')} className="w-full bg-purple-500 hover:bg-purple-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-purple-700 active:border-b-0 active:translate-y-1 transition-all">
                Hard (6x6)
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full dark:text-slate-200">
      {/* Header */}
      <header className="pt-6 pb-2 px-4 text-center relative">
        <button 
          onClick={() => setView('MENU')}
          className="absolute left-4 top-6 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 font-bold transition-colors"
        >
          ← Menu
        </button>
        <h1 className="text-4xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">
          Zip <span className="text-sm font-normal text-slate-400 block sm:inline opacity-70"> - {level}</span>
        </h1>
      </header>

      {/* Game Area */}
      <main className="flex-1 flex flex-col items-center justify-center p-4">

        {/* Progress or Loading */}
        {isGenerating ? (
            <div className="animate-pulse text-xl font-bold text-slate-500">Generating Puzzle...</div>
        ) : (
            <>
                <div className="mb-6 font-mono text-xl font-bold text-slate-600 dark:text-slate-400">
                   {path.length} / {gridSize * gridSize}
                </div>

                {/* The Grid */}
                <div 
                  className="relative bg-white dark:bg-slate-800 p-2 rounded-xl shadow-2xl border-2 border-slate-200 dark:border-slate-700 touch-none select-none"
                  style={{
                     display: 'grid',
                     gridTemplateColumns: `repeat(${gridSize}, 1fr)`,
                     gap: '6px',
                  }}
                >
                   {Array.from({ length: gridSize * gridSize }).map((_, i) => {
                     const r = Math.floor(i / gridSize);
                     const c = i % gridSize;
                     const key = posKey(r, c);

                     // Is it in user path?
                     const pathIndex = getPathIndex(r, c);
                     const isVisited = pathIndex !== -1;
                     const visitNum = pathIndex + 1;

                     // Is it fixed?
                     const fixedNum = fixedCells.get(key);
                     const isFixed = fixedNum !== undefined;

                     // Is it the current head of the path?
                     const isHead = isVisited && visitNum === path.length;

                     // Determine display number
                     const displayNum = isVisited ? visitNum : (isFixed ? fixedNum : '');

                     return (
                       <div
                         key={key}
                         onPointerDown={(e) => {
                             e.preventDefault(); // Prevent scroll
                             handlePointerDown(r, c);
                         }}
                         onPointerEnter={(e) => {
                             handlePointerEnter(r, c);
                         }}
                         className={`
                            w-12 h-12 sm:w-16 sm:h-16 rounded-lg flex items-center justify-center text-xl sm:text-2xl font-bold transition-all duration-200
                            ${isVisited ? 'scale-100 text-white' : 'scale-95 bg-slate-100 dark:bg-slate-900'}
                            ${isFixed && !isVisited ? 'text-slate-400 dark:text-slate-500 border-2 border-slate-300 dark:border-slate-600' : ''}
                            ${isFixed && isVisited ? 'ring-2 ring-white/50' : ''}
                            ${isHead ? 'z-10 scale-110 shadow-lg ring-4 ring-white/50' : ''}
                         `}
                         style={{
                            backgroundColor: isVisited ? getCellColor(visitNum, false) : undefined,
                            boxShadow: isVisited ? 'inset 0 -4px 0 rgba(0,0,0,0.1)' : 'none'
                         }}
                       >
                         {displayNum}
                       </div>
                     );
                   })}
                </div>

                {win && (
                   <div className="mt-8 animate-bounce-in flex flex-col items-center gap-4">
                      <div className="text-3xl font-bold text-green-500 mb-2">Level Complete!</div>
                      <div className="flex gap-4">
                          <button 
                            onClick={() => generatePuzzle(gridSize)}
                            className="px-6 py-3 bg-slate-800 dark:bg-slate-200 text-white dark:text-slate-900 font-bold rounded-full shadow-lg hover:scale-105 transition-transform"
                          >
                            New Puzzle
                          </button>
                      </div>
                   </div>
                )}

                {!win && (
                     <div className="flex gap-4 mt-8">
                         <button 
                            onClick={resetCurrentLevel}
                            className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 font-bold text-sm"
                          >
                            Restart
                          </button>
                          <span className="text-slate-300">|</span>
                          <button 
                            onClick={() => generatePuzzle(gridSize)}
                            className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 font-bold text-sm"
                          >
                            New Puzzle
                          </button>
                     </div>
                )}
            </>
        )}
      </main>
    </div>
  );
};

export default ZipGame;

import React, { useState, useEffect, useRef } from 'react';

interface ZipGameProps {
  onBackToLauncher: () => void;
  theme: 'light' | 'dark';
}

type Level = 'EASY' | 'MEDIUM' | 'HARD';
type Point = { r: number; c: number };

// Helper to generate a key for the map
const posKey = (r: number, c: number) => `${r},${c}`;

const ZipGame: React.FC<ZipGameProps> = ({ onBackToLauncher, theme }) => {
  const [view, setView] = useState<'MENU' | 'GAME'>('MENU');
  const [level, setLevel] = useState<Level>('EASY');
  const [gridSize, setGridSize] = useState(7);

  // Game State
  const [fixedCells, setFixedCells] = useState<Map<string, number>>(new Map());
  const [path, setPath] = useState<Point[]>([]); // User's current path. Index i is number i+1.
  const [isDrawing, setIsDrawing] = useState(false);
  const [win, setWin] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  // Refs for measurements
  const gridRef = useRef<HTMLDivElement>(null);
  const [cellMetrics, setCellMetrics] = useState({ size: 0, gap: 6 });

  // Update metrics on resize for SVG line calculation
  useEffect(() => {
    const updateMetrics = () => {
      if (gridRef.current) {
        // Assume square grid
        const gridWidth = gridRef.current.offsetWidth;
        // Calculation: gridWidth = (size * N) + (gap * (N-1))
        // size * N = gridWidth - gap * (N-1)
        // size = (gridWidth - gap * (N-1)) / N
        const gap = 6; // px, matches gap-1.5 (6px)
        const N = gridSize;
        const size = (gridWidth - gap * (N - 1)) / N;
        setCellMetrics({ size, gap });
      }
    };

    updateMetrics();
    window.addEventListener('resize', updateMetrics);
    return () => window.removeEventListener('resize', updateMetrics);
  }, [view, gridSize]);

  // Configuration based on level
  const getLevelConfig = (lvl: Level) => {
    switch(lvl) {
      case 'EASY': return { size: 7, hintDensity: 0.4 };   // ~20 hints
      case 'MEDIUM': return { size: 7, hintDensity: 0.25 }; // ~12 hints
      case 'HARD': return { size: 8, hintDensity: 0.25 };   // ~16 hints
      default: return { size: 7, hintDensity: 0.4 };
    }
  };

  const startGame = async (lvl: Level) => {
    const config = getLevelConfig(lvl);
    setGridSize(config.size);
    setLevel(lvl);
    setIsGenerating(true);
    setView('GAME');

    // Allow UI to update before heavy generation
    setTimeout(() => {
        generatePuzzle(config.size, config.hintDensity);
        setIsGenerating(false);
    }, 50);
  };

  const generatePuzzle = (size: number, density: number) => {
    const totalCells = size * size;
    const solutionPath: Point[] = [];
    const visited = new Set<string>();

    const isValid = (r: number, c: number) => r >= 0 && r < size && c >= 0 && c < size;

    // Optimized Backtracking
    // Heuristic: Try to visit neighbors that have fewest available neighbors first (Warnsdorff's rule variant)
    // But for simple grid filling, random is usually fine for < 10x10.

    const findPath = (curr: Point): boolean => {
       solutionPath.push(curr);
       visited.add(posKey(curr.r, curr.c));

       if (solutionPath.length === totalCells) return true;

       // Get neighbors
       let neighbors = [
         { r: curr.r - 1, c: curr.c },
         { r: curr.r + 1, c: curr.c },
         { r: curr.r, c: curr.c - 1 },
         { r: curr.r, c: curr.c + 1 },
       ].filter(n => isValid(n.r, n.c) && !visited.has(posKey(n.r, n.c)));

       // Randomize
       for (let i = neighbors.length - 1; i > 0; i--) {
           const j = Math.floor(Math.random() * (i + 1));
           [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
       }

       for (const n of neighbors) {
           if (findPath(n)) return true;
       }

       visited.delete(posKey(curr.r, curr.c));
       solutionPath.pop();
       return false;
    };

    let attempts = 0;
    let success = false;
    while(attempts < 50) {
        solutionPath.length = 0;
        visited.clear();
        const startR = Math.floor(Math.random() * size);
        const startC = Math.floor(Math.random() * size);

        if (findPath({r: startR, c: startC})) {
            success = true;
            break;
        }
        attempts++;
    }

    if (!success) {
        // Fallback for extreme bad luck: Just fill row by row (snake pattern) so game doesn't crash
        solutionPath.length = 0;
        for(let r=0; r<size; r++) {
            for(let c=0; c<size; c++) {
               // Snake pattern
               let ac = (r % 2 === 0) ? c : (size - 1 - c);
               solutionPath.push({r, c: ac});
            }
        }
    }

    // Determine Hints
    const fixed = new Map<string, number>();

    // Always reveal 1 and Last
    fixed.set(posKey(solutionPath[0].r, solutionPath[0].c), 1);
    fixed.set(posKey(solutionPath[totalCells-1].r, solutionPath[totalCells-1].c), totalCells);

    // Reveal hints based on density
    // We want distributed hints, not just random.
    // Random approach:
    const numHints = Math.floor(totalCells * density); 
    for(let i = 0; i < numHints; i++) {
        // Pick a random index in path (avoiding 0 and last)
        const idx = Math.floor(Math.random() * (totalCells - 2)) + 1;
        const p = solutionPath[idx];
        fixed.set(posKey(p.r, p.c), idx + 1);
    }

    setFixedCells(fixed);
    setPath([solutionPath[0]]); // Start path with '1'
    setWin(false);
  };

  const resetCurrentLevel = () => {
    let startKey: string | undefined;
    for (const [key, val] of fixedCells) {
      if (val === 1) {
        startKey = key;
        break;
      }
    }
    if (startKey) {
        const [rStr, cStr] = startKey.split(',');
        setPath([{ r: Number(rStr), c: Number(cStr) }]);
        setWin(false);
    }
  };

  // Interaction
  const getPathIndex = (r: number, c: number) => {
    return path.findIndex(p => p.r === r && p.c === c);
  };

  const handlePointerDown = (r: number, c: number) => {
    if (win) return;
    const index = getPathIndex(r, c);
    // User can start dragging from the HEAD of their current path
    if (index === path.length - 1) {
        setIsDrawing(true);
    }
  };

  const handlePointerEnter = (r: number, c: number) => {
    if (!isDrawing || win) return;

    const lastPoint = path[path.length - 1];
    const index = getPathIndex(r, c);

    // 1. Backtrack: If we move to the 2nd to last point, we undo
    if (path.length > 1 && index === path.length - 2) {
       // Cannot remove '1'
       setPath(prev => prev.slice(0, -1));
       return;
    }

    // 2. Extend
    if (index === -1) {
      const isAdjacent = Math.abs(lastPoint.r - r) + Math.abs(lastPoint.c - c) === 1;

      if (isAdjacent) {
        const nextVal = path.length + 1;
        const key = posKey(r, c);

        // Validate against Fixed Cells
        if (fixedCells.has(key)) {
            const requiredVal = fixedCells.get(key);
            if (requiredVal !== nextVal) return;
        }

        const newPath = [...path, { r, c }];
        setPath(newPath);

        if (newPath.length === gridSize * gridSize) {
          setWin(true);
          setIsDrawing(false);
        }
      }
    }
  };

  useEffect(() => {
    const stop = () => setIsDrawing(false);
    window.addEventListener('pointerup', stop);
    return () => window.removeEventListener('pointerup', stop);
  }, []);

  // --- SVG PATH CALCULATION ---
  const getSvgPath = () => {
    if (path.length < 2 || cellMetrics.size === 0) return '';

    // Center of cell (r, c) = 
    // x = c * (size + gap) + size/2
    // y = r * (size + gap) + size/2
    const { size, gap } = cellMetrics;
    const half = size / 2;

    return path.map((p, i) => {
        const x = p.c * (size + gap) + half;
        const y = p.r * (size + gap) + half;
        return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
    }).join(' ');
  };

  // --- RENDERING ---

  if (view === 'MENU') {
    return (
      <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
         <div className="absolute top-4 left-4 z-50">
           <button onClick={onBackToLauncher} className="text-slate-500 dark:text-slate-400 font-bold hover:text-slate-700 dark:hover:text-slate-200">← Back</button>
        </div>

        <div className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-2 border-slate-300 dark:border-slate-700 rounded-xl shadow-xl p-8 w-full text-center">
           <h1 className="text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-purple-600 mb-2 tracking-tight">
            Zip
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mb-8 font-medium">Connect numbers to fill the grid.</p>

          <div className="flex flex-col gap-3">
             <button onClick={() => startGame('EASY')} className="w-full bg-green-500 hover:bg-green-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-green-700 active:border-b-0 active:translate-y-1 transition-all">
                Easy (7x7)
             </button>
             <button onClick={() => startGame('MEDIUM')} className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-blue-700 active:border-b-0 active:translate-y-1 transition-all">
                Medium (7x7)
             </button>
             <button onClick={() => startGame('HARD')} className="w-full bg-purple-500 hover:bg-purple-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-purple-700 active:border-b-0 active:translate-y-1 transition-all">
                Hard (8x8)
             </button>
          </div>
        </div>
      </div>
    );
  }

  // Calculate gradient colors for path
  // Start: Blue, End: Purple/Pink
  // We can use SVG linearGradient for the whole path, but curve might be complex.
  // Simple solid color or simple gradient is safer. 
  // Let's use a nice stroke color that contrasts well.

  return (
    <div className="flex flex-col h-full w-full dark:text-slate-200 select-none">
      <header className="pt-6 pb-2 px-4 text-center relative z-20">
        <button 
          onClick={() => setView('MENU')}
          className="absolute left-4 top-6 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 font-bold transition-colors"
        >
          ← Menu
        </button>
        <h1 className="text-4xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">
          Zip <span className="text-sm font-normal text-slate-400 block sm:inline opacity-70"> - {level}</span>
        </h1>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center p-4 relative">

        {isGenerating ? (
            <div className="animate-pulse text-xl font-bold text-slate-500">Generating Puzzle...</div>
        ) : (
            <>
                <div className="mb-4 font-mono text-xl font-bold text-slate-600 dark:text-slate-400">
                   {path.length} / {gridSize * gridSize}
                </div>

                <div className="relative p-2 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border-2 border-slate-200 dark:border-slate-700 touch-none">
                   {/* SVG Layer */}
                   <svg className="absolute inset-0 w-full h-full z-10 pointer-events-none rounded-xl" style={{ padding: '8px' }}>
                      <defs>
                        <linearGradient id="pathGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                          <stop offset="0%" stopColor="#3b82f6" />
                          <stop offset="100%" stopColor="#a855f7" />
                        </linearGradient>
                      </defs>
                      <path 
                        d={getSvgPath()} 
                        fill="none" 
                        stroke="url(#pathGradient)" 
                        strokeWidth={cellMetrics.size * 0.4} 
                        strokeLinecap="round" 
                        strokeLinejoin="round"
                        className="transition-all duration-75 ease-linear"
                        style={{ filter: 'drop-shadow(0px 2px 3px rgba(0,0,0,0.2))' }}
                      />
                   </svg>

                   {/* Grid Layer */}
                   <div 
                      ref={gridRef}
                      className="relative z-20"
                      style={{
                         display: 'grid',
                         gridTemplateColumns: `repeat(${gridSize}, 1fr)`,
                         gap: '6px',
                      }}
                    >
                       {Array.from({ length: gridSize * gridSize }).map((_, i) => {
                         const r = Math.floor(i / gridSize);
                         const c = i % gridSize;
                         const key = posKey(r, c);

                         const pathIndex = getPathIndex(r, c);
                         const isVisited = pathIndex !== -1;
                         const visitNum = pathIndex + 1;
                         const fixedNum = fixedCells.get(key);
                         const isFixed = fixedNum !== undefined;
                         const isHead = isVisited && visitNum === path.length;

                         // Logic for display
                         // If visited: show current number (white on transparent/gradient)
                         // If fixed (and not visited yet): show fixed number (dark circle)

                         const showNum = isVisited ? visitNum : (isFixed ? fixedNum : '');

                         return (
                           <div
                             key={key}
                             onPointerDown={(e) => {
                                 e.preventDefault(); 
                                 handlePointerDown(r, c);
                             }}
                             onPointerEnter={(e) => {
                                 handlePointerEnter(r, c);
                             }}
                             className={`
                                rounded-full flex items-center justify-center font-bold transition-all duration-200
                                ${isVisited 
                                   ? 'text-white text-lg sm:text-2xl scale-100' 
                                   : (isFixed 
                                       ? 'bg-slate-200 dark:bg-slate-700 text-slate-800 dark:text-slate-200 scale-90 shadow-inner text-sm sm:text-xl' 
                                       : 'bg-slate-100 dark:bg-slate-900/50 scale-50')
                                }
                                ${isHead ? 'ring-4 ring-white/60 scale-110 shadow-lg' : ''}
                             `}
                             style={{
                                width: '45px', // Fallback
                                height: '45px', // Fallback
                                maxWidth: '12vw',
                                maxHeight: '12vw',
                                aspectRatio: '1/1'
                             }}
                           >
                             <span className="relative z-10" style={{ textShadow: isVisited ? '0 1px 2px rgba(0,0,0,0.3)' : 'none'}}>
                               {showNum}
                             </span>
                           </div>
                         );
                       })}
                    </div>
                </div>

                {/* Win Modal */}
                {win && (
                   <div className="mt-6 flex flex-col items-center gap-4 animate-bounce-in">
                      <div className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-green-500 to-emerald-400">Level Complete!</div>
                      <div className="flex gap-4">
                          <button 
                            onClick={() => generatePuzzle(gridSize, getLevelConfig(level).hintDensity)}
                            className="px-8 py-3 bg-slate-800 dark:bg-slate-100 text-white dark:text-slate-900 font-bold rounded-full shadow-lg hover:scale-105 transition-transform"
                          >
                            Next Puzzle
                          </button>
                      </div>
                   </div>
                )}

                {/* Controls */}
                {!win && (
                     <div className="flex gap-6 mt-8">
                         <button 
                            onClick={resetCurrentLevel}
                            className="flex items-center gap-2 text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 font-bold transition-colors"
                          >
