const ZipGame: React.FC<ZipGameProps> = ({ onBackToLauncher, theme }) => {
  const [view, setView] = useState<'MENU' | 'GAME'>('MENU');
  const [level, setLevel] = useState<Level>('EASY');
  const [gridSize, setGridSize] = useState(4);

  // Game State
  const [fixedCells, setFixedCells] = useState<Map<string, number>>(new Map());
  const [path, setPath] = useState<Point[]>([]); // User's current path. Index i is number i+1.
  const [isDrawing, setIsDrawing] = useState(false);
  const [win, setWin] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  // Refs for measurements
  const gridRef = useRef<HTMLDivElement>(null);
  const [cellMetrics, setCellMetrics] = useState({ size: 0, gap: 6 });

  // Update metrics on resize for SVG line calculation
  useEffect(() => {
    const updateMetrics = () => {
      if (gridRef.current) {
        const gridWidth = gridRef.current.offsetWidth;
        const gap = 6; // px
        const N = gridSize;
        const size = (gridWidth - gap * (N - 1)) / N;
        setCellMetrics({ size, gap });
      }
    };

    updateMetrics();
    window.addEventListener('resize', updateMetrics);
    return () => window.removeEventListener('resize', updateMetrics);
  }, [view, gridSize]);

  // Configuration based on level
  const getLevelConfig = (lvl: Level) => {
    switch(lvl) {
      case 'EASY': return { size: 4, hintDensity: 0.4 };   // 4x4
      case 'MEDIUM': return { size: 5, hintDensity: 0.3 }; // 5x5
      case 'HARD': return { size: 8, hintDensity: 0.2 };   // 8x8
      default: return { size: 4, hintDensity: 0.4 };
    }
  };

  const startGame = async (lvl: Level) => {
    const config = getLevelConfig(lvl);
    setGridSize(config.size);
    setLevel(lvl);
    setIsGenerating(true);
    setView('GAME');

    // Use a tiny timeout to let the React render cycle update the "Generating..." UI
    setTimeout(() => {
        generatePuzzle(config.size, config.hintDensity);
        setIsGenerating(false);
    }, 10);
  };

  const generatePuzzle = (size: number, density: number) => {
    const totalCells = size * size;
    let solutionPath: Point[] = [];

    // --- Optimized Generation Logic (Warnsdorff's Rule) ---
    // This allows 8x8 to generate instantly.

    const isValid = (r: number, c: number) => r >= 0 && r < size && c >= 0 && c < size;
    const visited = new Int8Array(size * size).fill(0); // Faster than Set

    const getIdx = (r: number, c: number) => r * size + c;

    const getNeighbors = (r: number, c: number) => {
        const moves = [
            { r: r - 1, c: c }, { r: r + 1, c: c },
            { r: r, c: c - 1 }, { r: r, c: c + 1 }
        ];
        return moves.filter(m => isValid(m.r, m.c) && visited[getIdx(m.r, m.c)] === 0);
    };

    const solve = (curr: Point): boolean => {
       solutionPath.push(curr);
       visited[getIdx(curr.r, curr.c)] = 1;

       if (solutionPath.length === totalCells) return true;

       let neighbors = getNeighbors(curr.r, curr.c);

       // HEURISTIC: Sort neighbors by their degree (how many free neighbors they have)
       // This prevents getting stuck in dead ends.
       if (neighbors.length > 0) {
           neighbors.sort((a, b) => {
               const degA = getNeighbors(a.r, a.c).length;
               const degB = getNeighbors(b.r, b.c).length;
               return degA - degB;
           });

           // Add a little randomness for variety so it's not the same puzzle every time
           // Only swap if degrees are equal or very close
           if (neighbors.length > 1 && Math.random() > 0.5) {
               const swapIdx = 1; 
               // Simple swap of first two best candidates
               [neighbors[0], neighbors[swapIdx]] = [neighbors[swapIdx], neighbors[0]];
           }
       }

       for (const n of neighbors) {
           if (solve(n)) return true;
       }

       // Backtrack
       visited[getIdx(curr.r, curr.c)] = 0;
       solutionPath.pop();
       return false;
    };

    // Attempt generation
    let success = false;
    // Try a few random start points if first fails
    for(let attempt = 0; attempt < 10; attempt++) {
        visited.fill(0);
        solutionPath = [];
        const startR = Math.floor(Math.random() * size);
        const startC = Math.floor(Math.random() * size);

        if (solve({r: startR, c: startC})) {
            success = true;
            break;
        }
    }

    // Fallback: If heuristic fails (rare), just use a snake pattern
    if (!success) {
        solutionPath = [];
        for(let r=0; r<size; r++) {
            for(let c=0; c<size; c++) {
               let ac = (r % 2 === 0) ? c : (size - 1 - c);
               solutionPath.push({r, c: ac});
            }
        }
    }

    // --- Create Hints ---
    const fixed = new Map<string, number>();

    // Always reveal 1 and Last
    fixed.set(posKey(solutionPath[0].r, solutionPath[0].c), 1);
    fixed.set(posKey(solutionPath[totalCells-1].r, solutionPath[totalCells-1].c), totalCells);

    // Random hints
    const numHints = Math.max(0, Math.floor(totalCells * density) - 2); 
    const indices = Array.from({length: totalCells - 2}, (_, i) => i + 1); // 1 to total-2

    // Shuffle indices to pick random spots
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }

    for(let i = 0; i < numHints; i++) {
        const idx = indices[i]; // Actual index in path
        const p = solutionPath[idx];
        fixed.set(posKey(p.r, p.c), idx + 1);
    }

    setFixedCells(fixed);
    setPath([solutionPath[0]]); // Start path with '1'
    setWin(false);
  };

