           <h1 className="text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-purple-600 mb-2 tracking-tight">
            Zip
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mb-8 font-medium">Connect numbers to fill the grid.</p>

