                Easy (4x4)
             </button>
             <button onClick={() => startGame('MEDIUM')} className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-blue-700 active:border-b-0 active:translate-y-1 transition-all">
                Medium (5x5)
             </button>
             <button onClick={() => startGame('HARD')} className="w-full bg-purple-500 hover:bg-purple-600 text-white font-bold py-4 rounded-xl shadow-md border-b-4 border-purple-700 active:border-b-0 active:translate-y-1 transition-all">
                Hard (8x8)
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full dark:text-slate-200 select-none">
      <header className="pt-6 pb-2 px-4 text-center relative z-20">
        <button 
          onClick={() => setView('MENU')}
          className="absolute left-4 top-6 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 font-bold transition-colors"
        >
          ← Menu
        </button>
        <h1 className="text-4xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">
          Zip <span className="text-sm font-normal text-slate-400 block sm:inline opacity-70"> - {level} ({gridSize}x{gridSize})</span>
        </h1>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center p-4 relative">

        {isGenerating ? (
            <div className="flex flex-col items-center gap-4 animate-pulse">
                <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                <div className="text-xl font-bold text-slate-500">Generating Puzzle...</div>
            </div>
        ) : (
            <>
                <div className="mb-4 font-mono text-xl font-bold text-slate-600 dark:text-slate-400">
                   {path.length} / {gridSize * gridSize}
                </div>

                <div className="relative p-2 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border-2 border-slate-200 dark:border-slate-700 touch-none">
                   {/* SVG Layer */}
                   <svg className="absolute inset-0 w-full h-full z-10 pointer-events-none rounded-xl" style={{ padding: '8px' }}>
                      <defs>
                        <linearGradient id="pathGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                          <stop offset="0%" stopColor="#3b82f6" />
                          <stop offset="100%" stopColor="#a855f7" />
                        </linearGradient>
                      </defs>
                      <path 
                        d={getSvgPath()} 
                        fill="none" 
                        stroke="url(#pathGradient)" 
                        strokeWidth={cellMetrics.size * 0.4} 
                        strokeLinecap="round" 
                        strokeLinejoin="round"
                        className="transition-all duration-75 ease-linear"
                        style={{ filter: 'drop-shadow(0px 2px 3px rgba(0,0,0,0.2))' }}
                      />
                   </svg>

                   {/* Grid Layer */}
                   <div 
                      ref={gridRef}
                      className="relative z-20"
                      style={{
                         display: 'grid',
                         gridTemplateColumns: `repeat(${gridSize}, 1fr)`,
                         gap: '6px',
                      }}
                    >
                       {Array.from({ length: gridSize * gridSize }).map((_, i) => {
                         const r = Math.floor(i / gridSize);
                         const c = i % gridSize;
                         const key = posKey(r, c);

                         const pathIndex = getPathIndex(r, c);
                         const isVisited = pathIndex !== -1;
                         const visitNum = pathIndex + 1;
                         const fixedNum = fixedCells.get(key);
                         const isFixed = fixedNum !== undefined;
                         const isHead = isVisited && visitNum === path.length;

                         const showNum = isVisited ? visitNum : (isFixed ? fixedNum : '');

                         return (
                           <div
                             key={key}
                             onPointerDown={(e) => {
                                 e.preventDefault(); 
                                 handlePointerDown(r, c);
                             }}
                             onPointerEnter={(e) => {
                                 handlePointerEnter(r, c);
                             }}
                             className={`
                                rounded-full flex items-center justify-center font-bold transition-all duration-200
                                ${isVisited 
                                   ? 'text-white text-lg sm:text-2xl scale-100' 
                                   : (isFixed 
                                       ? 'bg-slate-200 dark:bg-slate-700 text-slate-800 dark:text-slate-200 scale-90 shadow-inner text-sm sm:text-xl' 
                                       : 'bg-slate-100 dark:bg-slate-900/50 scale-50')
                                }
                                ${isHead ? 'ring-4 ring-white/60 scale-110 shadow-lg' : ''}
                             `}
                             style={{
                                width: '45px', // Fallback
                                height: '45px', // Fallback
                                maxWidth: '12vw',
                                maxHeight: '12vw',
                                aspectRatio: '1/1'
                             }}
                           >
                             <span className="relative z-10" style={{ textShadow: isVisited ? '0 1px 2px rgba(0,0,0,0.3)' : 'none'}}>
                               {showNum}
                             </span>
                           </div>
                         );
                       })}
                    </div>
                </div>

                {/* Win Modal */}
                {win && (
                   <div className="mt-6 flex flex-col items-center gap-4 animate-bounce-in">
                      <div className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-green-500 to-emerald-400">Level Complete!</div>
                      <div className="flex gap-4">
                          <button 
                            onClick={() => generatePuzzle(gridSize, getLevelConfig(level).hintDensity)}
                            className="px-8 py-3 bg-slate-800 dark:bg-slate-100 text-white dark:text-slate-900 font-bold rounded-full shadow-lg hover:scale-105 transition-transform"
                          >
                            Next Puzzle
                          </button>
                      </div>
                   </div>
                )}

                {/* Controls */}
                {!win && (
                     <div className="flex gap-6 mt-8">
                         <button 
                            onClick={resetCurrentLevel}
                            className="flex items-center gap-2 text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 font-bold transition-colors"
                          >
                            <span>↺</span> Restart
                          </button>
                          <button 
                            onClick={() => generatePuzzle(gridSize, getLevelConfig(level).hintDensity)}
                            className="flex items-center gap-2 text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 font-bold transition-colors"
                          >
                            <span>🎲</span> New
                          </button>
                     </div>
                )}
            </>
        )}
      </main>
    </div>
  );
};

