import React, { memo, useEffect, useState } from 'react';
import { PLAYER_X, CELL_SIZE, CORNER_SIZE } from '../constants';
import { GameState, LineType } from '../types';

interface GridProps {
  gameState: GameState;
  onLineClick: (type: LineType, row: number, col: number) => void;
  rows: number;
  cols: number;
  disabled?: boolean;
}

const isHLineFilled = (gameState: GameState, r: number, c: number) => gameState.hLines[r]?.[c];
const isVLineFilled = (gameState: GameState, r: number, c: number) => gameState.vLines[r]?.[c];

const Grid: React.FC<GridProps> = ({ gameState, onLineClick, rows, cols, disabled = false }) => {
  const [scale, setScale] = useState(1);

  useEffect(() => {
    const handleResize = () => {
      const gridPadding = 32; // Reduced padding
      const boardWidth = cols * CORNER_SIZE + (cols - 1) * CELL_SIZE + gridPadding;
      const availableWidth = window.innerWidth;
      const availableHeight = window.innerHeight - 200; // Account for scoreboard

      // Calculate width scale
      let newScale = 1;
      if (boardWidth > availableWidth) {
        newScale = (availableWidth - 32) / boardWidth;
      }

      // Check height constraint as well to fit on screen
      const boardHeight = rows * CORNER_SIZE + (rows - 1) * CELL_SIZE + gridPadding;
      if (boardHeight > availableHeight && availableHeight > 0) {
          const hScale = availableHeight / boardHeight;
          if (hScale < newScale) newScale = hScale;
      }

      setScale(newScale);
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [cols, rows]);

  const renderHorizontalRow = (rowIndex: number) => {
    const items = [];
    for (let col = 0; col < cols; col++) {
      // DOT
      items.push(
        <div 
          key={`dot-${rowIndex}-${col}`} 
          className="relative z-20 flex-shrink-0 flex items-center justify-center"
          style={{ width: CORNER_SIZE, height: CORNER_SIZE }}
        >
          <div className="w-2 h-2 sm:w-2.5 sm:h-2.5 rounded-full bg-slate-800 dark:bg-slate-200 shadow-sm" />
        </div>
      );

      // H-LINE
      if (col < cols - 1) {
        const isFilled = isHLineFilled(gameState, rowIndex, col);
        const isInteractive = !disabled && !isFilled && !gameState.winner;

        items.push(
          <div 
            key={`h-${rowIndex}-${col}`}
            className={`relative flex items-center justify-center flex-shrink-0 group ${!isFilled && !disabled ? 'cursor-pointer' : ''}`}
            style={{ width: CELL_SIZE, height: CORNER_SIZE }} 
            onClick={() => isInteractive && onLineClick('horizontal', rowIndex, col)}
          >
            {/* Hit area */}
            <div className={`absolute -top-2 -bottom-2 left-0 right-0 z-10 ${isInteractive ? 'hover:bg-slate-400/10 dark:hover:bg-slate-500/10 rounded-full' : ''}`} />

            {/* Visual Line */}
            <div 
              className={`h-1.5 rounded-full transition-all duration-300 ease-out ${
                isFilled 
                  ? 'bg-slate-800 dark:bg-slate-100 w-[110%] z-10 shadow-sm scale-100' 
                  : 'bg-slate-300/50 dark:bg-slate-700/50 w-full scale-90 group-hover:bg-slate-400 dark:group-hover:bg-slate-600'
              }`}
            />
          </div>
        );
      }
    }
    return (
      <div key={`row-h-${rowIndex}`} className="flex items-center leading-none">
        {items}
      </div>
    );
  };

  const renderVerticalRow = (rowIndex: number) => {
    const items = [];
    for (let col = 0; col < cols; col++) {
      const isFilled = isVLineFilled(gameState, rowIndex, col);
      const isInteractive = !disabled && !isFilled && !gameState.winner;

      // V-LINE
      items.push(
        <div 
          key={`v-${rowIndex}-${col}`}
          className={`relative flex flex-col items-center justify-start flex-shrink-0 group ${!isFilled && !disabled ? 'cursor-pointer' : ''}`}
          style={{ height: CELL_SIZE, width: CORNER_SIZE }}
          onClick={() => isInteractive && onLineClick('vertical', rowIndex, col)}
        >
          {/* Hit area */}
          <div className={`absolute -left-2 -right-2 top-0 bottom-0 z-10 ${isInteractive ? 'hover:bg-slate-400/10 dark:hover:bg-slate-500/10 rounded-full' : ''}`} />

          {/* Visual Line */}
          <div 
            className={`w-1.5 rounded-full transition-all duration-300 ease-out ${
              isFilled 
                ? 'bg-slate-800 dark:bg-slate-100 h-[110%] z-10 shadow-sm scale-100' 
                : 'bg-slate-300/50 dark:bg-slate-700/50 h-full scale-90 group-hover:bg-slate-400 dark:group-hover:bg-slate-600'
            }`}
          />
        </div>
      );

      // SQUARE
      if (col < cols - 1) {
        const owner = gameState.squares[rowIndex]?.[col];
        items.push(
          <div 
            key={`sq-${rowIndex}-${col}`}
            className="flex items-center justify-center relative flex-shrink-0"
            style={{ width: CELL_SIZE, height: CELL_SIZE }}
          >
            {owner && (
              <div className="w-full h-full p-1 animate-pop">
                 <div className={`w-full h-full rounded-md shadow-inner flex items-center justify-center backdrop-blur-sm ${
                    owner === PLAYER_X 
                      ? 'bg-blue-500/20 border border-blue-500/30' 
                      : 'bg-red-500/20 border border-red-500/30'
                 }`}>
                   <span className={`text-xl font-black drop-shadow-sm ${owner === PLAYER_X ? 'text-blue-600 dark:text-blue-400' : 'text-red-600 dark:text-red-400'}`}>
                     {owner}
                   </span>
                 </div>
              </div>
            )}
          </div>
        );
      }
    }

    return (
      <div key={`row-v-${rowIndex}`} className="flex items-start leading-none">
        {items}
      </div>
    );
  };

  return (
    <div style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }} className="my-auto transition-transform duration-300 ease-out">
      <div className={`inline-flex flex-col p-6 bg-white/60 dark:bg-slate-800/60 backdrop-blur-md border border-white/40 dark:border-slate-700 shadow-2xl rounded-[2rem] select-none transition-all duration-500 ${disabled && !gameState.winner ? 'opacity-90 grayscale-[0.3]' : 'opacity-100'}`}>
        {Array.from({ length: rows }).map((_, r) => (
          <React.Fragment key={r}>
            {renderHorizontalRow(r)}
            {r < rows - 1 && renderVerticalRow(r)}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
};

export default memo(Grid);

import React, { useState, useCallback, useRef } from 'react';
import { DataConnection, Peer } from 'peerjs';
import { 
  PLAYER_X, 
  PLAYER_O, 
  Player 
} from '../constants';
import { GameState, LineType, GameConfig, NetworkMessage } from '../types';
import Grid from './Grid';
import ScoreBoard from './ScoreBoard';
import SetupScreen from './SetupScreen';
import MenuScreen from './MenuScreen';
import OnlineSetup from './OnlineSetup';

type ViewState = 'MENU' | 'SETUP_OFFLINE' | 'SETUP_ONLINE' | 'GAME';

const createInitialState = (rows: number, cols: number): GameState => {
  const hLines = Array(rows).fill(null).map(() => Array(cols - 1).fill(false));
  const vLines = Array(rows - 1).fill(null).map(() => Array(cols).fill(false));
  const squares = Array(rows - 1).fill(null).map(() => Array(cols - 1).fill(null));

  return {
    hLines,
    vLines,
    squares,
    currentPlayer: PLAYER_X,
    scores: { [PLAYER_X]: 0, [PLAYER_O]: 0 },
    winner: null,
    moveHistory: []
  };
};

interface DotsGameProps {
  onBackToLauncher: () => void;
  theme: 'light' | 'dark';
  onToggleTheme: () => void;
}

const DotsGame: React.FC<DotsGameProps> = ({ onBackToLauncher, theme, onToggleTheme }) => {
  const [view, setView] = useState<ViewState>('MENU');
  const [gameConfig, setGameConfig] = useState<GameConfig | null>(null);
  const [gameState, setGameState] = useState<GameState | null>(null);

  const connectionRef = useRef<DataConnection | null>(null);
  const peerRef = useRef<Peer | null>(null);

  const processMove = (prev: GameState, type: LineType, r: number, c: number, rows: number, cols: number): GameState => {
      if (type === 'horizontal') {
        if (prev.hLines[r][c]) return prev; 
      } else {
        if (prev.vLines[r][c]) return prev;
      }

      const newHLines = prev.hLines.map(row => [...row]);
      const newVLines = prev.vLines.map(row => [...row]);
      const newSquares = prev.squares.map(row => [...row]);
      let newScores = { ...prev.scores };
      let squareCompleted = false;

      if (type === 'horizontal') newHLines[r][c] = true;
      else newVLines[r][c] = true;

      const ROWS = rows;
      const COLS = cols;

      if (type === 'horizontal') {
        if (r > 0 && newHLines[r-1][c] && newHLines[r][c] && newVLines[r-1][c] && newVLines[r-1][c+1]) {
            newSquares[r-1][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
        if (r < ROWS - 1 && newHLines[r][c] && newHLines[r+1][c] && newVLines[r][c] && newVLines[r][c+1]) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
      } else {
        if (c > 0 && newHLines[r][c-1] && newHLines[r+1][c-1] && newVLines[r][c-1] && newVLines[r][c]) {
            newSquares[r][c-1] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
        if (c < COLS - 1 && newHLines[r][c] && newHLines[r+1][c] && newVLines[r][c] && newVLines[r][c+1]) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
      }

      const totalSquares = (ROWS - 1) * (COLS - 1);
      const filledSquares = newScores[PLAYER_X] + newScores[PLAYER_O];
      let winner = null;
      if (filledSquares === totalSquares) {
        if (newScores[PLAYER_X] > newScores[PLAYER_O]) winner = PLAYER_X;
        else if (newScores[PLAYER_O] > newScores[PLAYER_X]) winner = PLAYER_O;
        else winner = 'Draw';
      }

      const nextPlayer = squareCompleted ? prev.currentPlayer : (prev.currentPlayer === PLAYER_X ? PLAYER_O : PLAYER_X);

      return {
        ...prev,
        hLines: newHLines,
        vLines: newVLines,
        squares: newSquares,
        scores: newScores,
        currentPlayer: nextPlayer,
        winner: winner as any
      };
  };

  const handleStartOffline = (config: { p1Name: string; p2Name: string; gridSize: number }) => {
    const fullConfig: GameConfig = { ...config, mode: 'OFFLINE' };
    setGameConfig(fullConfig);
    setGameState(createInitialState(config.gridSize, config.gridSize));
    setView('GAME');
  };

  const handleStartOnline = (config: GameConfig, conn: DataConnection, peer: Peer) => {
    connectionRef.current = conn;
    peerRef.current = peer;
    setGameConfig(config);
    setGameState(createInitialState(config.gridSize, config.gridSize));
    setView('GAME');

    conn.on('data', (data: any) => {
      const msg = data as NetworkMessage;
      if (msg.type === 'MOVE') {
        setGameState(prev => {
          if (!prev) return null;
          return processMove(prev, msg.lineType, msg.r, msg.c, config.gridSize, config.gridSize);
        });
      } else if (msg.type === 'RESTART') {
        setGameState(createInitialState(config.gridSize, config.gridSize));
      } else if (msg.type === 'QUIT') {
        alert('Opponent has left the game.');
        quitGame();
      }
    });

    conn.on('close', () => {
      alert('Connection lost.');
      quitGame();
    });
  };

  const quitGame = () => {
    if (connectionRef.current) {
      try { connectionRef.current.send({ type: 'QUIT' }); } catch(e) {}
      connectionRef.current.close();
      connectionRef.current = null;
    }

    if (peerRef.current) {
      peerRef.current.destroy();
      peerRef.current = null;
    }

    setGameConfig(null);
    setGameState(null);
    setView('MENU');
  };

  const resetGame = () => {
    if (!gameConfig) return;

    if (gameConfig.mode === 'ONLINE') {
        if (window.confirm("Do you want to leave the game?")) {
            quitGame();
        }
       return;
    }

    setGameState(createInitialState(gameConfig.gridSize, gameConfig.gridSize));
  };

  const handleLineClick = useCallback((type: LineType, r: number, c: number) => {
    if (!gameConfig || !gameState) return;

    if (gameConfig.mode === 'ONLINE' && gameConfig.myPlayer !== gameState.currentPlayer) {
      return; 
    }

    setGameState(prev => {
      if (!prev) return null;
      const newState = processMove(prev, type, r, c, gameConfig.gridSize, gameConfig.gridSize);

      if (gameConfig.mode === 'ONLINE' && connectionRef.current) {
         if (newState !== prev) {
             const msg: NetworkMessage = { type: 'MOVE', lineType: type, r, c };
             connectionRef.current.send(msg);
         }
      }

      return newState;
    });
  }, [gameConfig, gameState]);

  if (view === 'MENU') {
    return (
      <>
        <div className="absolute top-4 left-4 z-50">
           <button onClick={onBackToLauncher} className="flex items-center gap-2 px-4 py-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur rounded-full text-slate-600 dark:text-slate-300 font-bold hover:bg-white dark:hover:bg-slate-700 transition-all shadow-sm">
              <span className="text-lg">←</span> Back
           </button>
        </div>
        <MenuScreen onSelectMode={(mode) => setView(mode === 'ONLINE' ? 'SETUP_ONLINE' : 'SETUP_OFFLINE')} theme={theme} onToggleTheme={onToggleTheme} />
      </>
    );
  }

  if (view === 'SETUP_OFFLINE') {
    return <SetupScreen onStart={handleStartOffline} onBack={() => setView('MENU')} />;
  }

  if (view === 'SETUP_ONLINE') {
    return <OnlineSetup onStartGame={handleStartOnline} onBack={() => setView('MENU')} />;
  }

  if (!gameConfig || !gameState) return null;

  return (
    <div className="flex flex-col h-full w-full relative">
      <div className="absolute top-4 left-4 z-30 flex gap-2">
        <button 
            onClick={quitGame}
            className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-200/80 dark:bg-slate-700/80 text-slate-600 dark:text-slate-300 hover:bg-slate-300 dark:hover:bg-slate-600 font-bold transition-all backdrop-blur shadow-sm"
          >
            ✕
        </button>
      </div>

      {gameConfig.mode === 'ONLINE' && (
             <div className="absolute right-4 top-4 z-30 px-3 py-1 bg-blue-100 dark:bg-blue-900/50 rounded-full text-xs font-bold text-blue-600 dark:text-blue-300 border border-blue-200 dark:border-blue-800">
                 Room: {gameConfig.roomId}
             </div>
      )}

      {/* Game Content Container - Allows scrolling of the grid while keeping header available */}
      <div className="flex flex-col h-full overflow-hidden pt-16 sm:pt-6">
        <ScoreBoard 
          scores={gameState.scores} 
          currentPlayer={gameState.currentPlayer} 
          winner={gameState.winner}
          onReset={resetGame}
          p1Name={gameConfig.p1Name}
          p2Name={gameConfig.p2Name}
          myPlayer={gameConfig.myPlayer}
        />

        <div className="flex-1 w-full overflow-y-auto overflow-x-hidden flex items-start justify-center pb-8 px-4 game-scroll">
           <Grid 
             gameState={gameState} 
             onLineClick={handleLineClick} 
             rows={gameConfig.gridSize} 
             cols={gameConfig.gridSize} 
             disabled={gameConfig.mode === 'ONLINE' && gameState.currentPlayer !== gameConfig.myPlayer}
            />
        </div>
      </div>
    </div>
  );
}

export default DotsGame;

import React, { memo, useEffect, useState } from 'react';
import { PLAYER_X, CELL_SIZE, CORNER_SIZE } from '../constants';
import { GameState, LineType } from '../types';

interface GridProps {
  gameState: GameState;
  onLineClick: (type: LineType, row: number, col: number) => void;
  rows: number;
  cols: number;
  disabled?: boolean;
}

const isHLineFilled = (gameState: GameState, r: number, c: number) => gameState.hLines[r]?.[c];
const isVLineFilled = (gameState: GameState, r: number, c: number) => gameState.vLines[r]?.[c];

const Grid: React.FC<GridProps> = ({ gameState, onLineClick, rows, cols, disabled = false }) => {
  const [scale, setScale] = useState(1);

  useEffect(() => {
    const handleResize = () => {
      const gridPadding = 64; // Account for the p-8 padding (32px * 2)
      const boardWidth = cols * CORNER_SIZE + (cols - 1) * CELL_SIZE + gridPadding;
      const availableWidth = window.innerWidth;
      const availableHeight = window.innerHeight - 180; // Account for scoreboard

      // Calculate width scale
      let newScale = 1;
      if (boardWidth > availableWidth) {
        newScale = (availableWidth - 32) / boardWidth;
      }

      // Check height constraint
      const boardHeight = rows * CORNER_SIZE + (rows - 1) * CELL_SIZE + gridPadding;
      if (boardHeight > availableHeight && availableHeight > 0) {
          const hScale = availableHeight / boardHeight;
          if (hScale < newScale) newScale = hScale;
      }

      setScale(newScale);
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [cols, rows]);

  const renderHorizontalRow = (rowIndex: number) => {
    const items = [];
    for (let col = 0; col < cols; col++) {
      // DOT
      items.push(
        <div 
          key={`dot-${rowIndex}-${col}`} 
          className="relative z-20 flex-shrink-0 flex items-center justify-center"
          style={{ width: CORNER_SIZE, height: CORNER_SIZE }}
        >
          <div className="w-3 h-3 sm:w-3.5 sm:h-3.5 rounded-full bg-slate-800 dark:bg-slate-200 shadow-[0_0_0_2px_rgba(255,255,255,1)] dark:shadow-[0_0_0_2px_rgba(30,41,59,1)]" />
        </div>
      );

      // H-LINE
      if (col < cols - 1) {
        const isFilled = isHLineFilled(gameState, rowIndex, col);
        const isInteractive = !disabled && !isFilled && !gameState.winner;

        items.push(
          <div 
            key={`h-${rowIndex}-${col}`}
            className={`relative flex items-center justify-center flex-shrink-0 group ${!isFilled && !disabled ? 'cursor-pointer' : ''}`}
            style={{ width: CELL_SIZE, height: CORNER_SIZE }} 
            onClick={() => isInteractive && onLineClick('horizontal', rowIndex, col)}
          >
            {/* Hit area */}
            <div className={`absolute -top-3 -bottom-3 left-0 right-0 z-10 ${isInteractive ? 'hover:bg-blue-500/10 dark:hover:bg-blue-400/10 rounded' : ''}`} />

            {/* Visual Line */}
            <div 
              className={`h-2 rounded-full transition-all duration-300 ease-out ${
                isFilled 
                  ? 'bg-slate-800 dark:bg-slate-100 w-[115%] z-10 shadow-md scale-100' 
                  : 'bg-slate-200 dark:bg-slate-700 w-full scale-100 group-hover:bg-blue-200 dark:group-hover:bg-blue-800/50'
              }`}
            />
          </div>
        );
      }
    }
    return (
      <div key={`row-h-${rowIndex}`} className="flex items-center leading-none">
        {items}
      </div>
    );
  };

  const renderVerticalRow = (rowIndex: number) => {
    const items = [];
    for (let col = 0; col < cols; col++) {
      const isFilled = isVLineFilled(gameState, rowIndex, col);
      const isInteractive = !disabled && !isFilled && !gameState.winner;

      // V-LINE
      items.push(
        <div 
          key={`v-${rowIndex}-${col}`}
          className={`relative flex flex-col items-center justify-start flex-shrink-0 group ${!isFilled && !disabled ? 'cursor-pointer' : ''}`}
          style={{ height: CELL_SIZE, width: CORNER_SIZE }}
          onClick={() => isInteractive && onLineClick('vertical', rowIndex, col)}
        >
          {/* Hit area */}
          <div className={`absolute -left-3 -right-3 top-0 bottom-0 z-10 ${isInteractive ? 'hover:bg-blue-500/10 dark:hover:bg-blue-400/10 rounded' : ''}`} />

          {/* Visual Line */}
          <div 
            className={`w-2 rounded-full transition-all duration-300 ease-out ${
              isFilled 
                ? 'bg-slate-800 dark:bg-slate-100 h-[115%] z-10 shadow-md scale-100' 
                : 'bg-slate-200 dark:bg-slate-700 h-full scale-100 group-hover:bg-blue-200 dark:group-hover:bg-blue-800/50'
            }`}
          />
        </div>
      );

      // SQUARE
      if (col < cols - 1) {
        const owner = gameState.squares[rowIndex]?.[col];
        items.push(
          <div 
            key={`sq-${rowIndex}-${col}`}
            className="flex items-center justify-center relative flex-shrink-0"
            style={{ width: CELL_SIZE, height: CELL_SIZE }}
          >
            {owner && (
              <div className="w-full h-full p-1 animate-pop">
                 <div className={`w-full h-full rounded-lg shadow-sm flex items-center justify-center ${
                    owner === PLAYER_X 
                      ? 'bg-blue-500 text-white' 
                      : 'bg-red-500 text-white'
                 }`}>
                   <span className="text-xl font-black">
                     {owner}
                   </span>
                 </div>
              </div>
            )}
          </div>
        );
      }
    }

    return (
      <div key={`row-v-${rowIndex}`} className="flex items-start leading-none">
        {items}
      </div>
    );
  };

  return (
    <div style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }} className="my-auto transition-transform duration-300 ease-out">
      <div className={`inline-flex flex-col p-8 bg-[#f1f5f9] dark:bg-[#1e293b] shadow-[0_10px_40px_-10px_rgba(0,0,0,0.2)] dark:shadow-[0_10px_40px_-10px_rgba(0,0,0,0.5)] rounded-[2rem] select-none transition-all duration-500 border-[6px] border-white dark:border-slate-600 ${disabled && !gameState.winner ? 'opacity-90 grayscale-[0.3]' : 'opacity-100'}`}>
        {Array.from({ length: rows }).map((_, r) => (
          <React.Fragment key={r}>
            {renderHorizontalRow(r)}
            {r < rows - 1 && renderVerticalRow(r)}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
};

export default memo(Grid);

