                     const displayNum = isVisited ? visitNum : (isFixed ? fixedNum : '');

                     return (
                       <div
                         key={key}
                         data-cell="true"
                         data-row={r}
                         data-col={c}
                         onPointerDown={(e) => {
                             e.preventDefault(); 
                             handlePointerDown(r, c);
                         }}
                         onPointerEnter={(e) => {
                             handlePointerEnter(r, c);
