import React, { memo, useEffect, useState } from 'react';
import { PLAYER_X, CELL_SIZE, CORNER_SIZE } from '../constants';
import { GameState, LineType } from '../types';

interface GridProps {
  gameState: GameState;
  onLineClick: (type: LineType, row: number, col: number) => void;
  rows: number;
  cols: number;
  disabled?: boolean;
}

const isHLineFilled = (gameState: GameState, r: number, c: number) => gameState.hLines[r]?.[c];
const isVLineFilled = (gameState: GameState, r: number, c: number) => gameState.vLines[r]?.[c];

const Grid: React.FC<GridProps> = ({ gameState, onLineClick, rows, cols, disabled = false }) => {
  const [scale, setScale] = useState(1);

  useEffect(() => {
    const handleResize = () => {
      const gridPadding = 64; // Account for the p-8 padding
      const boardWidth = cols * CORNER_SIZE + (cols - 1) * CELL_SIZE + gridPadding;
      const availableWidth = window.innerWidth;
      const availableHeight = window.innerHeight - 180; // Account for scoreboard

      // Calculate width scale
      let newScale = 1;
      if (boardWidth > availableWidth) {
        newScale = (availableWidth - 32) / boardWidth;
      }

      // Check height constraint
      const boardHeight = rows * CORNER_SIZE + (rows - 1) * CELL_SIZE + gridPadding;
      if (boardHeight > availableHeight && availableHeight > 0) {
          const hScale = availableHeight / boardHeight;
          if (hScale < newScale) newScale = hScale;
      }

      setScale(newScale);
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [cols, rows]);

  const renderHorizontalRow = (rowIndex: number) => {
    const items = [];
    for (let col = 0; col < cols; col++) {
      // DOT
      items.push(
        <div 
          key={`dot-${rowIndex}-${col}`} 
          className="relative z-20 flex-shrink-0 flex items-center justify-center"
          style={{ width: CORNER_SIZE, height: CORNER_SIZE }}
        >
          <div className="w-3 h-3 sm:w-3.5 sm:h-3.5 rounded-full bg-slate-800 dark:bg-slate-300 shadow-[0_0_0_2px_rgba(255,255,255,1)] dark:shadow-[0_0_0_2px_rgba(30,41,59,1)]" />
        </div>
      );

      // H-LINE
      if (col < cols - 1) {
        const isFilled = isHLineFilled(gameState, rowIndex, col);
        const isInteractive = !disabled && !isFilled && !gameState.winner;

        items.push(
          <div 
            key={`h-${rowIndex}-${col}`}
            className={`relative flex items-center justify-center flex-shrink-0 group ${!isFilled && !disabled ? 'cursor-pointer' : ''}`}
            style={{ width: CELL_SIZE, height: CORNER_SIZE }} 
            onClick={() => isInteractive && onLineClick('horizontal', rowIndex, col)}
          >
            {/* Hit area */}
            <div className={`absolute -top-3 -bottom-3 left-0 right-0 z-10 ${isInteractive ? 'hover:bg-blue-500/10 dark:hover:bg-blue-400/10 rounded' : ''}`} />

            {/* Visual Line */}
            <div 
              className={`h-2 rounded-full transition-all duration-300 ease-out ${
                isFilled 
                  ? 'bg-slate-800 dark:bg-slate-100 w-[115%] z-10 shadow-md scale-100' 
                  : 'bg-slate-200 dark:bg-slate-700 w-full scale-100 group-hover:bg-blue-300 dark:group-hover:bg-blue-700'
              }`}
            />
          </div>
        );
      }
    }
    return (
      <div key={`row-h-${rowIndex}`} className="flex items-center leading-none">
        {items}
      </div>
    );
  };

  const renderVerticalRow = (rowIndex: number) => {
    const items = [];
    for (let col = 0; col < cols; col++) {
      const isFilled = isVLineFilled(gameState, rowIndex, col);
      const isInteractive = !disabled && !isFilled && !gameState.winner;

      // V-LINE
      items.push(
        <div 
          key={`v-${rowIndex}-${col}`}
          className={`relative flex flex-col items-center justify-start flex-shrink-0 group ${!isFilled && !disabled ? 'cursor-pointer' : ''}`}
          style={{ height: CELL_SIZE, width: CORNER_SIZE }}
          onClick={() => isInteractive && onLineClick('vertical', rowIndex, col)}
        >
          {/* Hit area */}
          <div className={`absolute -left-3 -right-3 top-0 bottom-0 z-10 ${isInteractive ? 'hover:bg-blue-500/10 dark:hover:bg-blue-400/10 rounded' : ''}`} />

          {/* Visual Line */}
          <div 
            className={`w-2 rounded-full transition-all duration-300 ease-out ${
              isFilled 
                ? 'bg-slate-800 dark:bg-slate-100 h-[115%] z-10 shadow-md scale-100' 
                : 'bg-slate-200 dark:bg-slate-700 h-full scale-100 group-hover:bg-blue-300 dark:group-hover:bg-blue-700'
            }`}
          />
        </div>
      );

      // SQUARE
      if (col < cols - 1) {
        const owner = gameState.squares[rowIndex]?.[col];
        items.push(
          <div 
            key={`sq-${rowIndex}-${col}`}
            className="flex items-center justify-center relative flex-shrink-0"
            style={{ width: CELL_SIZE, height: CELL_SIZE }}
          >
            {owner && (
              <div className="w-full h-full p-1 animate-pop">
                 <div className={`w-full h-full rounded-lg shadow-sm flex items-center justify-center ${
                    owner === PLAYER_X 
                      ? 'bg-blue-500 text-white shadow-blue-500/50' 
                      : 'bg-red-500 text-white shadow-red-500/50'
                 }`}>
                   <span className="text-xl font-black">
                     {owner}
                   </span>
                 </div>
              </div>
            )}
          </div>
        );
      }
    }

    return (
      <div key={`row-v-${rowIndex}`} className="flex items-start leading-none">
        {items}
      </div>
    );
  };

  return (
    <div style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }} className="my-auto transition-transform duration-300 ease-out">
      <div className={`inline-flex flex-col p-8 bg-white dark:bg-[#1e293b] shadow-2xl dark:shadow-[0_10px_40px_-10px_rgba(0,0,0,0.5)] rounded-[2rem] select-none transition-all duration-500 border-[6px] border-slate-100 dark:border-slate-600 ${disabled && !gameState.winner ? 'opacity-90 grayscale-[0.3]' : 'opacity-100'}`}>
        {Array.from({ length: rows }).map((_, r) => (
          <React.Fragment key={r}>
            {renderHorizontalRow(r)}
            {r < rows - 1 && renderVerticalRow(r)}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
};

export default memo(Grid);

import React from 'react';
import { Player, PLAYER_X, PLAYER_O } from '../constants';

interface ScoreBoardProps {
  scores: Record<Player, number>;
  currentPlayer: Player;
  winner: Player | 'Draw' | null;
  onReset: () => void;
  p1Name: string;
  p2Name: string;
  myPlayer?: Player; 
}

const ScoreBoard: React.FC<ScoreBoardProps> = ({ scores, currentPlayer, winner, onReset, p1Name, p2Name, myPlayer }) => {
  const isMyTurn = myPlayer ? currentPlayer === myPlayer : true;

  // Helper to determine active state styles
  const getPlayerStyles = (player: Player) => {
    const isActive = currentPlayer === player && !winner;
    const isWinner = winner === player;

    // Base styles
    let containerClass = "flex items-center gap-2 sm:gap-3 py-2 px-3 sm:px-4 rounded-2xl transition-all duration-300 relative overflow-hidden ";

    if (isWinner) {
      containerClass += "bg-yellow-100 dark:bg-yellow-900/40 ring-2 ring-yellow-400 scale-105 shadow-lg z-10";
    } else if (isActive) {
      if (player === PLAYER_X) containerClass += "bg-blue-100 dark:bg-blue-900/40 ring-2 ring-blue-500 shadow-md scale-105 z-10";
      else containerClass += "bg-red-100 dark:bg-red-900/40 ring-2 ring-red-500 shadow-md scale-105 z-10";
    } else {
      containerClass += "bg-transparent opacity-60 grayscale-[0.5] scale-95";
    }

    return containerClass;
  };

  return (
    <div className="w-full max-w-lg mx-auto mb-2 px-2 z-20 shrink-0">
      <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border border-slate-200 dark:border-slate-700 rounded-3xl shadow-xl p-1.5 flex items-stretch justify-between gap-1 sm:gap-4 transition-all duration-300">

        {/* Player X */}
        <div className={getPlayerStyles(PLAYER_X)}>
          <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-xl bg-blue-500 text-white flex items-center justify-center font-black text-lg sm:text-xl shadow-sm shrink-0">
            X
          </div>
          <div className="flex flex-col min-w-[40px] sm:min-w-[60px]">
             <span className="text-[10px] uppercase font-bold text-slate-500 dark:text-slate-400 leading-none mb-0.5 truncate max-w-[70px] sm:max-w-[100px]">
               {myPlayer === PLAYER_X ? 'YOU' : p1Name}
            </span>
            <span className="text-2xl sm:text-3xl font-black leading-none text-slate-800 dark:text-slate-100">
              {scores[PLAYER_X]}
            </span>
          </div>
        </div>

        {/* Center Info - Compact on Mobile */}
        <div className="flex flex-col items-center justify-center min-w-[60px] shrink-0">
          {winner ? (
            <div className="flex flex-col items-center animate-in">
               <span className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500">Result</span>
               <span className={`text-xs sm:text-sm font-black text-center leading-tight ${winner === PLAYER_X ? 'text-blue-500' : winner === PLAYER_O ? 'text-red-500' : 'text-slate-500'}`}>
                 {winner === 'Draw' ? 'DRAW' : 'WINNER'}
               </span>
               <button onClick={onReset} className="mt-1 text-[10px] bg-slate-800 dark:bg-slate-200 text-white dark:text-slate-900 px-2 py-1 rounded-full font-bold hover:scale-105 transition-transform shadow-lg">
                  RESTART
               </button>
            </div>
          ) : (
            <div className="flex flex-col items-center">
               <span className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-1">Turn</span>
               <div className={`w-3 h-3 sm:w-4 sm:h-4 rounded-full transition-colors duration-300 ${currentPlayer === PLAYER_X ? 'bg-blue-500 shadow-[0_0_10px_#3b82f6]' : 'bg-red-500 shadow-[0_0_10px_#ef4444]'} animate-pulse`}></div>
            </div>
          )}
        </div>

        {/* Player O */}
        <div className={getPlayerStyles(PLAYER_O) + " text-right flex-row-reverse"}>
          <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-xl bg-red-500 text-white flex items-center justify-center font-black text-lg sm:text-xl shadow-sm shrink-0">
            O
          </div>
          <div className="flex flex-col items-end min-w-[40px] sm:min-w-[60px]">
            <span className="text-[10px] uppercase font-bold text-slate-500 dark:text-slate-400 leading-none mb-0.5 truncate max-w-[70px] sm:max-w-[100px]">
              {myPlayer === PLAYER_O ? 'YOU' : p2Name}
            </span>
            <span className="text-2xl sm:text-3xl font-black leading-none text-slate-800 dark:text-slate-100">
              {scores[PLAYER_O]}
            </span>
          </div>
        </div>

      </div>

      {myPlayer && !winner && (
         <div className={`text-center mt-1 text-[10px] sm:text-xs font-bold uppercase tracking-widest transition-opacity duration-300 ${isMyTurn ? 'opacity-100 text-green-600 dark:text-green-400' : 'opacity-50 text-slate-400'}`}>
           {isMyTurn ? "Your Turn" : "Opponent's Turn"}
         </div>
      )}
    </div>
  );
};

export default ScoreBoard;

import React, { useState, useEffect } from 'react';

interface SetupScreenProps {
  onStart: (config: { p1Name: string; p2Name: string; gridSize: number }) => void;
  onBack: () => void;
}

const SetupScreen: React.FC<SetupScreenProps> = ({ onStart, onBack }) => {
  const [p1Name, setP1Name] = useState('Player 1');
  const [p2Name, setP2Name] = useState('Player 2');
  const [gridSize, setGridSize] = useState(6);
  const [installPrompt, setInstallPrompt] = useState<any>(null);
  const [isStandalone, setIsStandalone] = useState(false);

  useEffect(() => {
    // Check if running in standalone mode (PWA)
    const checkStandalone = () => {
      const isStandaloneMode = window.matchMedia('(display-mode: standalone)').matches || 
                              (window.navigator as any).standalone === true;
      setIsStandalone(isStandaloneMode);
    };

    checkStandalone();
    window.addEventListener('resize', checkStandalone);

    if ((window as any).deferredPrompt) {
      setInstallPrompt((window as any).deferredPrompt);
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setInstallPrompt(e);
      (window as any).deferredPrompt = e;
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => {
      window.removeEventListener('beforeinstallprompt', handler);
      window.removeEventListener('resize', checkStandalone);
    }
  }, []);

  const handleInstallClick = () => {
    if (installPrompt) {
      installPrompt.prompt();
      installPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          setInstallPrompt(null);
          (window as any).deferredPrompt = null;
        }
      });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onStart({ p1Name, p2Name, gridSize });
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
      <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border border-white/50 dark:border-slate-700 rounded-3xl shadow-2xl p-6 sm:p-8 w-full relative transition-all">

        <div className="flex items-center justify-between mb-8">
           <button 
             onClick={onBack} 
             className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
           >
             ←
           </button>
           <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tight">Game Setup</h2>
           <div className="w-10"></div> {/* Spacer */}
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col gap-6">
          {/* Player Names */}
          <div className="space-y-4">
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-blue-500">
                <span className="font-bold text-lg">X</span>
              </div>
              <input 
                type="text" 
                value={p1Name}
                onChange={(e) => setP1Name(e.target.value)}
                maxLength={12}
                className="w-full pl-10 pr-4 py-4 bg-slate-50 dark:bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-xl font-bold text-slate-700 dark:text-slate-200 outline-none transition-all placeholder:text-slate-400 group-hover:bg-slate-100 dark:group-hover:bg-slate-750"
                placeholder="Player 1 Name"
              />
            </div>
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-red-500">
                <span className="font-bold text-lg">O</span>
              </div>
              <input 
                type="text" 
                value={p2Name}
                onChange={(e) => setP2Name(e.target.value)}
                maxLength={12}
                className="w-full pl-10 pr-4 py-4 bg-slate-50 dark:bg-slate-800 border-2 border-transparent focus:border-red-500 rounded-xl font-bold text-slate-700 dark:text-slate-200 outline-none transition-all placeholder:text-slate-400 group-hover:bg-slate-100 dark:group-hover:bg-slate-750"
                placeholder="Player 2 Name"
              />
            </div>
          </div>

          {/* Grid Size Selection */}
          <div>
            <label className="block text-slate-500 dark:text-slate-400 text-xs font-bold mb-3 uppercase tracking-widest text-center">Grid Size</label>
            <div className="bg-slate-100 dark:bg-slate-800 p-1.5 rounded-2xl flex justify-between relative">
              {[6, 8, 10].map((size) => (
                <button
                  key={size}
                  type="button"
                  onClick={() => setGridSize(size)}
                  className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all duration-300 relative z-10 ${
                    gridSize === size 
                      ? 'text-white shadow-lg' 
                      : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'
                  }`}
                >
                  {size}x{size}
                  {gridSize === size && (
                    <div className="absolute inset-0 bg-slate-800 dark:bg-slate-600 rounded-xl -z-10 animate-in"></div>
                  )}
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col gap-3 mt-4">
            <button 
              type="submit"
              className="w-full bg-slate-900 dark:bg-blue-600 hover:bg-slate-800 dark:hover:bg-blue-500 text-white font-bold py-4 rounded-xl shadow-lg shadow-slate-900/20 active:scale-[0.98] transition-all text-lg tracking-wide"
            >
              Start Game
            </button>

            {!isStandalone && installPrompt && (
              <button
                type="button"
                onClick={handleInstallClick}
                className="w-full bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 font-bold py-3 rounded-xl transition-all text-sm flex items-center justify-center gap-2"
              >
                <span>↓</span> Install App
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

