@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: light;
}
:root.dark {
  color-scheme: dark;
}

body {
  font-family: 'Patrick Hand', cursive;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  background-color: #fdfbf7;
  transition: background-color 0.5s ease, color 0.3s ease;
}

.dark body {
  background-color: #0f172a;
}

.paper-pattern {
