  width: 6px;
  height: 6px;
}
.game-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.game-scroll::-webkit-scrollbar-thumb {
  background: rgba(0,0,0,0.1);
  border-radius: 3px;
}
.dark .game-scroll::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.1);
}

/* Animation utilities */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.animate-in {
  animation: fadeIn 0.3s ease-out forwards;
}

.animate-bounce-in {
  animation: bounceIn 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

@keyframes bounceIn {
  0% { transform: scale(0); }
  70% { transform: scale(1.2); }
  100% { transform: scale(1); }
}

@keyframes pop {
  0% { opacity: 0; transform: scale(0.5); }
  100% { opacity: 1; transform: scale(1); }
}

.animate-pop {
  animation: pop 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}

/* ATMOSPHERE ANIMATIONS */
@keyframes fall {
  0% { transform: translateY(-10vh) translateX(0); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateY(110vh) translateX(20px); opacity: 0; }
}

@keyframes rain {
  0% { transform: translateY(-10vh); }
  100% { transform: translateY(110vh); }
}

@keyframes float-ash {
  0% { transform: translateY(110vh) translateX(0) rotate(0deg); opacity: 0; }
  20% { opacity: 0.8; }
  80% { opacity: 0.8; }
  100% { transform: translateY(-10vh) translateX(50px) rotate(360deg); opacity: 0; }
}

@keyframes heat-wave {
  0% { transform: translateY(0) scaleY(1); opacity: 0.3; }
  50% { transform: translateY(-20px) scaleY(1.1); opacity: 0; }
  100% { transform: translateY(0) scaleY(1); opacity: 0.3; }
}

@keyframes sway {
  0% { margin-left: 0px; }
  50% { margin-left: 50px; }
  100% { margin-left: 0px; }
}

import React, { useMemo } from 'react';
import { AtmosphereType } from '../types';

interface AtmosphereLayerProps {
  type: AtmosphereType;
}

const AtmosphereLayer: React.FC<AtmosphereLayerProps> = ({ type }) => {
  // Generate random particles based on type
  const particles = useMemo(() => {
    const count = type === 'NONE' ? 0 : 25; // Keep count low for performance
    return Array.from({ length: count }).map((_, i) => ({
      id: i,
      left: `${Math.random() * 100}%`,
      animationDuration: `${Math.random() * 10 + 5}s`,
      animationDelay: `${Math.random() * 5}s`,
      size: Math.random() * 10 + 5,
    }));
  }, [type]);

  if (type === 'NONE') return null;

  return (
    <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden transition-all duration-1000">

      {/* 1. STRANGER THINGS */}
      {type === 'STRANGER_THINGS' && (
        <>
          <div className="absolute inset-0 bg-gradient-to-b from-slate-900 via-red-950/20 to-slate-900 opacity-80 mix-blend-overlay"></div>
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_transparent_0%,_rgba(0,0,0,0.8)_100%)]"></div>
          {particles.map((p) => (
            <div
              key={p.id}
              className="absolute bg-slate-300 rounded-full opacity-60 blur-[1px]"
              style={{
                left: p.left,
                width: p.size / 2,
                height: p.size / 2,
                animation: `float-ash ${p.animationDuration} linear infinite`,
                animationDelay: p.animationDelay,
                bottom: '-20px' // Start from bottom for ash
              }}
            />
          ))}
          {/* Subtle red dust overlay */}
          <div className="absolute inset-0 bg-red-500/5 mix-blend-color-dodge animate-pulse" style={{ animationDuration: '4s' }}></div>
        </>
      )}

      {/* 2. SUMMER */}
      {type === 'SUMMER' && (
        <>
          <div className="absolute inset-0 bg-gradient-to-t from-orange-200/40 via-yellow-100/20 to-blue-200/10 dark:from-orange-900/20 dark:via-transparent dark:to-transparent"></div>
          {/* Heat Haze Lines */}
          {particles.slice(0, 10).map((p) => (
            <div
              key={p.id}
              className="absolute bottom-0 w-20 h-40 bg-white/20 blur-xl rounded-full"
              style={{
                left: p.left,
                animation: `heat-wave 3s ease-in-out infinite`,
                animationDelay: p.animationDelay,
              }}
            />
          ))}
          <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-yellow-400/10 rounded-full blur-[100px] -translate-y-1/2 translate-x-1/2"></div>
        </>
      )}

      {/* 3. RAINY */}
      {type === 'RAINY' && (
        <>
          <div className="absolute inset-0 bg-gradient-to-b from-slate-700/30 to-slate-900/30 dark:from-slate-800/50 dark:to-black/50"></div>
          {particles.map((p) => (
            <div
              key={p.id}
              className="absolute w-[1px] bg-blue-300/60"
              style={{
                left: p.left,
                height: p.size * 2,
                top: -50,
                animation: `rain 1s linear infinite`,
                animationDelay: `${Math.random()}s`, // Fast random rain
                opacity: 0.5
              }}
            />
          ))}
        </>
      )}

      {/* 4. WINTER */}
      {type === 'WINTER' && (
        <>
          <div className="absolute inset-0 bg-gradient-to-b from-blue-50/50 to-white/50 dark:from-slate-800/50 dark:to-blue-900/20"></div>
          {particles.map((p) => (
            <div
              key={p.id}
              className="absolute bg-white rounded-full blur-[1px]"
              style={{
                left: p.left,
                width: p.size,
                height: p.size,
                top: -20,
                animation: `fall ${p.animationDuration} linear infinite`,
                animationDelay: p.animationDelay,
              }}
            >
                {/* Sway wrapper */}
               <div style={{ animation: `sway 3s ease-in-out infinite alternate` }}></div>
            </div>
          ))}
        </>
      )}

      {/* 5. SPRING */}
      {type === 'SPRING' && (
        <>
          <div className="absolute inset-0 bg-gradient-to-br from-pink-100/30 via-green-50/20 to-blue-50/20 dark:from-pink-900/10 dark:via-slate-900 dark:to-slate-900"></div>
          {particles.map((p) => (
            <div
              key={p.id}
              className={`absolute rounded-tl-none rounded-br-none rounded-tr-full rounded-bl-full ${
                  p.id % 2 === 0 ? 'bg-pink-300/60' : 'bg-green-300/40'
              }`}
              style={{
                left: p.left,
                width: p.size,
                height: p.size,
                top: -20,
                animation: `fall ${p.animationDuration} linear infinite, float-ash 5s ease-in-out infinite alternate`, // Reusing float-ash for rotation
                animationDelay: p.animationDelay,
              }}
            />
          ))}
        </>
      )}
    </div>
  );
};

