export default ZipGame;

import React, { useState, useEffect } from 'react';

interface ZipGameProps {
  onBackToLauncher: () => void;
  theme: 'light' | 'dark';
}

type Level = 'EASY' | 'MEDIUM' | 'HARD';
type Point = { r: number; c: number };

const posKey = (r: number, c: number) => `${r},${c}`;

const ZipGame: React.FC<ZipGameProps> = ({ onBackToLauncher, theme }) => {
  const [view, setView] = useState<'MENU' | 'GAME'>('MENU');
  const [level, setLevel] = useState<Level>('EASY');
  const [gridSize, setGridSize] = useState(4);

  const [fixedCells, setFixedCells] = useState<Map<string, number>>(new Map());
  const [path, setPath] = useState<Point[]>([]); 
  const [isDrawing, setIsDrawing] = useState(false);
  const [win, setWin] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  const getGridSize = (lvl: Level) => {
    switch(lvl) {
      case 'EASY': return 4;
      case 'MEDIUM': return 6;
      case 'HARD': return 8;
      default: return 4;
    }
  };

  const startGame = async (lvl: Level) => {
    const size = getGridSize(lvl);
    setGridSize(size);
    setLevel(lvl);
    setIsGenerating(true);
    setView('GAME');

    // Allow UI to render loading state before starting generation
    setTimeout(() => {
        generatePuzzle(size);
        setIsGenerating(false);
    }, 100);
  };

  const generatePuzzle = (size: number) => {
    const totalCells = size * size;
    const solutionPath: Point[] = [];
    const visited = new Set<string>();

    const isValid = (r: number, c: number) => r >= 0 && r < size && c >= 0 && c < size;

    // Count valid unvisited neighbors
    const getDegree = (r: number, c: number) => {
        let count = 0;
        const moves = [
            { r: r - 1, c: c },
            { r: r + 1, c: c },
            { r: r, c: c - 1 },
            { r: r, c: c + 1 }
        ];
        for (const m of moves) {
            if (isValid(m.r, m.c) && !visited.has(posKey(m.r, m.c))) {
                count++;
            }
        }
        return count;
    };

    // Recursive path finder with refined scoring
    const findPath = (curr: Point, prev: Point | null): boolean => {
       solutionPath.push(curr);
       visited.add(posKey(curr.r, curr.c));

       if (solutionPath.length === totalCells) return true;

       let neighbors = [
         { r: curr.r - 1, c: curr.c },
         { r: curr.r + 1, c: curr.c },
         { r: curr.r, c: curr.c - 1 },
         { r: curr.r, c: curr.c + 1 },
       ].filter(n => isValid(n.r, n.c) && !visited.has(posKey(n.r, n.c)));

       if (neighbors.length > 0) {
           // SCORING LOGIC FOR "HARDER" PATHS
           // 1. Degree (Warnsdorff): Low degree = Must visit (prevents freezing)
           // 2. Straight Line Penalty: If moving in same dir as prev, add penalty (encourages turns)
           // 3. Randomness: Add noise to make it less predictable

           const scoredNeighbors = neighbors.map(n => {
               const degree = getDegree(n.r, n.c);
               let score = degree; // Base score is degree

               // Check for straight line
               if (prev) {
                   const drPrev = curr.r - prev.r;
                   const dcPrev = curr.c - prev.c;
                   const drNext = n.r - curr.r;
                   const dcNext = n.c - curr.c;

                   if (drPrev === drNext && dcPrev === dcNext) {
                       // Penalize straight lines. 
                       // 0.9 ensures we prefer a turn (degree X) over a straight (degree X + 0.9),
                       // but we still prefer a straight (degree X) over a turn into a dead end (degree X+1).
                       score += 0.9; 
                   }
               }

               // Add Random jitter (0.0 to 0.5) to shuffle equal moves
               score += Math.random() * 0.5;

               return { ...n, score };
           });

           // Sort by score ascending (Lower is better)
           scoredNeighbors.sort((a, b) => a.score - b.score);

           neighbors = scoredNeighbors;
       }

       for (const n of neighbors) {
           if (findPath({r: n.r, c: n.c}, curr)) return true;
       }

       visited.delete(posKey(curr.r, curr.c));
       solutionPath.pop();
       return false;
    };

    // Attempt generation
    let attempts = 0;
    while(attempts < 20) {
        solutionPath.length = 0;
        visited.clear();
        // Random start position
        const r = Math.floor(Math.random() * size);
        const c = Math.floor(Math.random() * size);

        if (findPath({r, c}, null)) break;
        attempts++;
    }

    if (solutionPath.length !== totalCells) {
        setFixedCells(new Map());
        setPath([]);
        return;
    }

    // Set Hints (Fixed Cells)
    const fixed = new Map<string, number>();

    // Always show Start and End
    fixed.set(posKey(solutionPath[0].r, solutionPath[0].c), 1);
    fixed.set(posKey(solutionPath[totalCells-1].r, solutionPath[totalCells-1].c), totalCells);

    // Add intermediate hints
    // Reduced hint percentage slightly for larger grids to make it feel cleaner/harder
    const hintPercentage = size >= 8 ? 0.25 : 0.35; 
    const numHints = Math.floor(totalCells * hintPercentage); 

    for(let i = 0; i < numHints; i++) {
        // Randomly pick indices from the path (excluding start/end)
        const idx = Math.floor(Math.random() * (totalCells - 2)) + 1; 
        const p = solutionPath[idx];
        fixed.set(posKey(p.r, p.c), idx + 1);
    }

    setFixedCells(fixed);
    setPath([solutionPath[0]]);
    setWin(false);
  };

  const resetCurrentLevel = () => {
    let startKey: string | undefined;
    for (const [key, val] of fixedCells) {
      if (val === 1) {
        startKey = key;
        break;
      }
    }
    if (startKey) {
        const [rStr, cStr] = startKey.split(',');
        setPath([{ r: Number(rStr), c: Number(cStr) }]);
        setWin(false);
    }
  };

  const getPathIndex = (r: number, c: number) => {
    return path.findIndex(p => p.r === r && p.c === c);
  };

  const handlePointerDown = (r: number, c: number) => {
    if (win) return;
    const index = getPathIndex(r, c);
    if (index === path.length - 1) {
