                            <button 
                                onClick={() => generatePuzzle(gridSize)}
                                className="px-6 py-2 bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold rounded-full hover:bg-slate-300 dark:hover:bg-slate-700 transition-colors text-sm"
                            >
                                Skip Puzzle
                            </button>
                        </>
                     )}
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default ZipGame;

import React, { useState, useEffect, useRef } from 'react';

interface ZipGameProps {
  onBackToLauncher: () => void;
  theme: 'light' | 'dark';
}

type Level = 'EASY' | 'MEDIUM' | 'HARD';
type Point = { r: number; c: number };

const posKey = (r: number, c: number) => `${r},${c}`;

const ZipGame: React.FC<ZipGameProps> = ({ onBackToLauncher, theme }) => {
  const [view, setView] = useState<'MENU' | 'GAME'>('MENU');
  const [level, setLevel] = useState<Level>('EASY');
  const [gridSize, setGridSize] = useState(4);

  const [fixedCells, setFixedCells] = useState<Map<string, number>>(new Map());
  const [path, setPath] = useState<Point[]>([]); 
  const [isDrawing, setIsDrawing] = useState(false);
  const [win, setWin] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const generatingRef = useRef(false);

  const getGridSize = (lvl: Level) => {
    switch(lvl) {
      case 'EASY': return 4;
      case 'MEDIUM': return 6;
      case 'HARD': return 8;
      default: return 4;
    }
  };

  const startGame = (lvl: Level) => {
    const size = getGridSize(lvl);
    setGridSize(size);
    setLevel(lvl);
    setView('GAME');
    setWin(false);
    setPath([]);
    setFixedCells(new Map());

    // Trigger generation after render to show loading state
    setTimeout(() => {
        generatePuzzleAsync(size);
    }, 50);
  };

  const generatePuzzleAsync = async (size: number) => {
    if (generatingRef.current) return;
    generatingRef.current = true;
    setIsGenerating(true);

    const totalCells = size * size;
    const visited = new Set<string>();
    const isValid = (r: number, c: number) => r >= 0 && r < size && c >= 0 && c < size;

    // Heuristic Helpers
    const getDegree = (r: number, c: number, currentVisited: Set<string>) => {
        let count = 0;
        const moves = [[0, 1], [0, -1], [1, 0], [-1, 0]];
        for (const [dr, dc] of moves) {
            const nr = r + dr, nc = c + dc;
            if (isValid(nr, nc) && !currentVisited.has(posKey(nr, nc))) {
                count++;
            }
        }
        return count;
    };

    const getDistFromCenter = (r: number, c: number) => {
        const center = (size - 1) / 2;
        return Math.abs(r - center) + Math.abs(c - center);
    };

    // Iterative Backtracking with Time Slicing
    // We use a stack to simulate recursion but allow yielding to the UI thread
    const solve = async () => {
        let attempts = 0;
        const maxAttempts = 5; // Restart completely if stuck deeply

        while (attempts < maxAttempts) {
            // Pick a random start point, prefer corners/edges for easier Hamilton paths
            let startR = 0, startC = 0;
            if (Math.random() > 0.5) {
                startR = Math.floor(Math.random() * size);
                startC = Math.random() > 0.5 ? 0 : size - 1;
            } else {
                startR = Math.random() > 0.5 ? 0 : size - 1;
                startC = Math.floor(Math.random() * size);
            }

            const stack = [{ 
                curr: { r: startR, c: startC }, 
                visited: new Set([posKey(startR, startC)]),
                path: [{ r: startR, c: startC }]
            }];

            let iterations = 0;

            while (stack.length > 0) {
                iterations++;

                // Yield to main thread every 500 iterations to keep UI responsive
                if (iterations % 500 === 0) {
                    await new Promise(resolve => setTimeout(resolve, 0));
                    // If user left the game, stop
                    if (!generatingRef.current) return null;
                }

                // If taking too long on this attempt, break to retry with new seed
                if (iterations > 6000 * (size/4)) break;

                const { curr, visited, path } = stack[stack.length - 1];

                if (path.length === totalCells) {
                    return path;
                }

                // Find valid neighbors
                let neighbors = [
                    { r: curr.r - 1, c: curr.c },
                    { r: curr.r + 1, c: curr.c },
                    { r: curr.r, c: curr.c - 1 },
                    { r: curr.r, c: curr.c + 1 },
                ].filter(n => isValid(n.r, n.c) && !visited.has(posKey(n.r, n.c)));

                if (neighbors.length === 0) {
                    stack.pop(); // Backtrack
                    continue;
                }

                // --- HEURISTIC SCORING ---
                // 1. Degree (Ascending): Crucial for Hamiltonian paths. Avoid isolating cells.
                // 2. Distance From Center (Descending): Hug edges first. This prevents cutting the board in half.
                // 3. Turn Bias: Prefer moves that change direction from the previous move.

                const prev = path.length > 1 ? path[path.length - 2] : null;

                neighbors = neighbors.map(n => {
                    const degree = getDegree(n.r, n.c, visited);

                    // Edge hugging bias
                    const distScore = getDistFromCenter(n.r, n.c);

                    // Turn bias
                    let turnBonus = 0;
                    if (prev) {
                        const drPrev = curr.r - prev.r;
                        const dcPrev = curr.c - prev.c;
                        const drNext = n.r - curr.r;
                        const dcNext = n.c - curr.c;
                        // If direction changes, give a small bonus (reduce score effectively)
                        if (drPrev !== drNext || dcPrev !== dcNext) {
                             turnBonus = 0.5; // Prefer turns
                        }
                    }

                    // Lower score is better.
                    // Priority: Degree >>> Distance (invert) >>> Turn
                    const score = (degree * 10) - distScore - turnBonus + Math.random() * 0.5; 

                    return { ...n, score };
                }).sort((a, b) => a.score - b.score);

                // We only push the BEST neighbor to the stack to be processed effectively (Greedy-ish DFS)
                // If we need to backtrack, we will regenerate neighbors. 
                // However, to support full backtracking, we should push the current state back with remaining neighbors.
                // For performance on 8x8, we often just want to "dive" with the best move.
                // If the best move fails, we might want to try the second best.

                // Optimized Stack Logic:
                // Modify the current stack frame to remove the chosen neighbor, then push new frame.
                // Actually, simple DFS approach: just pick one, if it fails, loop continues next time?
                // No, standard stack DFS requires pushing the next state.

                // Let's take the best candidate
                const best = neighbors[0];

                // Create new state
                const newVisited = new Set(visited);
                newVisited.add(posKey(best.r, best.c));
                const newPath = [...path, best];

                stack.push({
                    curr: best,
                    visited: newVisited,
                    path: newPath
                });
            }
            attempts++;
            await new Promise(resolve => setTimeout(resolve, 10)); // Breathe between attempts
        }
        return null;
    };

    const solutionPath = await solve();

    if (!solutionPath) {
        // Fallback for extreme edge cases (should almost never happen with retries)
        setIsGenerating(false);
        generatingRef.current = false;
        alert("Could not generate a valid puzzle. Please try again.");
        setView('MENU');
        return;
    }

    // Process Solution
    const fixed = new Map<string, number>();
    fixed.set(posKey(solutionPath[0].r, solutionPath[0].c), 1);
    fixed.set(posKey(solutionPath[totalCells-1].r, solutionPath[totalCells-1].c), totalCells);

    // Hints
    const hintPercentage = size >= 8 ? 0.20 : 0.30; // Fewer hints on hard for cleaner look
    const numHints = Math.floor(totalCells * hintPercentage); 

    // Ensure hints are spread out
    const step = Math.floor(totalCells / numHints);
    for(let i = 1; i < numHints; i++) {
        const idx = Math.min((i * step) + Math.floor(Math.random() * 4) - 2, totalCells - 2);
        if (idx > 0) {
            const p = solutionPath[idx];
            fixed.set(posKey(p.r, p.c), idx + 1);
        }
    }

    if (generatingRef.current) {
        setFixedCells(fixed);
        setPath([solutionPath[0]]);
        setIsGenerating(false);
        generatingRef.current = false;
    }
  };

  // Cleanup if unmounted during generation
  useEffect(() => {
      return () => {
          generatingRef.current = false;
      };
  }, []);

  const resetCurrentLevel = () => {
    let startKey: string | undefined;
    for (const [key, val] of fixedCells) {
      if (val === 1) {
        startKey = key;
        break;
      }
    }
    if (startKey) {
        const [rStr, cStr] = startKey.split(',');
        setPath([{ r: Number(rStr), c: Number(cStr) }]);
        setWin(false);
    }
  };

  const getPathIndex = (r: number, c: number) => {
    return path.findIndex(p => p.r === r && p.c === c);
  };

  const handlePointerDown = (r: number, c: number) => {
    if (win) return;
    const index = getPathIndex(r, c);
    if (index === path.length - 1) {
        setIsDrawing(true);
    }
  };

  const handlePointerEnter = (r: number, c: number) => {
    if (!isDrawing || win) return;

    const lastPoint = path[path.length - 1];
    const index = getPathIndex(r, c);

    // Backtracking
    if (path.length > 1 && index === path.length - 2) {
      const currentVal = path.length;
      if (currentVal > 1) { 
         setPath(prev => prev.slice(0, -1));
      }
      return;
    }

    // Moving forward
    if (index === -1) {
      const isAdjacent = Math.abs(lastPoint.r - r) + Math.abs(lastPoint.c - c) === 1;

      if (isAdjacent) {
        const nextVal = path.length + 1;
        const key = posKey(r, c);

        if (fixedCells.has(key)) {
            const requiredVal = fixedCells.get(key);
            if (requiredVal !== nextVal) {
                return; 
            }
        }

        const newPath = [...path, { r, c }];
        setPath(newPath);

        if (newPath.length === gridSize * gridSize) {
          setWin(true);
          setIsDrawing(false);
        }
      }
    }
  };

  const handlePointerUp = () => {
    setIsDrawing(false);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (win) return;
    const touch = e.touches[0];
    const target = document.elementFromPoint(touch.clientX, touch.clientY);
    if (target) {
        const cell = target.closest('[data-cell]');
        if (cell) {
             const r = parseInt(cell.getAttribute('data-row') || '-1', 10);
             const c = parseInt(cell.getAttribute('data-col') || '-1', 10);
             if (r !== -1 && c !== -1) {
                 handlePointerEnter(r, c);
             }
        }
    }
  };

  useEffect(() => {
    window.addEventListener('pointerup', handlePointerUp);
    window.addEventListener('touchend', handlePointerUp);
    return () => {
        window.removeEventListener('pointerup', handlePointerUp);
        window.removeEventListener('touchend', handlePointerUp);
    }
  }, []);

  const getCellColor = (val: number) => {
    const total = gridSize * gridSize;
    const hue = 200 + ((val / total) * 120); 
    return `hsl(${hue}, 85%, 60%)`;
  };

  if (view === 'MENU') {
    return (
      <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
         <div className="absolute top-4 left-4 z-50">
           <button onClick={onBackToLauncher} className="flex items-center gap-2 px-4 py-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur rounded-full text-slate-600 dark:text-slate-300 font-bold hover:bg-white dark:hover:bg-slate-700 transition-all shadow-sm">
              <span className="text-lg">←</span> Back
           </button>
        </div>

        <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border border-white/50 dark:border-slate-700 rounded-3xl shadow-2xl p-8 w-full text-center relative overflow-hidden transition-all group">
           <div className="absolute inset-0 bg-gradient-to-br from-blue-50 via-purple-50 to-slate-50 dark:from-indigo-900/40 dark:via-purple-900/40 dark:to-slate-900/40 opacity-100"></div>
           <div className="absolute top-[-50px] right-[-50px] w-48 h-48 bg-fuchsia-500/10 dark:bg-fuchsia-500/20 rounded-full blur-3xl animate-pulse"></div>

           <div className="relative z-10">
              <div className="text-6xl mb-4">🌈</div>
              <h1 className="text-5xl font-black text-slate-800 dark:text-white mb-2 tracking-tight text-shadow-sm">
                Number Slide
              </h1>
              <p className="text-slate-500 dark:text-slate-300 mb-10 font-medium text-lg">Connect the flow.</p>

              <div className="flex flex-col gap-4">
                {[
                  { id: 'EASY', label: 'Easy', size: '4x4', color: 'from-green-500 to-emerald-600', icon: '🌱' },
                  { id: 'MEDIUM', label: 'Medium', size: '6x6', color: 'from-blue-500 to-indigo-600', icon: '💧' },
                  { id: 'HARD', label: 'Hard', size: '8x8', color: 'from-fuchsia-500 to-purple-600', icon: '🔥' }
                ].map((item) => (
                  <button 
                    key={item.id}
                    onClick={() => startGame(item.id as Level)} 
                    className={`w-full relative overflow-hidden bg-gradient-to-r ${item.color} text-white font-bold py-4 rounded-xl shadow-lg transition-transform hover:scale-[1.02] active:scale-[0.98] group`}
                  >
                    <div className="flex items-center justify-between px-6">
                      <span className="text-2xl">{item.icon}</span>
                      <span className="text-lg tracking-wider uppercase">{item.label}</span>
                      <span className="text-sm opacity-80 bg-black/20 px-2 py-1 rounded">{item.size}</span>
                    </div>
                  </button>
                ))}
              </div>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full w-full dark:text-slate-200 bg-transparent transition-colors duration-500">
      <header className="pt-6 pb-4 px-6 flex items-center justify-between z-10">
        <button 
          onClick={() => setView('MENU')}
          className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-200/50 dark:bg-slate-800/50 text-slate-600 dark:text-slate-300 hover:bg-slate-300 dark:hover:bg-slate-700 font-bold transition-all backdrop-blur"
        >
          ←
        </button>
        <div className="flex flex-col items-center">
            <h1 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight">
              Number Slide
            </h1>
            <span className="text-xs font-bold px-2 py-0.5 rounded bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400">
               {level} • {gridSize}x{gridSize}
            </span>
        </div>
        <div className="w-10"></div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center p-4 relative overflow-hidden">

        <div className="absolute inset-0 pointer-events-none opacity-20 dark:opacity-10">
            <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-blue-500/30 rounded-full blur-[100px]"></div>
            <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-fuchsia-500/30 rounded-full blur-[100px]"></div>
        </div>

        {isGenerating ? (
            <div className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm animate-in">
               <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl flex flex-col items-center border border-slate-200 dark:border-slate-700">
                   <div className="relative w-16 h-16 mb-4">
                       <div className="absolute inset-0 border-4 border-slate-200 dark:border-slate-600 rounded-full"></div>
                       <div className="absolute inset-0 border-4 border-fuchsia-500 border-t-transparent rounded-full animate-spin"></div>
                   </div>
                   <div className="text-xl font-black text-slate-700 dark:text-white mb-1">Constructing...</div>
                   <div className="text-sm font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">
                       {gridSize}x{gridSize} Grid
                   </div>
               </div>
            </div>
        ) : (
            <div className="relative z-10 flex flex-col items-center animate-in">

                <div 
                  className="bg-slate-900/5 dark:bg-black/40 p-3 rounded-2xl backdrop-blur-sm border-2 border-slate-200/50 dark:border-slate-700/50 touch-none select-none shadow-2xl"
                  style={{
                     display: 'grid',
                     gridTemplateColumns: `repeat(${gridSize}, 1fr)`,
                     gap: gridSize >= 8 ? '4px' : '8px',
                  }}
                  onTouchMove={handleTouchMove}
                >
                   {Array.from({ length: gridSize * gridSize }).map((_, i) => {
                     const r = Math.floor(i / gridSize);
                     const c = i % gridSize;
                     const key = posKey(r, c);

                     const pathIndex = getPathIndex(r, c);
                     const isVisited = pathIndex !== -1;
                     const visitNum = pathIndex + 1;
                     const fixedNum = fixedCells.get(key);
                     const isFixed = fixedNum !== undefined;
                     const isHead = isVisited && visitNum === path.length;

                     const displayNum = isVisited ? visitNum : (isFixed ? fixedNum : '');

                     // Dynamic cell size to fit 8x8 on mobile screens
                     const cellSizeClass = gridSize >= 8 
                        ? 'w-8 h-8 sm:w-10 sm:h-10 text-xs sm:text-lg' 
                        : (gridSize >= 6 ? 'w-10 h-10 sm:w-14 sm:h-14 text-base sm:text-xl' : 'w-12 h-12 sm:w-16 sm:h-16 text-xl sm:text-2xl');

                     return (
                       <div
                         key={key}
                         data-cell="true"
                         data-row={r}
                         data-col={c}
                         onPointerDown={(e) => {
                             e.preventDefault(); 
                             handlePointerDown(r, c);
                         }}
                         onPointerEnter={(e) => {
                             handlePointerEnter(r, c);
                         }}
                         className={`
                            relative ${cellSizeClass} rounded-xl flex items-center justify-center font-black transition-all duration-200
                            ${isVisited 
                                ? 'scale-100 text-white shadow-lg z-10' 
                                : 'scale-95 bg-white dark:bg-slate-800 text-slate-300 dark:text-slate-600 shadow-sm'
                            }
                            ${isFixed && !isVisited ? 'border-2 border-dashed border-slate-300 dark:border-slate-600 text-slate-400 dark:text-slate-500' : ''}
                            ${isHead ? 'scale-110 ring-4 ring-white/30 z-20' : ''}
                         `}
                         style={{
                            background: isVisited ? getCellColor(visitNum) : undefined,
                            boxShadow: isVisited ? `0 4px 12px ${getCellColor(visitNum).replace(')', ', 0.4)')}` : undefined,
                         }}
                       >
                         {displayNum}
                         {isHead && !win && (
                             <div className="absolute inset-0 bg-white/20 animate-pulse rounded-xl"></div>
                         )}
                       </div>
                     );
                   })}
                </div>

                {/* Controls */}
                <div className="mt-8 flex gap-4">
                     {win ? (
                        <div className="animate-bounce-in flex flex-col items-center gap-4">
                            <div className="px-6 py-2 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full font-bold text-lg border border-green-200 dark:border-green-800">
                                Level Complete! 🎉
                            </div>
                            <button 
                                onClick={() => startGame(level)}
                                className="px-8 py-3 bg-slate-800 dark:bg-white text-white dark:text-slate-900 font-bold rounded-full shadow-lg hover:scale-105 active:scale-95 transition-all"
                            >
                                Next Puzzle →
                            </button>
                        </div>
                     ) : (
                        <>
                            <button 
                                onClick={resetCurrentLevel}
                                className="w-12 h-12 flex items-center justify-center rounded-full bg-slate-200 dark:bg-slate-800 text-slate-500 hover:bg-slate-300 dark:hover:bg-slate-700 transition-colors"
                                title="Restart Level"
                            >
                                ↺
                            </button>
                            <button 
                                onClick={() => startGame(level)}
                                className="px-6 py-2 bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold rounded-full hover:bg-slate-300 dark:hover:bg-slate-700 transition-colors text-sm"
                            >
                                Skip Puzzle
                            </button>
                        </>
                     )}
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default ZipGame;

import React, { useState, useCallback, useRef } from 'react';
import { DataConnection, Peer } from 'peerjs';
import { 
  PLAYER_X, 
  PLAYER_O, 
  Player 
} from '../constants';
import { GameState, LineType, GameConfig, NetworkMessage } from '../types';
import Grid from './Grid';
import ScoreBoard from './ScoreBoard';
import SetupScreen from './SetupScreen';
import MenuScreen from './MenuScreen';
import OnlineSetup from './OnlineSetup';

type ViewState = 'MENU' | 'SETUP_OFFLINE' | 'SETUP_ONLINE' | 'GAME';

const createInitialState = (rows: number, cols: number): GameState => {
  const hLines = Array(rows).fill(null).map(() => Array(cols - 1).fill(false));
  const vLines = Array(rows - 1).fill(null).map(() => Array(cols).fill(false));
  const squares = Array(rows - 1).fill(null).map(() => Array(cols - 1).fill(null));

  return {
    hLines,
    vLines,
    squares,
    currentPlayer: PLAYER_X,
    scores: { [PLAYER_X]: 0, [PLAYER_O]: 0 },
    winner: null,
    moveHistory: []
  };
};

interface DotsGameProps {
  onBackToLauncher: () => void;
}

const DotsGame: React.FC<DotsGameProps> = ({ onBackToLauncher }) => {
  const [view, setView] = useState<ViewState>('MENU');
  const [gameConfig, setGameConfig] = useState<GameConfig | null>(null);
  const [gameState, setGameState] = useState<GameState | null>(null);

  const connectionRef = useRef<DataConnection | null>(null);
  const peerRef = useRef<Peer | null>(null);

  const processMove = (prev: GameState, type: LineType, r: number, c: number, rows: number, cols: number): GameState => {
      if (type === 'horizontal') {
        if (prev.hLines[r][c]) return prev; 
      } else {
        if (prev.vLines[r][c]) return prev;
      }

      const newHLines = prev.hLines.map(row => [...row]);
      const newVLines = prev.vLines.map(row => [...row]);
      const newSquares = prev.squares.map(row => [...row]);
      let newScores = { ...prev.scores };
      let squareCompleted = false;

      if (type === 'horizontal') newHLines[r][c] = true;
      else newVLines[r][c] = true;

      const ROWS = rows;
      const COLS = cols;

      if (type === 'horizontal') {
        if (r > 0 && newHLines[r-1][c] && newHLines[r][c] && newVLines[r-1][c] && newVLines[r-1][c+1]) {
            newSquares[r-1][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
        if (r < ROWS - 1 && newHLines[r][c] && newHLines[r+1][c] && newVLines[r][c] && newVLines[r][c+1]) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
      } else {
        if (c > 0 && newHLines[r][c-1] && newHLines[r+1][c-1] && newVLines[r][c-1] && newVLines[r][c]) {
            newSquares[r][c-1] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
        if (c < COLS - 1 && newHLines[r][c] && newHLines[r+1][c] && newVLines[r][c] && newVLines[r][c+1]) {
            newSquares[r][c] = prev.currentPlayer;
            newScores[prev.currentPlayer]++;
            squareCompleted = true;
        }
      }

      const totalSquares = (ROWS - 1) * (COLS - 1);
      const filledSquares = newScores[PLAYER_X] + newScores[PLAYER_O];
      let winner = null;
      if (filledSquares === totalSquares) {
        if (newScores[PLAYER_X] > newScores[PLAYER_O]) winner = PLAYER_X;
        else if (newScores[PLAYER_O] > newScores[PLAYER_X]) winner = PLAYER_O;
        else winner = 'Draw';
      }

      const nextPlayer = squareCompleted ? prev.currentPlayer : (prev.currentPlayer === PLAYER_X ? PLAYER_O : PLAYER_X);

      return {
        ...prev,
        hLines: newHLines,
        vLines: newVLines,
        squares: newSquares,
        scores: newScores,
        currentPlayer: nextPlayer,
        winner: winner as any
      };
  };

  const handleStartOffline = (config: { p1Name: string; p2Name: string; gridSize: number }) => {
    const fullConfig: GameConfig = { ...config, mode: 'OFFLINE' };
    setGameConfig(fullConfig);
    setGameState(createInitialState(config.gridSize, config.gridSize));
    setView('GAME');
  };

  const handleStartOnline = (config: GameConfig, conn: DataConnection, peer: Peer) => {
    connectionRef.current = conn;
    peerRef.current = peer;
    setGameConfig(config);
    setGameState(createInitialState(config.gridSize, config.gridSize));
    setView('GAME');

    conn.on('data', (data: any) => {
      const msg = data as NetworkMessage;
      if (msg.type === 'MOVE') {
        setGameState(prev => {
          if (!prev) return null;
          return processMove(prev, msg.lineType, msg.r, msg.c, config.gridSize, config.gridSize);
        });
      } else if (msg.type === 'RESTART') {
        setGameState(createInitialState(config.gridSize, config.gridSize));
      } else if (msg.type === 'QUIT') {
        alert('Opponent has left the game.');
        quitGame();
      }
    });

    conn.on('close', () => {
      alert('Connection lost.');
      quitGame();
    });
  };

  const quitGame = () => {
    if (connectionRef.current) {
      try { connectionRef.current.send({ type: 'QUIT' }); } catch(e) {}
      connectionRef.current.close();
      connectionRef.current = null;
    }

    if (peerRef.current) {
      peerRef.current.destroy();
      peerRef.current = null;
    }

    setGameConfig(null);
    setGameState(null);
    setView('MENU');
  };

  const resetGame = () => {
    if (!gameConfig) return;

    if (gameConfig.mode === 'ONLINE') {
        if (window.confirm("Do you want to leave the game?")) {
            quitGame();
        }
       return;
    }

    setGameState(createInitialState(gameConfig.gridSize, gameConfig.gridSize));
  };

  const handleLineClick = useCallback((type: LineType, r: number, c: number) => {
    if (!gameConfig || !gameState) return;

    if (gameConfig.mode === 'ONLINE' && gameConfig.myPlayer !== gameState.currentPlayer) {
      return; 
    }

    setGameState(prev => {
      if (!prev) return null;
      const newState = processMove(prev, type, r, c, gameConfig.gridSize, gameConfig.gridSize);

      if (gameConfig.mode === 'ONLINE' && connectionRef.current) {
         if (newState !== prev) {
             const msg: NetworkMessage = { type: 'MOVE', lineType: type, r, c };
             connectionRef.current.send(msg);
         }
      }

      return newState;
    });
  }, [gameConfig, gameState]);

  const BackButton = ({ onClick }: { onClick: () => void }) => (
    <div className="absolute top-4 left-4 z-50">
       <button onClick={onClick} className="flex items-center gap-2 px-4 py-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur rounded-full text-slate-600 dark:text-slate-300 font-bold hover:bg-white dark:hover:bg-slate-700 transition-all shadow-sm">
          <span className="text-lg">←</span> Back
       </button>
    </div>
  );

  if (view === 'MENU') {
    return (
      <>
        <BackButton onClick={onBackToLauncher} />
        <MenuScreen onSelectMode={(mode) => setView(mode === 'ONLINE' ? 'SETUP_ONLINE' : 'SETUP_OFFLINE')} />
      </>
    );
  }

  if (view === 'SETUP_OFFLINE') {
    return (
      <>
        <BackButton onClick={() => setView('MENU')} />
        <SetupScreen onStart={handleStartOffline} />
      </>
    );
  }

  if (view === 'SETUP_ONLINE') {
    return (
      <>
        <BackButton onClick={() => setView('MENU')} />
        <OnlineSetup onStartGame={handleStartOnline} />
      </>
    );
  }

  if (!gameConfig || !gameState) return null;

  return (
    <div className="flex flex-col h-full w-full relative">
      <div className="absolute top-4 left-4 z-30 flex gap-2">
        <button 
            onClick={quitGame}
            className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-200/80 dark:bg-slate-700/80 text-slate-600 dark:text-slate-300 hover:bg-slate-300 dark:hover:bg-slate-600 font-bold transition-all backdrop-blur shadow-sm"
          >
            ✕
        </button>
      </div>

      {gameConfig.mode === 'ONLINE' && (
             <div className="absolute right-4 top-4 z-30 px-3 py-1 bg-blue-100 dark:bg-blue-900/50 rounded-full text-xs font-bold text-blue-600 dark:text-blue-300 border border-blue-200 dark:border-blue-800">
                 Room: {gameConfig.roomId}
             </div>
      )}

      {/* Game Content Container - Allows scrolling of the grid while keeping header available */}
      <div className="flex flex-col h-full overflow-hidden pt-16 sm:pt-6">
        <ScoreBoard 
          scores={gameState.scores} 
          currentPlayer={gameState.currentPlayer} 
          winner={gameState.winner}
          onReset={resetGame}
          p1Name={gameConfig.p1Name}
          p2Name={gameConfig.p2Name}
          myPlayer={gameConfig.myPlayer}
        />

        <div className="flex-1 w-full overflow-y-auto overflow-x-hidden flex items-start justify-center pb-8 px-4 game-scroll">
           <Grid 
             gameState={gameState} 
             onLineClick={handleLineClick} 
             rows={gameConfig.gridSize} 
             cols={gameConfig.gridSize} 
             disabled={gameConfig.mode === 'ONLINE' && gameState.currentPlayer !== gameConfig.myPlayer}
            />
        </div>
      </div>
    </div>
  );
}

export default DotsGame;

import React, { useState, useEffect } from 'react';

interface SetupScreenProps {
  onStart: (config: { p1Name: string; p2Name: string; gridSize: number }) => void;
}

const SetupScreen: React.FC<SetupScreenProps> = ({ onStart }) => {
  const [p1Name, setP1Name] = useState('Player 1');
  const [p2Name, setP2Name] = useState('Player 2');
  const [gridSize, setGridSize] = useState(6);
  const [installPrompt, setInstallPrompt] = useState<any>(null);
  const [isStandalone, setIsStandalone] = useState(false);

  useEffect(() => {
    // Check if running in standalone mode (PWA)
    const checkStandalone = () => {
      const isStandaloneMode = window.matchMedia('(display-mode: standalone)').matches || 
                              (window.navigator as any).standalone === true;
      setIsStandalone(isStandaloneMode);
    };

    checkStandalone();
    window.addEventListener('resize', checkStandalone);

    if ((window as any).deferredPrompt) {
      setInstallPrompt((window as any).deferredPrompt);
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setInstallPrompt(e);
      (window as any).deferredPrompt = e;
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => {
      window.removeEventListener('beforeinstallprompt', handler);
      window.removeEventListener('resize', checkStandalone);
    }
  }, []);

  const handleInstallClick = () => {
    if (installPrompt) {
      installPrompt.prompt();
      installPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          setInstallPrompt(null);
          (window as any).deferredPrompt = null;
        }
      });
    }
