@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: light;
}
:root.dark {
  color-scheme: dark;
}

body {
  font-family: 'Patrick Hand', cursive;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  background-color: #fdfbf7;
  transition: background-color 0.5s ease, color 0.3s ease;
}

.dark body {
  background-color: #0f172a;
}

/* Performance Optimization: Pause all animations when app is backgrounded/hidden */
html.paused *,
html.paused *::before,
html.paused *::after {
  animation-play-state: paused !important;
}

.paper-pattern {
  background-color: #fdfbf7;
  background-image:
    linear-gradient(#e1ebf6 1px, transparent 1px),
    linear-gradient(90deg, #e1ebf6 1px, transparent 1px);
  background-size: 20px 20px;
  transition: background-color 0.5s ease, background-image 0.5s ease;
}

.dark .paper-pattern {
  background-color: #0f172a; /* slate-900 */
  background-image:
    linear-gradient(#1e293b 1px, transparent 1px),
    linear-gradient(90deg, #1e293b 1px, transparent 1px); /* slate-800 lines */
}

/* Custom scrollbar for game container */
.game-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.game-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.game-scroll::-webkit-scrollbar-thumb {
  background: rgba(0,0,0,0.1);
  border-radius: 3px;
}
.dark .game-scroll::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.1);
}

/* Animation utilities */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.animate-in {
  animation: fadeIn 0.3s ease-out forwards;
}

.animate-bounce-in {
  animation: bounceIn 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

@keyframes bounceIn {
  0% { transform: scale(0); }
  70% { transform: scale(1.2); }
  100% { transform: scale(1); }
}

@keyframes pop {
  0% { opacity: 0; transform: scale(0.5); }
  100% { opacity: 1; transform: scale(1); }
}

.animate-pop {
  animation: pop 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}

/* ATMOSPHERE ANIMATIONS */
@keyframes fall {
  0% { transform: translateY(-10vh) translateX(0); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateY(110vh) translateX(20px); opacity: 0; }
}

@keyframes rain {
  0% { transform: translateY(-10vh); }
  100% { transform: translateY(110vh); }
}

@keyframes float-ash {
  0% { transform: translateY(110vh) translateX(0) rotate(0deg); opacity: 0; }
  20% { opacity: 0.8; }
  80% { opacity: 0.8; }
  100% { transform: translateY(-10vh) translateX(50px) rotate(360deg); opacity: 0; }
}

@keyframes suspended-ash {
  0% { transform: translate(0, 0); opacity: 0.3; }
  25% { transform: translate(15px, -15px); opacity: 0.6; }
  50% { transform: translate(0, -30px); opacity: 0.3; }
  75% { transform: translate(-15px, -15px); opacity: 0.6; }
  100% { transform: translate(0, 0); opacity: 0.3; }
}

@keyframes heat-wave {
  0% { transform: translateY(0) scaleY(1); opacity: 0.3; }
  50% { transform: translateY(-20px) scaleY(1.1); opacity: 0; }
  100% { transform: translateY(0) scaleY(1); opacity: 0.3; }
}

@keyframes sway {
  0% { margin-left: 0px; }
  50% { margin-left: 50px; }
  100% { margin-left: 0px; }
}

/* Breaking / Earthquake Animations */
@keyframes shake-hard {
  0% { transform: translate(0px, 0px) rotate(0deg); }
  10% { transform: translate(-10px, -10px) rotate(-2deg); }
  20% { transform: translate(10px, 10px) rotate(2deg); }
  30% { transform: translate(-10px, 10px) rotate(0deg); }
  40% { transform: translate(10px, -10px) rotate(2deg); }
  50% { transform: translate(-10px, -10px) rotate(-2deg); }
  60% { transform: translate(10px, 10px) rotate(0deg); }
  70% { transform: translate(-10px, 10px) rotate(2deg); }
  80% { transform: translate(10px, -10px) rotate(-2deg); }
  90% { transform: translate(-5px, 0px) rotate(0deg); }
  100% { transform: translate(0px, 0px) rotate(0deg); }
}

.animate-shake-hard {
  animation: shake-hard 0.4s cubic-bezier(.36,.07,.19,.97) both infinite;
}

@keyframes crack-expand {
  0% { stroke-width: 0; opacity: 0; }
  10% { stroke-width: 2px; opacity: 1; }
  100% { stroke-width: 8px; opacity: 1; }
}

.animate-crack {
  animation: crack-expand 0.9s ease-out forwards;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Upside Down Text Mode - Stranger Things */
.upside-down-mode span {
  /* Spans are inline by default and can't transform. inline-block fixes this. */
  display: inline-block;
}

.upside-down-mode h1,
.upside-down-mode h2,
.upside-down-mode h3,
.upside-down-mode h4,
.upside-down-mode h5,
.upside-down-mode h6,
.upside-down-mode p,
.upside-down-mode span,
.upside-down-mode label,
.upside-down-mode input,
.upside-down-mode button,
.upside-down-mode [data-cell] {
  transform: rotate(180deg);
}

/* Prevent double-rotation if elements are nested (e.g. span inside button) */
.upside-down-mode button span,
.upside-down-mode [data-cell] span,
.upside-down-mode h1 span,
.upside-down-mode h2 span,
.upside-down-mode p span {
  transform: none;
}

