const CACHE_NAME = 'mindgrid-v5';
const URLS_TO_CACHE = [
  '/',
  '/index.html',
  '/manifest.json',
  '/icons/icon-192.png',
  '/icons/icon-512.png'
];

// Install: Pre-cache core assets and dynamically find JS/CSS bundles
self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then(async (cache) => {
      // 1. Cache known static files
      await cache.addAll(URLS_TO_CACHE);

      // 2. Dynamically identify and cache hashed assets from index.html
      // This ensures the main JS/CSS bundles are cached without a build step injecting filenames.
      try {
        const response = await fetch('/index.html');
        if (response.ok) {
           const html = await response.text();
           // Find standard Vite build assets (/assets/...)
           const assets = html.match(/\/assets\/[^"']+/g) || [];
           const uniqueAssets = [...new Set(assets)];
           if (uniqueAssets.length > 0) {
             await cache.addAll(uniqueAssets);
           }
        }
      } catch (err) {
        console.log('Dynamic asset caching failed', err);
      }
    })
  );
});

// Activate: Clean up old caches and take control
self.addEventListener('activate', (event) => {
  event.waitUntil(
    Promise.all([
      self.clients.claim(),
      caches.keys().then((cacheNames) => {
        return Promise.all(
          cacheNames.map((cacheName) => {
            if (cacheName !== CACHE_NAME) {
              return caches.delete(cacheName);
            }
          })
        );
      })
    ])
  );
});

// Fetch: Cache First strategy for assets, Network First for data/API
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  const url = new URL(event.request.url);

  // Exclude API calls or PeerJS signaling (dynamic data)
  // Assuming API calls might be to external domains or specific paths
  if (url.pathname.startsWith('/api') || url.hostname.includes('peerjs')) {
     return;
  }

  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      // 1. Return from cache if available (Cache-First)
      if (cachedResponse) {
        return cachedResponse;
      }

      // 2. Fetch from network
      return fetch(event.request).then((networkResponse) => {
        // Only cache valid responses (basic/cors) and valid status
        if (!networkResponse || networkResponse.status !== 200 || networkResponse.type === 'error') {
          return networkResponse;
        }

        // Clone and cache
        const responseToCache = networkResponse.clone();
        caches.open(CACHE_NAME).then((cache) => {
          cache.put(event.request, responseToCache);
        });

        return networkResponse;
      }).catch(() => {
        // 3. Offline fallback for navigation
        if (event.request.mode === 'navigate') {
          return caches.match('/index.html');
        }
      });
    })
  );
});

import React, { useState, useEffect } from 'react';
import DotsGame from './components/DotsGame';
import ZipGame from './components/ZipGame';
import GameLauncher from './components/GameLauncher';
import AtmosphereLayer from './components/AtmosphereLayer';
import BreakingTransition from './components/BreakingTransition';
import PrivacyPolicy from './components/PrivacyPolicy';
import { AtmosphereType } from './types';

type AppState = 'LAUNCHER' | 'DOTS' | 'ZIP' | 'PRIVACY';

function App() {
  const [activeGame, setActiveGame] = useState<AppState>('LAUNCHER');

  // Theme State managed globally
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    if (typeof window !== 'undefined') {
      return (localStorage.getItem('theme') as 'light' | 'dark') || 'light';
    }
    return 'light';
  });

  const [atmosphere, setAtmosphere] = useState<AtmosphereType>('NONE');
  const [isBreaking, setIsBreaking] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Apply theme to document and update status bar color for PWA/TWA
  useEffect(() => {
    const root = document.documentElement;
    const metaThemeColor = document.querySelector('meta[name="theme-color"]');

    if (theme === 'dark') {
      root.classList.add('dark');
      if (metaThemeColor) metaThemeColor.setAttribute('content', '#0f172a');
    } else {
      root.classList.remove('dark');
      if (metaThemeColor) metaThemeColor.setAttribute('content', '#fdfbf7');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  // Monitor network status, visibility for performance, and URL routing
  useEffect(() => {
    const handleStatusChange = () => setIsOnline(navigator.onLine);
    const handleVisibilityChange = () => {
      if (document.hidden) {
        document.documentElement.classList.add('paused');
      } else {
        document.documentElement.classList.remove('paused');
      }
    };

    // Simple routing logic
    const handlePopState = () => {
       if (window.location.pathname === '/privacy') {
         setActiveGame('PRIVACY');
       } else {
         setActiveGame('LAUNCHER');
       }
    };

    // Check initial URL
    if (window.location.pathname === '/privacy') {
       setActiveGame('PRIVACY');
    }

    window.addEventListener('online', handleStatusChange);
    window.addEventListener('offline', handleStatusChange);
    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('popstate', handlePopState);

    return () => {
      window.removeEventListener('online', handleStatusChange);
      window.removeEventListener('offline', handleStatusChange);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('popstate', handlePopState);
    };
  }, []);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const handleSetAtmosphere = (type: AtmosphereType) => {
    if (type === 'STRANGER_THINGS') {
        setIsBreaking(true);
        setAtmosphere(type);
        setTheme('dark');
        setTimeout(() => {
            setIsBreaking(false);
        }, 1000);
    } else {
        setAtmosphere(type);
    }
  };

  const navigateHome = () => {
    try {
      // Use replaceState if going back to root to avoid building up history stack of same page
      // or pushState depending on desired UX. Here pushing to support browser back button.
      // We also check if we are already at root to avoid redundant entries.
      if (window.location.pathname !== '/') {
         window.history.pushState({}, '', '/');
      }
    } catch (e) {
      console.warn('History API not supported or restricted:', e);
    }
    setActiveGame('LAUNCHER');
  };

  return (
    <>
      <AtmosphereLayer type={atmosphere} />
      {isBreaking && <BreakingTransition />}

      {/* Main Content Wrapper */}
      <div className={`relative h-full w-full flex flex-col transition-transform ${isBreaking ? 'animate-shake-hard' : ''} ${atmosphere === 'STRANGER_THINGS' ? 'upside-down-mode' : ''}`}>

        {activeGame === 'DOTS' && (
          <DotsGame 
            onBackToLauncher={navigateHome} 
          />
        )}

        {activeGame === 'ZIP' && (
          <ZipGame 
            onBackToLauncher={navigateHome} 
            theme={theme}
          />
        )}

        {activeGame === 'PRIVACY' && (
          <PrivacyPolicy 
            onBack={navigateHome}
          />
        )}

        {activeGame === 'LAUNCHER' && (
          <GameLauncher 
            onSelectGame={(game) => {
               if (game === 'PRIVACY') {
                  try {
                    window.history.pushState({}, '', '/privacy');
                  } catch (e) {
                     console.warn('History API error:', e);
                  }
               }
               setActiveGame(game);
            }} 
            theme={theme} 
            onToggleTheme={toggleTheme}
            currentAtmosphere={atmosphere}
            onSetAtmosphere={handleSetAtmosphere}
          />
        )}
      </div>

      {/* Minimal Offline Banner */}
      {!isOnline && (
        <div className="fixed bottom-0 left-0 right-0 z-[100] bg-slate-900/95 dark:bg-slate-800/95 text-white backdrop-blur-md px-4 py-3 flex items-center justify-center gap-3 shadow-lg border-t border-white/10 animate-in">
           <span className="text-lg">📡</span>
           <span className="text-xs sm:text-sm font-bold tracking-wide">You are currently offline. Online play is unavailable.</span>
        </div>
      )}
    </>
  );
}

export default App;

import React, { useState, useEffect } from 'react';

interface ZipGameProps {
  onBackToLauncher: () => void;
  theme: 'light' | 'dark';
}

type Level = 'EASY' | 'MEDIUM' | 'HARD';
type Point = { r: number; c: number };

const posKey = (r: number, c: number) => `${r},${c}`;

const ZipGame: React.FC<ZipGameProps> = ({ onBackToLauncher, theme }) => {
  const [view, setView] = useState<'MENU' | 'GAME'>('MENU');
  const [level, setLevel] = useState<Level>('EASY');
  const [gridSize, setGridSize] = useState(4);

  const [fixedCells, setFixedCells] = useState<Map<string, number>>(new Map());
  const [path, setPath] = useState<Point[]>([]); 
  const [isDrawing, setIsDrawing] = useState(false);
  const [win, setWin] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  const getGridSize = (lvl: Level) => {
    switch(lvl) {
      case 'EASY': return 4;
      case 'MEDIUM': return 5;
      case 'HARD': return 6;
      default: return 4;
    }
  };

  const startGame = async (lvl: Level) => {
    const size = getGridSize(lvl);
    setGridSize(size);
    setLevel(lvl);
    setIsGenerating(true);
    setView('GAME');

    setTimeout(() => {
        generatePuzzle(size);
        setIsGenerating(false);
    }, 100);
  };

  const generatePuzzle = (size: number) => {
    const totalCells = size * size;
    const solutionPath: Point[] = [];
    const visited = new Set<string>();

    const isValid = (r: number, c: number) => r >= 0 && r < size && c >= 0 && c < size;

    const findPath = (curr: Point): boolean => {
       solutionPath.push(curr);
       visited.add(posKey(curr.r, curr.c));

       if (solutionPath.length === totalCells) return true;

       const neighbors = [
         { r: curr.r - 1, c: curr.c },
         { r: curr.r + 1, c: curr.c },
         { r: curr.r, c: curr.c - 1 },
         { r: curr.r, c: curr.c + 1 },
       ].filter(n => isValid(n.r, n.c) && !visited.has(posKey(n.r, n.c)));

       for (let i = neighbors.length - 1; i > 0; i--) {
           const j = Math.floor(Math.random() * (i + 1));
           [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
       }

       for (const n of neighbors) {
           if (findPath(n)) return true;
       }

       visited.delete(posKey(curr.r, curr.c));
       solutionPath.pop();
       return false;
    };

    let attempts = 0;
    while(attempts < 50) {
        solutionPath.length = 0;
        visited.clear();
        const r = Math.floor(Math.random() * size);
        const c = Math.floor(Math.random() * size);
        if (findPath({r, c})) break;
        attempts++;
    }

    if (solutionPath.length !== totalCells) {
        setFixedCells(new Map());
        setPath([]);
        return;
    }

    const fixed = new Map<string, number>();
    fixed.set(posKey(solutionPath[0].r, solutionPath[0].c), 1);
    fixed.set(posKey(solutionPath[totalCells-1].r, solutionPath[totalCells-1].c), totalCells);

    const numHints = Math.floor(totalCells * 0.35); 
    for(let i = 0; i < numHints; i++) {
        const idx = Math.floor(Math.random() * (totalCells - 2)) + 1; 
        const p = solutionPath[idx];
        fixed.set(posKey(p.r, p.c), idx + 1);
    }

    setFixedCells(fixed);
    setPath([solutionPath[0]]);
    setWin(false);
  };

  const resetCurrentLevel = () => {
    let startKey: string | undefined;
    for (const [key, val] of fixedCells) {
      if (val === 1) {
        startKey = key;
        break;
      }
    }
    if (startKey) {
        const [rStr, cStr] = startKey.split(',');
        setPath([{ r: Number(rStr), c: Number(cStr) }]);
        setWin(false);
    }
  };

  const getPathIndex = (r: number, c: number) => {
    return path.findIndex(p => p.r === r && p.c === c);
  };

  const handlePointerDown = (r: number, c: number) => {
    if (win) return;
    const index = getPathIndex(r, c);
    if (index === path.length - 1) {
        setIsDrawing(true);
    }
  };

  const handlePointerEnter = (r: number, c: number) => {
    if (!isDrawing || win) return;

    const lastPoint = path[path.length - 1];
    const index = getPathIndex(r, c);

    if (path.length > 1 && index === path.length - 2) {
      const currentVal = path.length;
      if (currentVal > 1) { 
         setPath(prev => prev.slice(0, -1));
      }
      return;
    }

    if (index === -1) {
      const isAdjacent = Math.abs(lastPoint.r - r) + Math.abs(lastPoint.c - c) === 1;

      if (isAdjacent) {
        const nextVal = path.length + 1;
        const key = posKey(r, c);

        if (fixedCells.has(key)) {
            const requiredVal = fixedCells.get(key);
            if (requiredVal !== nextVal) {
                return; 
            }
        }

        const newPath = [...path, { r, c }];
        setPath(newPath);

        if (newPath.length === gridSize * gridSize) {
          setWin(true);
          setIsDrawing(false);
        }
      }
    }
  };

  const handlePointerUp = () => {
    setIsDrawing(false);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (win) return;
    const touch = e.touches[0];
    const target = document.elementFromPoint(touch.clientX, touch.clientY);
    if (target) {
        const cell = target.closest('[data-cell]');
        if (cell) {
             const r = parseInt(cell.getAttribute('data-row') || '-1', 10);
             const c = parseInt(cell.getAttribute('data-col') || '-1', 10);
             if (r !== -1 && c !== -1) {
                 handlePointerEnter(r, c);
             }
        }
    }
  };

  useEffect(() => {
    window.addEventListener('pointerup', handlePointerUp);
    // Also listen for touchend globally to stop drawing
    window.addEventListener('touchend', handlePointerUp);
    return () => {
        window.removeEventListener('pointerup', handlePointerUp);
        window.removeEventListener('touchend', handlePointerUp);
    }
  }, []);

  const getCellColor = (val: number) => {
    const total = gridSize * gridSize;
    const hue = 200 + ((val / total) * 120); // Blue to Pink/Purple
    return `hsl(${hue}, 85%, 60%)`;
  };

  if (view === 'MENU') {
    return (
      <>
        <div className="absolute top-4 left-4 z-50">
           <button onClick={onBackToLauncher} className="flex items-center gap-2 px-4 py-2 bg-white/50 dark:bg-slate-800/50 backdrop-blur rounded-full text-slate-600 dark:text-slate-300 font-bold hover:bg-white dark:hover:bg-slate-700 transition-all shadow-sm">
              <span className="text-lg">←</span> Back
           </button>
        </div>

        <div className="flex flex-col items-center justify-center min-h-full p-4 w-full max-w-md mx-auto animate-in">
          <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border border-white/50 dark:border-slate-700 rounded-3xl shadow-2xl p-8 w-full text-center relative overflow-hidden transition-all group">

             {/* Decorative */}
             <div className="absolute inset-0 bg-gradient-to-br from-blue-50 via-purple-50 to-slate-50 dark:from-indigo-900/40 dark:via-purple-900/40 dark:to-slate-900/40 opacity-100"></div>
             <div className="absolute top-[-50px] right-[-50px] w-48 h-48 bg-fuchsia-500/10 dark:bg-fuchsia-500/20 rounded-full blur-3xl animate-pulse"></div>

             <div className="relative z-10">
                <div className="text-6xl mb-4">🌈</div>
                <h1 className="text-5xl font-black text-slate-800 dark:text-white mb-2 tracking-tight text-shadow-sm">
                  Number Slide
                </h1>
                <p className="text-slate-500 dark:text-slate-300 mb-10 font-medium text-lg">Connect the flow.</p>

                <div className="flex flex-col gap-4">
                  {[
                    { id: 'EASY', label: 'Easy', size: '4x4', color: 'from-green-500 to-emerald-600', icon: '🌱' },
                    { id: 'MEDIUM', label: 'Medium', size: '5x5', color: 'from-blue-500 to-indigo-600', icon: '💧' },
                    { id: 'HARD', label: 'Hard', size: '6x6', color: 'from-fuchsia-500 to-purple-600', icon: '🔥' }
                  ].map((item) => (
                    <button 
                      key={item.id}
                      onClick={() => startGame(item.id as Level)} 
